INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-k8cdd', 'k8cdd', 'Trabalho de campo com animais: procedimentos, riscos e biossegurança', NULL, '["Elba Regina Sampaio de Lemos","Paulo Sérgio D’Andrea"]', 'Editora FIOCRUZ', 'Brasil', 'SciELO Books', 'books', 2014, '2014-01-01', 'pt', 'book', 'medical-health', 'Ciencias Médicas y de la Salud', 'Medicine', 'O trabalho de muitos pesquisadores não se restringe ao laboratório. Aqueles que estudam zoonoses – doenças transmitidas por animais – estão entre os que costumam ir a campo. Suas atividades podem incluir expedições a campo para a captura de animais silvestres e coleta de amostras biológicas. No imaginário, algo associado ao senso de aventura. Na prática, tarefa fundamental à pesquisa e à vigilância ambiental e epidemiológica, exercida por profissionais continuamente expostos ao risco de infecção por bactérias, vírus e outros parasitas transmitidos por animais. Contribuir para a capacitação desses profissionais é o objetivo deste livro. A coletânea apresenta e discute diversos aspectos importantes para evitar acidentes e assegurar a proteção do profissional e do ambiente no trabalho de campo com animais, bem como os procedimentos necessários antes e depois da expedição.', '["zoonoses","biosafety","occupational risk","wildlife capture","biological sample collection","infection control","professional training"]', '10.7476/9786557080658', '9788575414460', 'https://books.scielo.org/id/k8cdd', NULL, NULL, 'https://books.scielo.org/id/k8cdd/cover/cover_thumbnail.jpeg', 180, 20, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-k8ng9', 'k8ng9', 'Os gramáticos latinos: Varrão, Quintiliano, Donato, Prisciano', NULL, '["Fábio Fortes","Julia Burghini"]', 'Editora da Unicamp', 'Brasil', 'SciELO Books', 'books', 2021, '2021-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'Pelo menos desde o final da Idade Média e a consolidação das línguas nacionais, o modelo gramatical greco-latino foi a base para a constituição das gramáticas das línguas modernas, inclusive de línguas não europeias, como o tupi- guarani. Isso ilustra a extensão, a complexidade e a riqueza do campo quando nos referimos a` gramática antiga. Com o objetivo de compreender as fontes latinas desse gênero, esta obra busca oferecer um panorama geral, com ênfase nos elementos teóricos e históricos da ars grammatica e em sua aplicação no contexto educacional romano. Além disso, propõe-se neste livro uma introdução ao pensamento e à obra dos mais importantes gramáticos latinos: Varrão, Quintiliano, Donato e Prisciano, perfazendo, assim, um arco temporal que vai do século I a.C. – com a obra de Varrão De lingua Latina – ao século VI d.C. – com a obra de Prisciano Institutiones grammaticae.', '["Latin grammarians","Latin grammar","Varron","Quintilian","Donatus","Priscian","Ars grammatica","Latin language teaching","history of grammar","De lingua Latina","Institutiones grammaticae"]', '10.7476/9788526815438', '9786586253863', 'https://books.scielo.org/id/k8ng9', NULL, NULL, 'https://books.scielo.org/id/k8ng9/cover/cover_thumbnail.jpeg', 155, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-k8s27', 'k8s27', 'Televisão digital: informação e conhecimento', NULL, '["María Cristina Gobbi","María Teresa Miceli Kerbauy"]', 'Editora UNESP', 'Brasil', 'SciELO Books', 'books', 2010, '2010-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Estamos a seis anos do alardeado "apagão digital", momento que demarca o fim do período transitório no processo de implantação da televisão digital terrestre no Brasil.2016 parece distante, porém nesse ínterim muito deve ser feito para que a mudança seja bem-sucedida e as centenas de milhares de lares brasileiros estejam equipados a receberem as transmissões apenas em sinal digital.Desde o início da transmissões digitais na Grande São Paulo, em dezembro de 2007, a implantação segue num ritmo constante, adentrando outras capitais e regiões metropolitanas do país, porém a adesão ainda é tímida.Os set-top boxes ainda são dispositivos de alto custo e baixo benefício, uma vez que dentre os diversos recursos potenciais disponibilizam até o momento apenas um, a alta definição de som e imagem.Para uma melhor compreensão do cenário atual e dos desafios que aguardam gestores, profissionais, pesquisadores e telespectadores é importante recordar a projeção feita pelo Centro de Pesquisa e Desenvolvimento em Telecomunicações (CPqD), primeiro encarregado de investigar as possibilidades dos diversos padrões', '["digital television","analog-to-digital transition","digital terrestrial television","set-top box","digital divide"]', '10.7476/9788579831010', '9788579831010', 'https://books.scielo.org/id/k8s27', 'https://books.scielo.org/id/k8s27/pdf/gobbi-9788579831010.pdf', NULL, 'https://books.scielo.org/id/k8s27/cover/cover_thumbnail.jpeg', NULL, 1, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-k8tdh', 'k8tdh', 'Tecnologia da conservação e da restauração - materiais e estruturas: um roteiro de estudos', NULL, '["Mário Mendonça de Oliveira"]', 'EDUFBA', 'Brasil', 'SciELO Books', 'books', 2011, '2011-01-01', 'pt', 'book', 'engineering-tech', 'Ingeniería y Tecnología', 'Engineering', 'Conservar a memória da produção arquitetônica humana é o tema deste livro, que apresenta, através de minucioso trabalho, uma simplificação de conteúdos de autores renomados, procurando facilitar a árdua tarefa do aprendizado científico, combinada com observações do dia-a-dia no laboratório e de canteiros de restauro brasileiros, nos quais os pontos destacados coincidem com os temas afrontados na prática do exercício profissional.', '["architectural conservation","architectural restoration","conservation materials","building structures","architectural heritage","restoration practice"]', '10.7476/9788523209230', '9788523209230', 'https://books.scielo.org/id/k8tdh', 'https://books.scielo.org/id/k8tdh/pdf/oliveira-9788523209230.pdf', NULL, 'https://books.scielo.org/id/k8tdh/cover/cover_thumbnail.jpeg', NULL, 7, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-k8vc4', 'k8vc4', 'Fazer-se no "Estado": uma etnografia sobre o processo de constituição dos "LGBT" como sujeitos de direitos no Brasil contemporâneo', NULL, '["Sílvia Aguião"]', 'EDUERJ', 'Brasil', 'SciELO Books', 'books', 2018, '2018-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'AGUIÃOFazer-se no "Estado": uma etnografia sobre o processo de constituição dos "LGBT" como sujeitos de direitos no Brasil contemporâneo A282 Aguião, Silvia.Fazer-se no "Estado" : uma etnografia sobre o processo de constituição dos "LGBT" como sujeitos de direitos no Brasil contemporâneo / Silvia Aguião.', '["LGBT","state formation","sexual and gender diversity","state and sexuality"]', '10.7476/9788575115152', '9788575115152', 'https://books.scielo.org/id/k8vc4', 'https://books.scielo.org/id/k8vc4/pdf/aguiao-9788575115152.pdf', NULL, 'https://books.scielo.org/id/k8vc4/cover/cover_thumbnail.jpeg', NULL, 28, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-k92cj', 'k92cj', 'Cartas vazias: leituras e leitores de um Centro de Referência de Down', NULL, '["Ana Maria Esteves"]', 'Editora UNESP', 'Brasil', 'SciELO Books', 'books', 2012, '2012-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'A partir do século XIX, as mulheres passaram a frequentar a escola, foram para a universidade, para o trabalho e para as ruas. Aprender a ler e a escrever trouxe para essas mulheres uma nova rotina de leitura: depois dos livros de reza, vieram os diários, os romances, as revistas femininas, a correspondência, os jornais. Nessa perspectiva, Ana Maria Esteves analisa as práticas de leitura de mulheres, mais particularmente os processos de apropriação da leitura e da escrita de professoras, de mães e de meninas portadoras da síndrome de Down em um Centro de Referência. Trata-se de um estudo de caso, de caráter etnográfico, que clarifica as trajetórias próprias de leitura dessas mulheres que, entre táticas e estratégias, apropriaram-se de maneiras de ler nas relações da oralidade com a cultura escrita e constituíram uma comunidade leitora. Para essas mulheres, a leitura assume uma presença singular no cotidiano e um significado especial em suas vidas.', '["Down syndrome","reading practices","women''s reading","reading communities","mothers of children with disabilities","teachers","special schools","women''s history"]', '10.7476/9786557144985', '9786557144985', 'https://books.scielo.org/id/k92cj', 'https://books.scielo.org/id/k92cj/pdf/esteves-9786557144985.pdf', NULL, 'https://books.scielo.org/id/k92cj/cover/cover_thumbnail.jpeg', NULL, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-k9jnh', 'k9jnh', 'A responsabilidade pela saúde: aspectos jurídicos', NULL, '["Hélio Pereira Dias"]', 'Editora FIOCRUZ', 'Brasil', 'SciELO Books', 'books', 1995, '1995-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Tomando como base a lei e interpretando-a na melhor tradição e conhecimento jurídicos, o autor examina a responsabilidade legal dos principais ''agentes'' do Sistema Único de Saúde - de um lado, o Estado, com seus três níveis de governo; de outro, os profissionais de saúde e os produtores de serviços e insumos - para, finalmente, deter-se na responsabilidade dos servidores públicos do SUS. Apesar do rigor técnico do tratamento destes temas, o livro destina-se não só aos advogados que militam na área, mas a todos os profissionais, administradores e pesquisadores envolvidos com o sistema de saúde.', '["health law","legal liability","Unified Health System (SUS)","state responsibility","healthcare workers","public servants liability","health system governance"]', '10.7476/9788575412749', '9788575412749', 'https://books.scielo.org/id/k9jnh', 'https://books.scielo.org/id/k9jnh/pdf/dias-9788575412749.pdf', NULL, 'https://books.scielo.org/id/k9jnh/cover/cover_thumbnail.jpeg', NULL, 2, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-k9kjv', 'k9kjv', 'Literatura e linguística: saberes acadêmicos além das fronteiras', NULL, '["Cristhiane Ferreguett","Deije Machado de Moura","João Evangelista do Nascimento Neto"]', 'LA Referencia (Red Federada de Repositorios Institucionales de Publicaciones Científicas)', 'Brasil', 'SciELO Books', 'books', 2016, '2016-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'O livro traz os resultados de pesquisa em nível de doutorado de 18 autores nas áreas de Literatura e Linguística e que apresentam reflexões e descobertas sobre a literatura baiana, brasileira e internacional, observando traços peculiares da construção cultural integradora que a literatura representa, além dos vários estudos linguísticos.', '["linguistics and literature","Bahian literature","Brazilian literature","world literature","cultural integration","literary studies","language studies"]', '10.7476/9786588211151', '9788578873240', 'https://books.scielo.org/id/k9kjv', 'https://books.scielo.org/id/k9kjv/pdf/ferreguett-9786588211151.pdf', 'https://books.scielo.org/id/k9kjv/epub/ferreguett-9786588211151.epub', 'https://books.scielo.org/id/k9kjv/cover/cover_thumbnail.jpeg', 464, 1, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-kbfwq', 'kbfwq', 'Perspectivas: Fernando Henrique Cardoso: idéias e atuação política', NULL, '["Eduardo Graeff","Fernando Henríque Cardoso"]', 'Centro Edelstein', 'Brasil', 'SciELO Books', 'books', 2008, '2008-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Com esta perspectiva, recuso a disjuntiva entre a afirmação absoluta de valores últimos (e os meus, como os de tantos brasileiros, são simples e diretos: igualdade social, participação democrática e liberdade efetiva), recuso a disjuntiva entre os valores últimos e a noção de que o político opera no campo concreto da violência, do cálculo racional na utilização dos meios e, portanto, do risco e do erro responsáveis.', '["Fernando Henrique Cardoso","political thought","political action","social equality","democratic participation","political freedom","political violence","political risk","Brazilian politics"]', '10.7476/9788599662670', '9788599662670', 'https://books.scielo.org/id/kbfwq', 'https://books.scielo.org/id/kbfwq/pdf/cardoso-9788599662670.pdf', NULL, 'https://books.scielo.org/id/kbfwq/cover/cover_thumbnail.jpeg', NULL, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-kbxjh', 'kbxjh', 'A escravidão no Brasil ensaio histórico-jurídico-social - Vol 1', NULL, '["Agostinho Marques Perdigão Malheiros"]', 'Centro Edelstein', 'Brasil', 'SciELO Books', 'books', 1866, '1866-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', '"A matéria deste Título e Parte 1.ª constitui por si só objeto digno de um tratado. Tão importante é ela; tão vasto o campo a percorrer. Muito mais, porque nossas leis são escassas e como que fugitivas a tal respeito, principalmente nas infinitas relações cíveis que ligam os escravos e os senhores entre si e com terceiros, nas questões cardiais de estado de liberdade ou escravidão, e em tantas outras que emergem constantemente. Mas nós nos circunscreveremos no quadro correspondente ao plano deste nosso trabalho, procurando todavia fazê-lo por forma, que ao menos os princípios fundamentais e de maior freqüência prática sejam consignados de um modo claro e metódico. O desenvolvimento ficará ao estudo e gosto de cada um. O assunto é quase inesgotável."', '["slavery","slave law","slave status","master-slave relations","civil law","freedom and bondage","Brazilian law","history of slavery"]', '10.7476/9788579820724', '9788579820724', 'https://books.scielo.org/id/kbxjh', 'https://books.scielo.org/id/kbxjh/pdf/malheiros-9788579820724.pdf', NULL, 'https://books.scielo.org/id/kbxjh/cover/cover_thumbnail.jpeg', NULL, 45, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-kcbpq', 'kcbpq', 'Educomunicação no contexto pandêmico', 'desafios do ensino remoto', '["Adilson Odair Citelli"]', 'Editus', 'Brasil', 'SciELO Books', 'books', 2024, '2024-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'O livro está inserido nos estudos que envolvem os vínculos da comunicação com a educação e resulta de pesquisa realizada junto a docentes do ensino fundamental brasileiro durante a Covid-19. O objetivo da investigação e da organização do volume foi verificar, ao mesmo tempo, a crise gerada pela circulação do vírus e as alternativas encontradas para dar continuidade ao trabalho educativo, em grande parte realizado na modalidade remota ou híbrida. Conquanto o livro decorra dos dados obtidos durante a pandemia, nele serão apresentadas questões e análises de plena atualidade nas escolas, a exemplo da (des)valorização docente, dos problemas relacionados aos usos das redes digitais e dos meios de comunicação.', '["educommunication","COVID-19 pandemic","remote teaching","hybrid learning","primary school teachers","teacher devaluation","instructional media"]', '10.7476/9788574556031', '9788574555867', 'https://books.scielo.org/id/kcbpq', 'https://books.scielo.org/id/kcbpq/pdf/citelli-9788574556031.pdf', NULL, 'https://books.scielo.org/id/kcbpq/cover/cover_thumbnail.jpeg', NULL, 1, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-kcdyg', 'kcdyg', 'Direito e ecologia: investigações do Programa de Pós-graduação em Direito da UFBA', 'investigações do Programa de Pós-graduação em Direito da UFBA', '["Julio Cesar de Sá da ROCHA","Fábia Ribeiro Carvalho de Carvalho","Marcelo Bloizi Iglesias"]', 'EDUFBA', 'Brasil', 'SciELO Books', 'books', 2026, '2026-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Este livro reúne pesquisas empreendidas no componente Direito e Ecologia do Programa de Pós-Graduação em Direito da Universidade Federal da Bahia (PPGD/UFBA), com a participação do Programa de Pós-Graduação em Geografia da UFBA, do Programa de Pós-Graduação em Relações Internacionais, também da UFBA, do Programa de Pós-Graduação em Ciências Ambientais da Universidade do Estado do Pará, do Programa de Mestrado em Constitucionalismo e Direitos na Amazônia da Universidade Federal do Amazonas e do Programa de Pós-Graduação em Ciências Jurídicas da Universidade Federal da Paraíba. A obra aprofunda a relação entre os campos jurídico e ecológico buscando responder questões atuais e prementes da sociedade diante da crise ambiental e suas consequências para a humanidade e meio ambiente.', '["law and ecology","environmental law","environmental crisis","environmental protection"]', '10.7476/9786556309538', '9786556308432', 'https://books.scielo.org/id/kcdyg', 'https://books.scielo.org/id/kcdyg/pdf/rocha-9786556309538.pdf', NULL, 'https://books.scielo.org/id/kcdyg/cover/cover_thumbnail.jpeg', NULL, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-kcdz2', 'kcdz2', 'Um convite à utopia', NULL, '["Cidoval Morais de Sousa"]', 'EDUEPB', 'Brasil', 'SciELO Books', 'books', 2016, '2016-01-01', 'other', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'A coleção Um Convite à Utopia insere-se no contexto das comemorações dos 500 anos do lançamento do livro A Utopia (1516), de Thomas Morus. Trata-se de projeto editorial de natureza pública e coletiva, capitaneado pela Editora da Universidade Estadual da Paraíba (EDUEPB), com apoio da Associação Brasileira de Editoras Universitárias (ABEU) e uma série de instituições acadêmicas, científicas e culturais nacionais e estrangeiras. Pretende-se, de um lado, resgatar obras/textos que marcaram a construção da utopia como um projeto de contraposição a um mundo injusto e desigual; e, de outro, estimular a atualização da utopia, a partir de construções inéditas e provocadoras, articuladas em uma rede de esperanças. A ideia é que cada autor ou coletivo de autores, a partir de seu lugar de vida/mundo, produza um ensaio instigante, recuperando a necessidade de despertar do sono profundo em que se encontra o espírito utópico.', '["utopia","Thomas More","utopianism","social justice","inequality"]', '10.7476/9788578794880', '9788578794880', 'https://books.scielo.org/id/kcdz2', 'https://books.scielo.org/id/kcdz2/pdf/sousa-9788578794880.pdf', NULL, 'https://books.scielo.org/id/kcdz2/cover/cover_thumbnail.jpeg', NULL, 2, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-kckv8', 'kckv8', 'Congresso remoto: a experiência legislativa brasileira em tempos de pandemia', NULL, '["Fabiano Guilherme Mendes Santos"]', 'EDUERJ', 'Brasil', 'SciELO Books', 'books', 2021, '2021-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'A experiência legislativa brasileira durante a atual crise sanitária causada pelo Covid- 19 não apenas configura elemento político básico de conjuntura, mas, também, fenômeno de grande interesse no debate acadêmico sobre a inserção do Congresso no processo decisório de produção de políticas públicas. Desde os estudos pioneiros de Argelina Figueiredo e Fernando Limongi nos anos 90 do século passado, algum consenso se formou na literatura especializada sobre a liderança do Executivo, o presidente e seus ministros, na organização da agenda a tramitar no Congresso, tanto no que diz respeito ao ritmo de tramitação, quanto no que tange ao conteúdo das matérias.', '["COVID-19 pandemic","Brazilian National Congress","legislative process","public policy formulation","executive-legislative relations","agenda setting","legislative agenda"]', '10.7476/9786588808122', '9786588808122', 'https://books.scielo.org/id/kckv8', 'https://books.scielo.org/id/kckv8/pdf/santos-9786588808122.pdf', NULL, 'https://books.scielo.org/id/kckv8/cover/cover_thumbnail.jpeg', NULL, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-kcv6j', 'kcv6j', 'Políticas públicas para a Educação Infantil no Brasil (1990-2001)', NULL, '["Jani Alves da Silva Moreira","Ângela Mara de Barros Lara"]', 'EDUEM', 'Brasil', 'SciELO Books', 'books', 2012, '2012-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Este livro é resultado de uma pesquisa de análise documental desenvolvida no Programa de Pós-Graduação em Educação da Universidade Estadual de Maringá no período 2004-2006. A idéia das autoras em abordar o tema política educacional para a Educação Infantil no período 1990 a 2001 na imprensa periódica surgiu da preocupação em compreender como os professores-leitores apreenderam o discurso veiculado sobre a configuração das políticas nesse período de intensas reformas educacionais. Desta maneira, levantar a forma com que os textos e suas enunciações reproduziram esse contexto e colaborar para a implementação das políticas é essencial. As duas revistas escolhidas para essa assimilação foram selecionadas porque são as mais lidas e conhecidas pelos professores da Educação Infantil no Brasil. O fato de uma ser de cunho mercadológico e a outra de cunho oficial foi um aspecto propositalmente estabelecido, pois havia o interesse em diferenciá-las quanto à maneira que representam as políticas educacionais nas enunciações. Foi tomado como universo representativo para a análise, as enunciações das revistas Nova Escola (Editora Abril) e Criança (MEC), alguns documentos de organismos internacionais e documentos oficiais. Distinguiu-se que as categorias discursivas que compõem a trama de conceitos politicamente estratégicos para a Educação Infantil foram a Qualidade, a Descentralização e a Focalização. Com o intuito de evidenciar os vínculos das análises ao contexto macroeconômico, as políticas para a Educação Infantil foram abordadas por meio da mediação com a contextualização da mundialização do capital. No primeiro capítulo do livro, apresentamos a Educação Infantil inserida na contextualização histórica da atual fase de desenvolvimento do capital, a mundialização econômica, bem como a redefinição do papel do Estado e os ajustes neoliberais que determinaram as políticas públicas educacionais na década de 1990. No segundo capítulo, discutimos sobre as políticas para a Educação Infantil tendo como base a história desta etapa de ensino no Brasil e as orientações políticas das agências internacionais tais como a UNESCO, CEPAL e o Banco Mundial. Apresentamos também a estrutura políticas dos documentos oficiais destinadas a regulamentar a Educação Infantil no Brasil. A análise das categorias políticas Qualidade, Descentralização e Focalização foi o foco do terceiro capítulo. Tal abordagem colaborou para evidenciar que as políticas de ajustes neoliberais propaladas pelas agências internacionais foram acopladas nas políticas públicas destinadas à Educação Infantil e, também, foram estrategicamente veiculadas nos textos das revistas dirigidas aos profissionais dessa área. O enfoque para as análises foi pautado na concepção de que o texto é discurso produzido no embate da luta de classes. A análise mostrou que o caráter dos textos veiculados sugeriu uma continuidade aos ajustes neoliberais estruturais na educação infantil.', '["early childhood education policy","public policy","educational policy discourse","Nova Escola magazine","educational reform","neoliberalism","internationalization of capital","decentralization","educational quality","international organizations","role of the state","teacher perceptions"]', '10.7476/9788576285854', '9788576285854', 'https://books.scielo.org/id/kcv6j', 'https://books.scielo.org/id/kcv6j/pdf/moreira-9788576285854.pdf', NULL, 'https://books.scielo.org/id/kcv6j/cover/cover_thumbnail.jpeg', NULL, 5, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-kdqc2', 'kdqc2', 'Imagens reveladas, diferenças veladas: relações de gênero na dinâmica do espaço público na cidade do Salvador, Bahia', NULL, '["Claudia Andrade Vieira"]', 'LA Referencia (Red Federada de Repositorios Institucionales de Publicaciones Científicas)', 'Brasil', 'SciELO Books', 'books', 2017, '2017-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'A obra problematiza o lugar das mulheres no espaço público da cidade em uma perspectiva multidisciplinar. Quais as fronteiras, limites e possibilidades das mulheres na relação com o espaço público? Quais os lugares possíveis para o desempenho das atividades profissionais, nas primeiras décadas do século XX? Ao recuperar o passado para compreender melhor os problemas vivenciados por mulheres na sua relação com a cidade no presente, pretende-se contribuir para a construção de uma cidade mais democrática, o que implica torná-la sujeitos, voz ativa na produção do espaço urbano.', '["gender relations","public space","women in cities","Salvador, Bahia","early 20th century","women''s professional activity","urban space","democratic city","women''s history"]', '10.7476/9786588211359', '9788578873394', 'https://books.scielo.org/id/kdqc2', 'https://books.scielo.org/id/kdqc2/pdf/vieira-9786588211359.pdf', 'https://books.scielo.org/id/kdqc2/epub/vieira-9786588211359.epub', 'https://books.scielo.org/id/kdqc2/cover/cover_thumbnail.jpeg', 359, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-kdr44', 'kdr44', 'Docência em ambientes de aprendizagem online', NULL, '["Iolanda Bueno de Camargo Cortelazzo"]', 'EDUFBA', 'Brasil', 'SciELO Books', 'books', 2009, '2009-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'O livro Docência em ambientes de aprendizagem online afasta-se da realidade imposta pela “moderna renascença” das práticas pedagógicas universitárias tradicionais, mesmo quando são utilizados os mais diferenciados e inovadores recursos midiáticos. Como todas as demais áreas do conhecimento, a Educação mudou muito nos últimos anos. Porém, a mudança não se dá de forma decisiva no plano dos sistemas e hierarquias estruturadas das nossas escolas.', '["virtual learning environments","university teaching","teaching practice","educational technology","educational change","higher education"]', '10.7476/9788523211844', '9788523206666', 'https://books.scielo.org/id/kdr44', NULL, NULL, 'https://books.scielo.org/id/kdr44/cover/cover_thumbnail.jpeg', 176, 1, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-kds2t', 'kds2t', 'Desacordos: ensaios em epistemologia', 'ensaios em epistemologia', '["Nicolás Francisco Lo Guercio","Felipe Rocha Lima Santos","Waldomiro José da Silva Filho"]', 'EDUFBA', 'Brasil', 'SciELO Books', 'books', 2024, '2024-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'O livro busca oferecer ao público uma das primeiras coletâneas em língua portuguesa sobre a epistemologia do desacordo, campo de pesquisa relativamente recente e com uma literatura bastante ampla. Os capítulos deste livro abarcam vários aspectos do debate atual sobre desacordos, tantos nos seus aspectos lógicos, semânticos e epistemológicos, visando permitir que estudantes sem conhecimento prévio possam ser introduzidos ao tema, assim como que pesquisadores que trabalham com esse tema possam avançar em suas pesquisas, discutindo questões que se encontram no estado da arte da epistemologia do desacordo.', '["epistemology of disagreement","disagreement","epistemic logic","epistemic justification","collective epistemology"]', '10.7476/9786556308999', '9786556306476', 'https://books.scielo.org/id/kds2t', 'https://books.scielo.org/id/kds2t/pdf/lo-9786556308999.pdf', NULL, 'https://books.scielo.org/id/kds2t/cover/cover_thumbnail.jpeg', NULL, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-kfvcr', 'kfvcr', 'The Latin American Challenge: Social Cohesion and Democracy', NULL, '["Bernardo Sorj","Danilo Martuccelli"]', 'Centro Edelstein', 'Brasil', 'SciELO Books', 'books', 2008, '2008-01-01', 'en', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'In order to understand the dynamics of constructing social cohesion in Latin America we must bring a new perspective to approaches that focus mainly on the pervasive social problems on the continent.While it is true that disregarding these problems would be tantamount to adopting a conservative posture, we must by the same token identify the region''s wealth of positive resources for integration and sociocultural creativity in order to discern how our societies generate social cohesion and how this infl uences democracy building.1 Our continent is generally free of strong tensions between the state and the national culture and, compared to most regions of the world, is endowed with a high degree of linguistic and religious homogeneity as well as a deeply-rooted tradition of secularism and inter-religious coexistence.Th e conquest, followed by the nation states, destroyed the political and religious foundations that might have fostered the emergence of political-cultural movements based on alternative values to modernity.At the same time, the peoples of most Latin American countries self-identify as mestizos, or people of mixed descent, although this has not ruled out racism in various forms.Fratricidal struggles have not occurred among ethnic or religious communities and the inter-state wars of the 1 See Annex 1 for a discussion of the concept of social cohesion as it is used in the Latin American context (Discussion of the concept of social cohesion). Systems of Church -State Relations in Latin AmericaHas an offi cial church God in the Constitution Separation of Church and State with certain privileges for the Catholic Church God in the Constitution Separation of Church and State God in the Constitution Argentina', '["social cohesion","democracy building","Latin America","church-state relations","secularism","interreligious coexistence","mestizaje","racism","nation-building","social integration"]', '10.7476/9788579820816', '9788579820816', 'https://books.scielo.org/id/kfvcr', 'https://books.scielo.org/id/kfvcr/pdf/sorj-9788579820816.pdf', NULL, 'https://books.scielo.org/id/kfvcr/cover/cover_thumbnail.jpeg', NULL, 13, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-kfzzs', 'kfzzs', 'Microquímica do poder: uma análise genealógica dos psicofármacos contemporâneos', NULL, '["Sílvio de Azevedo Soares"]', 'Editora UNESP', 'Brasil', 'SciELO Books', 'books', 2022, '2022-01-01', 'pt', 'book', 'medical-health', 'Ciencias Médicas y de la Salud', 'Psychology', 'Esta obra apresenta uma pesquisa qualitativa em fontes bibliográficas e fílmica para traçar as singularidades políticas e subjetivas dos psicofármacos. O autor apresenta um jogo de contrastes, uma comparação entre as relações de poder-saber-sujeição que atravessam a psiquiatria em dois intervalos históricos distintos: a constituição e a consolidação da psiquiatria na França do século XIX e a medicalização das práticas e saberes psiquiátricos e, em especial, o uso asilar de substâncias químicas com algum efeito psicoativo (denominadas de de “protopsicofármacos”) na atualidade, sobretudo o Prozac, o antidepressivo mais receitado no planeta.', '["psychotropic drugs","genealogy of power","history of psychiatry","medicalization","asylum","fluoxetine","antidepressants","psychoactive substances","subjectivity","19th-century France"]', '10.7476/9786559542482', '9786559542482', 'https://books.scielo.org/id/kfzzs', 'https://books.scielo.org/id/kfzzs/pdf/soares-9786559542482.pdf', NULL, 'https://books.scielo.org/id/kfzzs/cover/cover_thumbnail.jpeg', NULL, 1, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-kgcbj', 'kgcbj', 'A paixão do negativo', NULL, '["Vladimir Safatle"]', 'Editora UNESP', 'Brasil', 'SciELO Books', 'books', 2006, '2006-01-01', 'pt', 'book', 'medical-health', 'Ciencias Médicas y de la Salud', 'Psychology', 'Construindo o espaço conceitual comum a dois pensamentos que se ignoraram durante meio século, o de Lacan e o de Adorno, Vladimir Safatle faz muito mais que uma aproximação interessante. Ele confronta duas filosofias apoiadas, cada uma, em uma prática: a cura psicanalítica para um, a criação artística para outro; assim como obriga o pensamento a se interrogar sobre o que um sistema, que tem sua densidade própria de teoria, deve à prática ou à experiência que ele privilegia.', '["Jacques Lacan","Theodor W. Adorno","psychoanalysis","artistic creation","negativity","theory and practice","psychoanalytic cure","artistic practice"]', '10.7476/9788539303335', '9788571396395', 'https://books.scielo.org/id/kgcbj', NULL, NULL, 'https://books.scielo.org/id/kgcbj/cover/cover_thumbnail.jpeg', 336, 39, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-kgkv6', 'kgkv6', 'Políticas públicas no Brasil', NULL, '["Gilberto Hochman","Marta Arretche","Eduardo Cesar Leão Marques"]', 'Editora FIOCRUZ', 'Brasil', 'SciELO Books', 'books', 2007, '2007-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'As pesquisas em políticas públicas no Brasil têm demonstrado crescente amadurecimento, o que pode ser comprovado nesta coletânea. Resultado de estudos apresentados no Grupo de Trabalho em Políticas Públicas da Associação Nacional de Pós-Graduação e Pesquisa em Ciências Sociais (Anpocs), o livro reúne 12 artigos que dão conta de uma diversidade de enfoques e agendas. A obra discute questões conceituais, processos decisórios, condicionantes e efeitos das políticas públicas, bem como sua implementação e avaliação. Os primeiros artigos trazem o estado da arte das pesquisas em políticas públicas, perspectivas teóricas e lições da literatura contemporânea. Em seguida, são apresentadas investigações sobre a descentralização das políticas de saúde, a participação popular e a interação entre sindicalismo e governo na reforma previdenciária brasileira, assim como reflexões sobre a estrutura e o comportamento dos gastos sociais. Por fim, os artigos trazem análises sobre a Reforma Sanitária e os programas de erradicação da malária e da varíola, além de experiências no campo da educação.', '["public policy research","Brazilian public policy","policy implementation","policy evaluation","decision-making","citizen participation","social spending","Reforma Sanitária","malaria eradication","smallpox eradication","education policy"]', '10.7476/9788575413500', '9788575411247', 'https://books.scielo.org/id/kgkv6', NULL, NULL, 'https://books.scielo.org/id/kgkv6/cover/cover_thumbnail.jpeg', 398, 46, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-kgsw8', 'kgsw8', 'Representações, jornalismo e a esfera pública democrática', NULL, '["Murilo César Soares"]', 'Editora UNESP', 'Brasil', 'SciELO Books', 'books', 2009, '2009-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Os textos deste livro analisam as representações da política e da mídia nas sociedades democráticas contemporâneas. A primeira parte da obra é dedicada aos aspectos cognitivos e retóricos do jornalismo e sua influência sobre as audiências. Na seqüência são examinadas as acepções da democracia e o papel do jornalismo na constituição das sociedades democráticas e na expansão dos direitos de cidadania. A parte final do livro trata do lugar ocupado pelos meios de comunicação nas eleições brasileiras de 1989, 1994, 1998, 2002 e 2006. Aliando reflexão teórica e análise de situações concretas, esta obra salienta as conexões entre representações, jornalismo e democracia', '["political representation","journalism","democratic public sphere","media and democracy","audience effects","conceptions of democracy","citizenship rights","election coverage"]', '10.7476/9788579830181', '9788579830181', 'https://books.scielo.org/id/kgsw8', 'https://books.scielo.org/id/kgsw8/pdf/soares-9788579830181.pdf', NULL, 'https://books.scielo.org/id/kgsw8/cover/cover_thumbnail.jpeg', NULL, 18, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-kgw7y', 'kgw7y', 'Poliomielite no Brasil: do reconhecimento da doença ao fim da transmissão', NULL, '["João Baptista Risi"]', 'Editora FIOCRUZ', 'Brasil', 'SciELO Books', 'books', 2019, '2019-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'Uma doença conhecida no Brasil desde o início do século XX, mas que só chamou a atenção da opinião pública nos anos 1950, quando epidemias atingiram algumas das principais cidades do país. Somente a partir de 1980, a poliomielite - a partir de intervenções e iniciativas internacionais de controle e erradicação - passou a ser combatida pelo setor Saúde no Brasil. O livro aborda essa longa trajetória, que passa pelo reconhecimento da doença, por estratégias de vacinação e processos de contínua aprendizagem nos campos político-institucional, tecnocientífico e social. Organizado por João Baptista Risi Junior - especialista em vigilância epidemiológica e ex-secretário nacional de Ações Básicas de Saúde do Ministério da Saúde -, o volume aborda também aspectos fundamentais dessa jornada, como a potencialização das ações de saúde e campanhas de vacinação. A mobilização científica mundial e o engajamento institucional de Bio-Manguinhos - unidade da Fiocruz responsável por pesquisa, inovação e pela produção de vacinas e biofármacos que atendem às demandas da saúde pública no Brasil - também são questões de destaque ao longo dos nove capítulos da obra, escritos por pesquisadoras e pesquisadores das áreas de medicina, epidemiologia e saúde pública. "A experiência prévia de Bio-Manguinhos/Fiocruz em processos de incorporação tecnológica contribuiu para a formulação de um conceito que se tornaria uma política de Estado: a do complexo econômico-industrial de saúde", ressalta, no prefácio, a presidente da Fiocruz, Nísia Trindade Lima. Segundo Carla Domingues, coordenadora geral do Programa Nacional de Imunizações do Ministério da Saúde, o movimento de eliminação da poliomielite no Brasil encorajou a iniciativa de erradicação mundial da doença, "deixando importante legado para a saúde pública brasileira, em diversos campos do conhecimento".', '["poliomyelitis","polio eradication","polio vaccination campaigns","Bio-Manguinhos","Fiocruz","health policy","disease surveillance","international health cooperation","health technology transfer","history of public health"]', '10.7476/9786557080627', '9788575416310', 'https://books.scielo.org/id/kgw7y', NULL, NULL, 'https://books.scielo.org/id/kgw7y/cover/cover_thumbnail.jpeg', 496, 1, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-kgx3n', 'kgx3n', 'O problema da motivação moral em Kant', NULL, '["Hélio José dos Santos Souza"]', 'Editora UNESP', 'Brasil', 'SciELO Books', 'books', 2009, '2009-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'A vontade diante de uma encruzilhada 17 2 Os princípios da razão prática 43 3 Dos motivos determinantes da vontade 81 4 Interesse da razão e liberdade 109 Considerações finais 131 Referências bibliográficas 139Bibliografia suplementar 140 O PROBLEMA DA MOTIVAÇÃO MORAL EM KANT 11 O que é mais interessante neste livro é que uma questão técnica kantiana é transformada em uma questão apaixonante.Não apenas a descrição da coisa em si moral oriunda da racionalidade e sua manifestação por meio de imperativos categóricos que se impõem pela reflexão, mas o que motiva o homem a agir moralmente.O medo da punição, a universalidade da razão, o desejo de felicidade, o equilíbrio psicológico, os benefícios materiais etc. não são em si suficientes para compreender a riqueza e diversidade da experiência humana.A questão é como é possível nos tornarmos homens melhores apesar de sermos homens.Hélio José apresenta ainda a discussão destes problemas por alguns dos grandes intérpretes da obra de Kant, o que enriquece filosoficamente a análise e as alternativas pertinentes.Este é um daqueles trabalhos aparentemente acadêmicos que podem estabelecer a vocação filosófica de seus leitores: a reflexão sobre o que está em jogo é por si só um prazeroso exercício do filosofar.', '["Immanuel Kant","moral motivation","practical reason","categorical imperative","wills","moral psychology","freedom","rationality","Kantian interpretation"]', '10.7476/9788579830167', '9788579830167', 'https://books.scielo.org/id/kgx3n', 'https://books.scielo.org/id/kgx3n/pdf/souza-9788579830167.pdf', NULL, 'https://books.scielo.org/id/kgx3n/cover/cover_thumbnail.jpeg', NULL, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-khqkb', 'khqkb', 'O trabalho no mundo contemporâneo: fundamentos e desafios para a saúde', 'fundamentos e desafios para a saúde', '["Ialê Falleiros Braga","Muza Clara Chaves Velasques","Márcia Valéria Cardoso Morosini","Renata Reis Cornélio Batistella","Júlio César França Lima","Daiana Crús Chagas"]', 'Editora FIOCRUZ', 'Brasil', 'SciELO Books', 'books', 2016, '2016-01-01', 'pt', 'book', 'medical-health', 'Ciencias Médicas y de la Salud', 'Medicine', 'Aprofundar a discussão sobre os fundamentos do trabalho no Brasil contemporâneo, relacionando-a ao trabalho e à educação dos trabalhadores na área da saúde: esta é proposta do presente livro, que completa uma trilogia sobre trabalho, educação e saúde, junto com os títulos Fundamentos da Educação Escolar no Brasil Contemporâneo (2006) e Estado, Sociedade e Formação Profissional em Saúde (2008). Os três volumes têm como objetivo “elucidar o processo histórico que vem conformando o campo do trabalho, da educação e da saúde no Brasil segundo a perspectiva da luta de classes contemporânea, constituindo materiais que podem contribuir para a organização e o acúmulo de forças da classe trabalhadora”. A nova coletânea está organizada em cinco eixos temáticos: o trabalho no mundo contemporâneo, as mudanças no mundo do trabalho e seus impactos na área da saúde; os trabalhadores da saúde e seus desafios e lutas; o trabalho e a educação profissional em saúde; e a saúde do trabalhador e a saúde do trabalhador da saúde. Ao longo dos capítulos, apresenta-se o trabalho no mundo contemporâneo nos seus aspectos políticos, econômicos, sociais e culturais, com aportes de conhecimentos da sociologia do trabalho, da história social, do serviço social, da saúde coletiva, da ergonomia e do trabalho e da educação em saúde. Destaca-se como “preocupação central a reflexão sobre o trabalho e a educação profissional em saúde no campo de lutas pela emancipação das formas e relações de exploração e dominação vigentes”.', '["contemporary world of work","healthcare workers","health education","health professions education","employee health","class struggle","labor exploitation","sociology of work","social history","collective health","human factors"]', '10.7476/9786557082935', '9788575414811', 'https://books.scielo.org/id/khqkb', 'https://books.scielo.org/id/khqkb/pdf/braga-9786557082935.pdf', NULL, 'https://books.scielo.org/id/khqkb/cover/cover_thumbnail.jpeg', NULL, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-khsnr', 'khsnr', 'No limiar do desconhecido: reflexões acerca do objeto no teatro de Tadeusz Kantor', NULL, '["Wagner Francisco Araújo Cintra"]', 'Editora UNESP', 'Brasil', 'SciELO Books', 'books', 2012, '2012-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'Tadeusz Kantor (Polônia, 1915-1990) foi um dos mais importantes homens do teatro do século XX, e seu trabalho, fortemente influenciado pelas artes plásticas, principalmente pelas vanguardas do início do século passado (Construtivismo, Bauhaus, Dadaísmo, Surrealismo, Expressionismo). Seu teatro é marcado pela ocorrência de imagens fortes e perturbadoras, principalmente a partir da encenação de A classe morta (1975). Entre os vários elementos de sustentação, os objetos (sejam reais, cotidianos ou construídos exclusivamente para finalidade cênica) transpassam toda a sua obra. No entanto, Kantor nunca explicou satisfatoriamente essa ocorrência em seu teatro. Nesse sentido, este livro trata da reflexão sobre o objeto no teatro de Kantor, tendo como tema central a demonstração do objeto como elemento responsável pela criação de outra realidade de tempo e espaço onde seus espetáculos acontecem.', '["Tadeusz Kantor","stage objects","avant-garde theatre","constructivism","Bauhaus","Dada","surrealism","Expressionism","stage design","Polish theatre"]', '10.7476/9786557145012', '9786557145012', 'https://books.scielo.org/id/khsnr', 'https://books.scielo.org/id/khsnr/pdf/cintra-9786557145012.pdf', NULL, 'https://books.scielo.org/id/khsnr/cover/cover_thumbnail.jpeg', NULL, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-khwkr', 'khwkr', 'PT - A lógica da diferença: o partido dos trabalhadores na construção da democracia brasileira', NULL, '["Margaret Elizabeth Keck"]', 'Centro Edelstein', 'Brasil', 'SciELO Books', 'books', 2010, '2010-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Este livro é o estudo de uma anomalia. É o alerta que Margaret Keck faz logo no início do livro. Porque a existência do Partido dos Trabalhadores é uma completa irregularidade e anormalidade no âmbito do sistema partidário brasileiro e na história política brasileira. Pela primeira vez, um partido podia se reivindicar uma presença sólida na classe operária e propor um programa que traduzisse com clareza essa representação. [trecho retirado do prefácio do livro]', '["Workers'' Party (PT)","PT","Brazilian democracy","political parties","party system","working-class representation","political representation","Party building","Brazilian political history"]', '10.7476/9788579820298', '9788579820298', 'https://books.scielo.org/id/khwkr', 'https://books.scielo.org/id/khwkr/pdf/keck-9788579820298.pdf', NULL, 'https://books.scielo.org/id/khwkr/cover/cover_thumbnail.jpeg', NULL, 32, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-kj4jy', 'kj4jy', 'Economía popular y solidaria: ¿realidad o utopía?. Caracterización de las entidades de fomento', NULL, '["Ana Castro Medina"]', 'Editorial Abya-Yala', 'Ecuador', 'SciELO Books', 'books', 2018, '2018-01-01', 'es', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Ecuador es un escenario en el que se desarrollan múltiples experiencias relacionadas con la Economía Popular y Solidaria —EPS—, es un laboratorio vivo que aún en contextos complejos genera redes y tejidos desde la reciprocidad, el don y la gratuidad. Comprender este entramado precisa de aportes que inviten a la reflexión y a la construcción de renovadas políticas públicas e instituciones. Este trabajo constituye un esfuerzo por caracterizar la institucionalidad pública del sector de la EPS, es una aproximación que explora sus prácticas desde el año 2013, en particular las entidades de fomento. Las principales conclusiones indican que la estructura organizacional pública, creada desde el rol regulador del Estado, visibiliza y apoya algunas de las expresiones solidarias, empero su comprensión y contribución aún es limitada en relación a las expectativas de quienes viven y activan cotidianamente la economía solidaria en el país.', '["popular and solidarity economy","solidarity economy","public policy","reciprocity","gift economy","Ecuador"]', '10.7476/9789978104903', '9789978104903', 'https://books.scielo.org/id/kj4jy', 'https://books.scielo.org/id/kj4jy/pdf/castro-9789978104903.pdf', NULL, 'https://books.scielo.org/id/kj4jy/cover/cover_thumbnail.jpeg', NULL, 13, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-kjc63', 'kjc63', 'Hip-hop feminista? Convenções de gênero e feminismos no movimento Hip-hop soteropolitano', NULL, '["Rebeca Sobral Freire"]', 'EDUFBA', 'Brasil', 'SciELO Books', 'books', 2018, '2018-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Nesse estudo, a autora analisa a existência de um hip-hop feminista jovem, negro, soteropolitano, a partir da perspectiva das mulheres inseridas nesse movimento, e interessa-se por compreender quais são suas concepções acerca do feminismo investigando se há e de que forma influenciam as experiências dessas mulheres diante de um contexto que dialoga com a cultura política local vigente. Esta obra faz parte da Coleção Bahianas que, desde sua primeira edição, em 1997, mostrou-se desafiadora e mantem-se como espaço de socialização de estudos teóricos e empíricos. Esses estudos buscam questionar os estereótipos e as convenções e de gênero que inscrevem lugares e posições distintas para mulheres e homens', '["gender norms","feminism","women in hip hop","Black women","political culture","gender stereotypes"]', '10.7476/9788523218621', '9788523218621', 'https://books.scielo.org/id/kjc63', 'https://books.scielo.org/id/kjc63/pdf/freire-9788523218621.pdf', NULL, 'https://books.scielo.org/id/kjc63/cover/cover_thumbnail.jpeg', NULL, 6, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-kk862', 'kk862', 'Ectoparasitofauna brasileira de importância veterinária. Volume 2. Acarofauna de Importância Veterinária: Parasitiformes - Mesostigmata', 'Parasitiformes - Mesostigmata', '["Darci Moraes Barros‐Battesti","Rosangela Zacarias Machado","Marcos Rogério André"]', 'Colégio Brasileiro de Parasitologia Veterinária (CBPV)', 'Brasil', 'SciELO Books', 'books', 2024, '2024-01-01', 'pt', 'book', 'agricultural-sciences', 'Ciencias Agrícolas y Veterinaria', 'Agricultural and Biological Sciences', 'Dentre as ordens que compõem a superordem Parasitiformes, Mesostigmata e Ixodida (= Metastigmata) são as que apresentam um papel significante sob o ponto de vista médico e veterinário. Esse livro (volume 2) faz parte da obra “Ectoparasitofauna brasileira de importância veterinária”. Os ácaros Mesostigmata que parasitam animais vertebrados (e, invertebrados, no caso de Varroidae), que ocorrem no Brasil e em países vizinhos, estão bem detalhados e ilustrados em 12 capítulos ao longo desse livro. Ao final, apresentamos um glossário de terminologias para auxiliar no uso das chaves de identificação das espécies. Desejamos um ótimo aproveitamento e que a obra seja útil a todos!', '["Mesostigmata","acarofauna","ectoparasites","Varroidae","Parasitiformes","ticks","veterinary importance","identification key"]', '10.7476/9786583181664', '9786584598751', 'https://books.scielo.org/id/kk862', NULL, NULL, 'https://books.scielo.org/id/kk862/cover/cover_thumbnail.jpeg', 273, 1, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-kkc7r', 'kkc7r', 'Bêabá na Bahia guia turístico', NULL, '["José Valladares"]', 'EDUFBA', 'Brasil', 'SciELO Books', 'books', 2012, '2012-01-01', 'es', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Custódia de ouro, do convento do Desterro p. 71 Rua do Bispo p. 73 Cais da rampa do Mercado p. 78 Feira de Água de Meninos p. 79 Maciel de Baixo p. 81 Convento de Santa Teresa p. 91 Saint George''s Church p. 93 Rua de São Francisco, vista de cima p. 98 Interior do bar Anjo Azul p. 102 Hospital Juliano Moreira, antigo solar da Boa Vista p. 106 Oratório da Cruz do Pascoal p. 112 Herma do Dr.Patterson p. 131 PREFÁCIO SESSENTA e um anos depois da primeira edição 1 , a Universidade Federal da Bahia publica, na Coleção Nordestina, em novo formato, o livro do baiano José Valladares , como uma homenagem a um seu docente de estética e de história da arte brasileira e das criações do barroco colonial, que cursou especialização em história da arte na Universidade de New York e visitou setenta e quatro museus norte-americanos no ano de 1943, fundou e dirigiu o Museu de Arte da Bahia (1939Bahia ( -1959) ) e ao artista plástico Carlos Thiré (carioca, 1917-1963), que estudou arte em Paris, em 1947, com o pintor André Lothe, foi produtor, diretor e cenógrafo de teatro, televisão (Rio e Tupi) e cinema (Vera Cruz), dentre outras atividades na área cultural, e também autor dos desenhos que ilustram, como uma joia, este guia turístico da cidade de Salvador em 1951.1 Na sua primeira edição, este livro foi editado com o formato 21x29cm, em papel WESTERPOST, trezentos exemplares numerados de 1 a 300 e 35 com desenho original do ilustrador, numerados de I a XXXV, todos assinados pelo autor, com 155 páginas, Livraria Turista Editora, Salvador, e com uma tiragem em formato 16x23,5cm, com 155 páginas, Livraria Progresso Editora, Salvador, ambos compostos e impressos nas oficinas gráficas da tipografia Beneditina Ltda., que contava com a orientação do Irmão Paulo Lachenmeyer OSB .Nas duas tiragens, há um "Mapa pitoresco e resumido da cidade da Bahia em 1950", de autoria de Carlos Thiré, cuja data nos esclarece o ano de feitura das ilustrações.Pode-se marcar a importância da reedição deste livro não só por seu conteúdo exemplar, com a qualidade do seu texto e a beleza das ilustrações, mas também pelo seu valor como documento ou fonte de natureza histórica e antropológica sobre a "cidade da Bahia", uma sutil e delicada apresentação da sua cultura, arquitetura e monumentos.O livro, esgotado há muitos anos, transcendeu a sua condição de "guia turístico" e passou a integrar, no meu entender, a bibliografia baiana, por seu variado interesse para os estudiosos da evolução (seria uma involução?)urbana da cidade, acentuadamente predadora da sua paisagem humana, arquitetônica e natural desde o início do século XX.Para que se constate esta destruição, basicamente provocada pela vontade e incúria dos homens, especialmente dos incompetentes administradores públicos e dos especuladores imobiliários, basta ler o capítulo do livro "Roteiro para o visitante apressado", comparando-o com o que se vê atualmente nas praças, ruas e becos daquilo que ainda resta do "centro histórico", na baixa e alta da cidade que chamo de Salvadolores.A primeira edição deste livro deu-se no Governo do democrata Octavio Mangabeira (1947)(1948)(1949)(1950)(1951), sendo Anísio Teixeira seu Secretário e grande mentor da cultura e das artes na Bahia.Esta nova edição, em 2012, repassa ao leitor um exemplo do que pode ser feito, com qualidade e bom gosto, quando se respeita a tradição.Não me resta qualquer dúvida que este livro deve ser lido, nos medíocres e temerosos tempos atuais, como uma obra de referência no gênero, por sua linguagem direta e clara, curiosa e informativa, principalmente crítica, pois o mestre e amigo José Valladares, já em 1951, em Nota Final ao livro, p. 110, advertia e prenunciava o que aconteceria quando o "turismo" assumisse o seu lugar na economia, como uma "indústria avassalante", também na Bahia, sem qualquer política e nenhum controle: Embora este livro tenha o subtítulo "Guia Turístico", não sinto a menor simpatia pela preocupação de muitos baianos com o turismo.Que a cidade da Bahia seja rica de atrativos turísticos -ninguém poderá contestar.Mas será uma tristeza no dia em que, ao invés de pensarmos em nossas coisas, à nossa maneira e de acordo com nossas convicções, nos pusermos a pensar no conforto, curiosidade, gosto e caprichos do turista.Não será desta forma que a Bahia progredirá.Sejamos cordiais com os que nos dão a honra da visita; mas não sejamos subservientes.No final, nós é que sairemos perdendo.E a primeira coisa que se perderá será o caráter de nossa cidade, quase por milagre ainda conservado num Brasil cujas grandes cidades a passos largos se vão tornando excessivamente semelhantes às grandes cidades de qualquer parte do mundo.Quando menos imaginarmos, com essa mania de cortejar os turistas, a Bahia terá deixado de ser a Bahia.Assim sendo, ainda hoje há muito o que defender no centro histórico da cidade, em especial no Pelourinho, quando intenta-se construir um "palco" modernoso e retrátil no seu largo (vide as ilustrações de páginas 38 e 39), porém, agora e sempre, muito o que agradecer pela existência deste belo livrinho, hoje redescoberto, e pela sensibilidade e lições dos seus autores: louvados sejam Valladares e Thiré.É preciso acrescentar que, para a segunda edição deste livro, contamos com uma cuidadosa revisão e atualização ortográfica, assim como das indicações bibliográficas dentro das normas da ABNT, realizadas pacientemente por Maria José Bacelar Guimarães.Creio que ainda vale ressaltar neste prefácio duas informações necessárias: 1', '["Salvador, Bahia","tour guides","Boa Vista"]', '10.7476/9788523211646', '9788523211646', 'https://books.scielo.org/id/kkc7r', 'https://books.scielo.org/id/kkc7r/pdf/valladares-9788523211646.pdf', NULL, 'https://books.scielo.org/id/kkc7r/cover/cover_thumbnail.jpeg', NULL, 1, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-kkf5v', 'kkf5v', 'Cultura gaúcha e separatismo no Rio Grande do Sul', NULL, '["Caroline Kraus Luvizotto"]', 'Editora UNESP', 'Brasil', 'SciELO Books', 'books', 2009, '2009-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Etnicidade e identidade étnica 29 3 O separatismo no Rio Grande do Sul 37 4 Tradição separatista 59 5 O nazismo no Rio Grande do Sul 75 Considerações finais 85 Referências bibliográficas 89 A ideia de compor este trabalho surgiu durante a graduação em Ciências Sociais na Faculdade de Filosofia e Ciências de Marília -Unesp/FFC.Desde o início, o foco dos estudos foi o estado do Rio Grande do Sul.Abordou-se inicialmente a história da colonização alemã no estado, e depois se estabeleceu uma relação entre essa colonização alemã, seus aspectos políticos, sociais e culturais e o movimento separatista que se espalhava pelos estados do sul do Brasil no início da década de 1990.Percebeu-se que a questão ia muito além dessa relação.Estudos sobre separatismo ou sobre etnicidade no Brasil existem muitos.Mas a abordagem que se propõe aqui é discutir etnicidade e separatismo, utilizando como estudo de caso o estado do Rio Grande do Sul e o Movimento Separatista Sulino contemporâneo, tendo como pano de fundo a cultura gaúcha.Pretende-se demonstrar como esses dois conceitos interagem no caso desse movimento separatista que tem por objetivo emancipar o estado do Rio Grande do Sul do Brasil.O trabalho apresenta primeiramente um panorama da discussão sobre o conceito de etnicidade a partir de autores clássicos, como Fredrik Barth, Philippe Poutgnat e Guilher- AP R E S E N T A Ç Ã O10 CAROLINE KRAUS LUVIZOTTO mo Rubem, entre outros.Apresenta também uma discussão sobre separatismo, baseada nos autores Manuel Andrade, João Nascimento Franco e Newton Duarte Molon, e sobre o Movimento Separatista Sulino contemporâneo, tomando-se como ponto de partida uma pesquisa de campo realizada em 1999 (cf.Luvizotto, 2000), composta de questionários e do estudo dos documentos do próprio movimento separatista.O trabalho também contempla uma reconstrução histórica sobre o Estado do Rio Grande do Sul em seus principais aspectos (colonização, tradições, revoluções), utilizando autores', '["gaucho culture","separatism","Rio Grande do Sul","German colonization","ethnic identity","ethnicity","National Socialism","German immigrants","regional identity"]', '10.7476/9788579830082', '9788579830082', 'https://books.scielo.org/id/kkf5v', 'https://books.scielo.org/id/kkf5v/pdf/luvizotto-9788579830082.pdf', NULL, 'https://books.scielo.org/id/kkf5v/cover/cover_thumbnail.jpeg', NULL, 10, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-km3d3', 'km3d3', 'Gonzagão e Gonzaguinha: gingados sonoros de brasilidades insubmissas', 'gingados sonoros de brasilidades insubmissas', '["Cláudia Pereira Vasconcelos"]', 'EDUFBA', 'Brasil', 'SciELO Books', 'books', 2025, '2025-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'O que a história de dois dos maiores ícones da MPB ainda tem a nos revelar sobre o Brasil? Indo além da biografia tradicional, este livro mergulha na trajetória de Luiz Gonzaga e Gonzaguinha para investigar como pai e filho, cada qual ao seu modo, desafiaram as margens da sociedade para pautar a identidade nacional. Do sertão de Pernambuco ao Morro de São Carlos no Rio de Janeiro, a obra analisa as "estratégias gingadas" que ambos utilizaram para vencer o preconceito e a exclusão. Através de uma sensível análise de suas canções e da complexa relação afetiva que os unia, a autora revela como os Gonzagas se tornaram autênticos pensadores da cultura brasileira, dando voz a realidades que a "História oficial" tentou silenciar. Mais do que um estudo sobre música, é um retrato insubmisso de um Brasil profundo, narrado a partir de encontros, desencontros e da cura através da arte.', '["Luiz Gonzaga","João Gilberto","Brazilian popular music","national identity","sertão","father-son relationship","song lyrics","Brazilian culture","official history","Pernambuco"]', '10.7476/9786556309514', '9786556308210', 'https://books.scielo.org/id/km3d3', 'https://books.scielo.org/id/km3d3/pdf/vasconcelos-9786556309514.pdf', NULL, 'https://books.scielo.org/id/km3d3/cover/cover_thumbnail.jpeg', NULL, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-km58w', 'km58w', 'Nilda: a dama e o tempo', NULL, '["Marcos Uzel"]', 'EDUFBA', 'Brasil', 'SciELO Books', 'books', 2021, '2021-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'A atriz Nilda Spencer, uma das mulheres mais importantes na memória das artes cênicas na Bahia, é o tema deste livro. As páginas da obra retratam como a dama do teatro baiano se destacou de forma efetiva na dinâmica da cultura da cidade. Revelam os devaneios de infância; os sonhos de juventude no escuro das salas de cinema; a fusão de comportamentos da mulher que transgrediu sem deixar de ter atitudes conservadoras; o trânsito pelas rodas da elite; as noites de boemia em ambientes libertários e marginalizados; a carreira de fôlego da artista que foi pioneira na província dos anos 1950 e trabalhou até o fim da vida. Tudo isso faz desta biografia um mosaico das experiências vividas por uma figura ímpar, em seu intenso caminhar pelo tempo.', '["actresses","women in theatre","Bahia","1950s","Bohemia","cultural elites","cinema"]', '10.7476/9786556303970', '9786556301723', 'https://books.scielo.org/id/km58w', NULL, NULL, 'https://books.scielo.org/id/km58w/cover/cover_thumbnail.jpeg', 287, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-kmtdy', 'kmtdy', 'Los superhéroes, el deber moral y la obligación. El caso de Spider-Man y de los X-Men', NULL, '["Laura Victoria Bolaño Perez"]', 'Editorial Universidad del Rosario', 'Colombia', 'SciELO Books', 'books', 2012, '2012-01-01', 'es', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'La obra presenta al superhéroe como un agente moral digno de imitar, debido a su gran preocupación por el cumplimiento de lo correcto y de los deberes morales. Asimismo, éste se enfrenta constantemente a dilemas morales que debe resolver. A partir de este personaje y de identificación que puede generar entre los jóvenes, es posible presentar de forma más amena y comprensible la filosofía moral. Es por ello que la obra está dirigida a educadores de la ética y a quienes estén interesados en la filosofía moral aplicada. El texto contiene una parte donde se describe la figura del héroe y su paso al superhéroe, así como una breve reseña de los casos de estudio, a saber, Spider-man y X-Men; a continuación, se hace una presentación sobre el concepto del deber moral y el dilema moral. Ésta sólo busca contextualizar al lector sobre los conceptos que se van a tratar más adelante. Finalmente, se presentan los resultados del análisis de discurso (para lo cual se utilizaron unas matrices de análisis) de varios capítulos de las series animadas referidas (Spider-man y X-Men) en donde se evidencia cómo actúan como agentes morales y cómo justifican sus decisiones morales.', '["superheroes","moral obligation","ethical dilemmas","Spider-Man","X-Men","moral agents","animated television series"]', '10.7476/9789585005372', '9789585005372', 'https://books.scielo.org/id/kmtdy', 'https://books.scielo.org/id/kmtdy/pdf/bolano-9789585005372.pdf', NULL, 'https://books.scielo.org/id/kmtdy/cover/cover_thumbnail.jpeg', NULL, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-kn7p7', 'kn7p7', 'Da liberdade do cristão: prefácio a Bíblia', NULL, '["Martinho Lutero"]', 'Editora UNESP', 'Brasil', 'SciELO Books', 'books', 1998, '1998-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'Reunião de quatro textos escritos pelo reformador alemão Martinho Lutero (1483-1546), no início da segunda década do século XVI, como introdução a alguns dos livros da Bíblia. Nas palavras do próprio Lutero, em carta ao papa Leão X, é um livrinho se consideramos o papel, mas que contém a totalidade da vida cristã se consideramos o sentido.', '["Martin Luther","Christian liberty","Reformation","Bible","Lutheran theology","Christian life","Pope Leo X"]', '10.7476/9788539302772', '9788571391925', 'https://books.scielo.org/id/kn7p7', NULL, NULL, 'https://books.scielo.org/id/kn7p7/cover/cover_thumbnail.jpeg', 127, 2, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-kng2j', 'kng2j', 'Fascismo e grande capital', NULL, '["Daniel Guérin"]', 'Editora da Unicamp', 'Brasil', 'SciELO Books', 'books', 2021, '2021-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Fascismo e grande capital é um clássico. Publicado em 1936, foi editado e reeditado em diversos países. No Brasil, permanecia inédito. O autor viajara pela Alemanha nazista e escrevera um livro relatando essa viagem. Impressionada com a qualidade do material, uma companheira o incitou a fazer uma pesquisa sistemática sobre o tema. O resultado foi este livro repleto de ideias, de teses originais e também de tratamento mais fundamentado e desenvolvido para teses que já circulavam sobre o fascismo. O objetivo de Fascismo e grande capital é elaborar o conceito de fascismo. Para tal elaboração conceitual, o autor examina o fascismo na Itália e na Alemanha. Guérin apresenta o fascismo como um movimento pequeno-burguês e de classe média, reacionário, que, numa conjuntura determinada, é cooptado pela burguesia e, particularmente, pela grande burguesia, que disputa a hegemonia política com o médio capital. O livro de Daniel Guérin, tratando de fenômeno aparentemente tão distante, contribui para a compreensão da natureza da extrema direita no mundo contemporâneo. (Armando Boito Jr.)', '["fascism","Daniel Guérin","Italian Fascism","Nazi Germany","bourgeoisie","political hegemony","concept of fascism","far right"]', '10.7476/9788526815421', '9786586253931', 'https://books.scielo.org/id/kng2j', NULL, NULL, 'https://books.scielo.org/id/kng2j/cover/cover_thumbnail.jpeg', 321, 9, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-knm4c', 'knm4c', 'Do contágio à transmissão: ciência e cultura na gênese do conhecimento epidemiológico', 'ciência e cultura na gênese do conhecimento epidemiológico', '["Dina Czeresnia"]', 'Editora FIOCRUZ', 'Brasil', 'SciELO Books', 'books', 1997, '1997-01-01', 'pt', 'book', 'medical-health', 'Ciencias Médicas y de la Salud', 'Medicine', 'Trata da relação entre o conceito de transmissão e a gênese do conhecimento epidemiológico. Busca responder às seguintes questões: como, a partir da ocorrência de uma epidemia, vão sendo construídas verdades e definições a seu respeito?; como os conceitos científicos que constituem a epidemiologia participam desse processo?; que marcas e conseqüências esses conceitos imprimem às maneiras adotadas para se lidar com o acontecimento? A autora trabalha criticamente com dois conceitos habituais no campo da saúde pública: o de contágio, associado a atitudes preconceituosas e de rejeição do outro; o de transmissão, que marca a constituição da epidemiologia como disciplina de estrutura científica. A problemática da Aids é o fio condutor da reflexão epistemológica.', '["contagion","transmission","epidemiology","history of epidemiology","AIDS","epistemology of science","epidemics","public health concepts","prejudice","rejection of the other","scientific knowledge construction"]', '10.7476/9788575412565', '9788585676322', 'https://books.scielo.org/id/knm4c', 'https://books.scielo.org/id/knm4c/pdf/czeresnia-9788575412565.pdf', NULL, 'https://books.scielo.org/id/knm4c/cover/cover_thumbnail.jpeg', NULL, 52, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-knsfc', 'knsfc', 'Epígrafes e diálogos na poesia de Machado de Assis', NULL, '["Audrey Ludmilla do Nascimento Miasso"]', 'EdUFSCar', 'Brasil', 'SciELO Books', 'books', 2017, '2017-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'Nas epígrafes que acompanham alguns dos poemas das Crisálidas (1864), de Machado de Assis, há o desfile de autores como Dante, Camões, Heine e Homero. O mesmo acontece nos livros de poemas seguintes, Falenas (1870) e Americanas (1875). A escolha desses nomes nos revela autores da biblioteca machadiana que o acompanharam durante toda sua carreira e que influenciaram seu modo de escrita. Tais nomes dialogam com a poesia machadiana e nos ajudam a melhor compreender a composição poética do autor, sendo não apenas fonte de abastecimento para os poemas, mas relacionando-se também com eles na questão do entendimento da obra, dando-lhes um novo sentido.', '["Machado de Assis","epigraphs","poetry","Americana","literary influence","Dante","Luís de Camões","Heinrich Heine","Homer","literary reception","poetry writing"]', '10.7476/9786580216147', '9786580216147', 'https://books.scielo.org/id/knsfc', 'https://books.scielo.org/id/knsfc/pdf/miasso-9786580216147.pdf', NULL, 'https://books.scielo.org/id/knsfc/cover/cover_thumbnail.jpeg', NULL, 1, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-kntw4', 'kntw4', 'Memória: estudos interdisciplinares', NULL, '["Elton Moreira Quadros"]', 'LA Referencia (Red Federada de Repositorios Institucionales de Publicaciones Científicas)', 'Brasil', 'SciELO Books', 'books', 2018, '2018-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'O livro contribui para aumentar o espaço acadêmico da discussão sobre a memória em seus aspectos inter/multi/transdisciplinares. Fruto de múltiplas pesquisas de graduação e pós-graduação, relaciona história, filosofia e cultura, dialogando com a literatura.', '["memory","interdisciplinary research","history","philosophy","culture","literature","interdisciplinarity"]', '10.7476/9786588211090', '9788578873561', 'https://books.scielo.org/id/kntw4', 'https://books.scielo.org/id/kntw4/pdf/quadros-9786588211090.pdf', 'https://books.scielo.org/id/kntw4/epub/quadros-9786588211090.epub', 'https://books.scielo.org/id/kntw4/cover/cover_thumbnail.jpeg', 174, 1, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-kp484', 'kp484', 'Capítulos da história colonial', NULL, '["Capistrano de Abreu"]', 'Centro Edelstein', 'Brasil', 'SciELO Books', 'books', 2009, '2009-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'Esta obra é constituída de onze capítulos sobre os antecedentes indígenas da terra brasilis e seus descobridores, os conflitos iniciais nas tentativas de colonização, o sistema de capitanias hereditárias, as guerras contra os franceses, espanhóis e holandeses, a descoberta das minas, a ocupação do interior (sertão) e a formação das fronteiras do território brasileiro. Os capítulos, desde sua primeira publicação, tornaram-se referência para todos os interessados no estudo do Brasil colonial.', '["colonial Brazil","indigenous peoples of Brazil","colonial exploration","Portuguese colonization of Brazil","colonial history"]', '10.7476/9788579820717', '9788579820717', 'https://books.scielo.org/id/kp484', 'https://books.scielo.org/id/kp484/pdf/abreu-9788579820717.pdf', 'https://books.scielo.org/id/kp484/epub/abreu-9788579820717.epub', 'https://books.scielo.org/id/kp484/cover/cover_thumbnail.jpeg', 195, 21, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-kpj32', 'kpj32', 'Entidades assistenciais para crianças e adolescentes no município: impasses institucionais e possibilidades', NULL, '["Sílvio José Benelli"]', 'Editora UNESP', 'Brasil', 'SciELO Books', 'books', 2022, '2022-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Neste livro, Silvio José Benelli examina nos arquivos do Conselho Municipal dos Direitos da Criança e do Adolescente as entidades assistenciais cadastradas, identificando quais são e como funcionam esses estabelecimentos públicos e privados que atendem crianças e adolescentes em “situação de risco pessoal e social” em um município do interior do estado de São Paulo. A partir de ampla literatura sobre política pública de atendimento à criança e ao adolescente na atualidade brasileira e por meio de uma análise crítica, tanto da documentação quanto da bibliografia, o autor aprofunda a compreensão sobre a estrutura, o modo de funcionamento, a efetividade, os não ditos e as lacunas discursivas, principais problemas e desafios que enfrentam essas instituições. A produção da vida social é um dos determinantes fundamentais na orientação filantrópica das entidades assistenciais, que se encontram pautadas atualmente pela lógica mercadológica do terceiro setor, avessa às políticas públicas sociais e que lhes impõe dificuldades para pautarem discursos e práticas a partir do paradigma do sujeito cidadão.', '["child and youth welfare","third sector","philanthropy","market logic","social policy","citizen subject","municipal government","São Paulo interior"]', '10.7476/9786557142998', '9786557142998', 'https://books.scielo.org/id/kpj32', 'https://books.scielo.org/id/kpj32/pdf/benelli-9786557142998.pdf', NULL, 'https://books.scielo.org/id/kpj32/cover/cover_thumbnail.jpeg', NULL, 3, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-kpp66', 'kpp66', 'Políticas públicas de saúde mental como promotoras de cidadania e (re)inserção social: um novo lugar para ser feliz?', NULL, '["Flávia Michelle Pereira Albuquerque"]', 'Editora UFFS', 'Brasil', 'SciELO Books', 'books', 2022, '2022-01-01', 'pt', 'book', 'medical-health', 'Ciencias Médicas y de la Salud', 'Psychology', 'Esta obra pretende produzir reflexões sobre a saúde mental e apresenta um estudo do município de Santa Rosa (RS). A assistência ao doente mental, por muitos anos, foi centrada nos hospitais psiquiátricos, locais da prática e do saber médico. O modelo de atenção constituía-se de internação e medicalização dos sintomas do transtorno mental, excluindo os sujeitos dos seus vínculos familiares e sociais. Somente em 2001 ocorreu a Reforma Psiquiátrica, o que proporcionou o começo da reorganização da saúde mental no Brasil, que foi avançando, aos poucos, conforme surgiam novas legislações brasileiras e internacionais. “Políticas públicas de saúde mental como promotoras de cidadania e (re)inserção social: um novo lugar para ser feliz?” defende, entre outros aspectos: a importância da rede de atendimentos em saúde mental; a necessidade de superar desafios e estigmas ainda existentes nessa trajetória de mudança do modelo de cuidado prestado ao indivíduo com transtorno mental; a construção de políticas intersetoriais integradas que ampliem o acesso e a rede de oferta de serviços; a integralidade, que se materializa à medida que o acolhimento, o vínculo e a responsabilização permitem a aproximação entre os atores envolvidos e eles dialogam e produzem novas possibilidades de vida, novas capacidades e novas habilidades.', '["mental health policy","citizenship","social reintegration","mental illness","psychiatric reform","mental health care network","stigma","intersectoral integration","comprehensive care","Santa Rosa, Rio Grande do Sul"]', '10.7476/9786550190194', '9786550190194', 'https://books.scielo.org/id/kpp66', 'https://books.scielo.org/id/kpp66/pdf/albuquerque-9786550190194.pdf', NULL, 'https://books.scielo.org/id/kpp66/cover/cover_thumbnail.jpeg', NULL, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-kprj8', 'kprj8', 'Histórias de pessoas e lugares: memórias das comunidades de Manguinhos', NULL, '["Tania Maria Fernandes","Renato Gama-Rosa Costa"]', 'Editora FIOCRUZ', 'Brasil', 'SciELO Books', 'books', 2009, '2009-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Em um contexto urbano complexo e vulnerável como o pesquisado, a obra busca reconstituir a história de pessoas e lugares do território de Manguinhos – hoje repleto de favelas que circundam a Fiocruz –, com seus inúmeros problemas socioambientais e sanitários. Os autores estendem-se por cerca de cem anos de ocupação da história social e urbana do Rio de Janeiro (capítulo importante e até hoje tão pouco explorado), mediante abordagens relacionadas à própria história, à memória e ao urbanismo. Trabalhou-se com a história oral, optando-se por dar voz aos moradores da região. Entre depoimentos, fotografias, vídeos, documentos oficiais, cartas e jornais de época, bem como entrevistas com experientes profissionais envolvidos na implantação de projetos em favelas cariocas, o livro nos revela, de forma consistente, com seu material inédito, a diversidade e a singularidade dos processos socioespaciais constitutivos das 12 comunidades estudadas. Entre lembranças e vivências narradas, transparecem as configurações desse típico bairro de periferia que retrata uma triste realidade de exclusão social e de discriminações. Com base no conteúdo, o leitor terá a oportunidade de poder continuar a registrar e a acompanhar as futuras transformações que ocorrerão em Manguinhos.', '["Manguinhos","favelas","urban periphery","social memory","oral history","social exclusion","urban history","socio-environmental problems","public health","Fiocruz","Rio de Janeiro","community history"]', '10.7476/9788575416020', '9788575416020', 'https://books.scielo.org/id/kprj8', 'https://books.scielo.org/id/kprj8/pdf/fernandes-9788575416020.pdf', NULL, 'https://books.scielo.org/id/kprj8/cover/cover_thumbnail.jpeg', NULL, 4, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-kpvcr', 'kpvcr', 'Produção sustentável e conservação ambiental: uma abordagem interdisciplinar', 'uma abordagem interdisciplinar', '["Paulo Afonso Hartmann","Leandro Galon"]', 'Editora UFFS', 'Brasil', 'SciELO Books', 'books', 2024, '2024-01-01', 'pt', 'book', 'agricultural-sciences', 'Ciencias Agrícolas y Veterinaria', 'Agricultural and Biological Sciences', 'Este livro está estruturado em dois grandes blocos. No primeiro, intitulado “Sustentabilidade dos Agroecossistemas” são contemplados capítulos que tratam de temas pertinentes à produção rural, seus impactos ambientais, sua contribuição social e econômica e suas relações com a qualidade de vida, tanto do homem do campo como da cidade. No segundo bloco, denominado “Conservação dos Recursos Naturais”, são tratados temas voltados para os impactos das atividades humanas na biodiversidade, além de técnicas e tecnologias para uso sustentável de resíduos e seu potencial para aplicação na indústria. “Produção Sustentável e Conservação Ambiental: uma abordagem interdisciplinar” apresenta, em 10 capítulos, estudos realizados no âmbito do Programa de Pós-Graduação em Ciência e Tecnologia (PPGCTA). Os temas foram selecionados para contemplar a diversidade de atuações, linhas de pesquisas e conhecimentos produzidos no Programa. Embora os capítulos abordem temáticas diversificadas, todos têm como foco a identificação, a análise, a discussão e a proposição de soluções de questões que envolvam produção sustentável e conservação dos recursos naturais, que é a área de concentração do PPGCTA.', '["sustainable production","environmental protection","agroecosystems","rural production","environmental impact of agriculture","natural resource conservation","quality of life","urban and rural life"]', '10.7476/9786550191191', '9786550191214', 'https://books.scielo.org/id/kpvcr', 'https://books.scielo.org/id/kpvcr/pdf/hartmann-9786550191191.pdf', NULL, 'https://books.scielo.org/id/kpvcr/cover/cover_thumbnail.jpeg', NULL, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-kqbg9', 'kqbg9', 'Latin America''s Elusive democracies', NULL, '["Bernardo Sorj"]', 'Centro Edelstein', 'Brasil', 'SciELO Books', 'books', 2007, '2007-01-01', 'en', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'This is a refreshing book: it contains nothing trite, rejects conventionality and academic fads, and unswervingly asserts a clear position on thorny issues. With this book, Bernardo Sorj has demonstrated once again what those of us who have followed his career already knew: not only is he an excellent sociologist, but above all, he is a true intellectual, a critical thinker who tackles the main issues of today’s world, and Latin America in particular.', '["democracy","Latin America","democratic transition","political sociology","democratization"]', '10.7476/9788599662212', '9788599662212', 'https://books.scielo.org/id/kqbg9', 'https://books.scielo.org/id/kqbg9/pdf/sorj-9788599662212.pdf', NULL, 'https://books.scielo.org/id/kqbg9/cover/cover_thumbnail.jpeg', NULL, 14, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-kqmj2', 'kqmj2', 'Estado, educación y pueblos indígenas en los Andes ecuatorianos: la experiencia del Sistema de Escuelas Indígenas de Cotopaxi', NULL, '["Sebastián Granda Merchán"]', 'Editorial Abya-Yala', 'Ecuador', 'SciELO Books', 'books', 2020, '2020-01-01', 'es', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Sebastián Granda Merchán debate en este libro el proceso de institucionalización de la Educación Intercultural Bilingüe (EIB) en Ecuador y su impacto en las iniciativas educativas gestadas y sostenidas por las comunidades indígenas. Analiza la experiencia del Sistema de Escuelas Indígenas de Cotopaxi (SEIC), en los alrededores del Quilotoa, que buscó atender las demandas de formación de la zona, en el marco de la lucha por la tierra y la construcción de un proyecto de desarrollo endógeno. El texto se construye a partir de la historia oral y la revisión de fuentes primarias, con actores que participaron directamente en el proceso, tanto del lado del Estado como directivos, equipos de gestión y educadores comunitarios, con quienes determina el efecto que tuvo la institucionalización de la EIB en las iniciativas de la educación indígena.', '["intercultural bilingual education","indigenous education","indigenous peoples","state education policy","institutionalization of education","indigenous land struggles","endogenous development","Cotopaxi","Ecuadorian Andes"]', '10.7476/9789978105733', '9789978105733', 'https://books.scielo.org/id/kqmj2', 'https://books.scielo.org/id/kqmj2/pdf/granda-9789978105733.pdf', NULL, 'https://books.scielo.org/id/kqmj2/cover/cover_thumbnail.jpeg', NULL, 3, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-kqnhg', 'kqnhg', 'O Nasf e o Trabalho na Atenção Básica à Saúde: apontamentos práticos e experimentações', NULL, '["Túlio Romério Lopes Quirino","Marques, Fabiana Maria de Aguiar Bello","Oliveira, Vick Brito","Silva, Evelyn Siqueira da"]', 'Editora FIOCRUZ', 'Brasil', 'SciELO Books', 'books', 2019, '2019-01-01', 'pt', 'book', 'medical-health', 'Ciencias Médicas y de la Salud', 'Health Professions', 'O cotidiano das equipes do Núcleo de Apoio à Saúde da Família (Nasf) em Recife, Pernambuco, é a base desta obra, que convida o leitor à reflexão sobre o lugar central da Atenção Básica à Saúde na organização do cuidado e nos processos criativos e inovadores que cercam os profissionais de saúde pública. Organizado por professores e pesquisadores da área de Saúde Coletiva, a coletânea reúne sete artigos, que apresentam aspectos legais e normativos de implantação dos Nasf, passando por questões ligadas às estratégias, ferramentas tecnológicas, desafios, territorialização, planejamento e avaliação dos Núcleos. O livro é mais um a integrar a coleção Fazer Saúde, que estimula diálogo e o compartilhamento de conhecimentos científicos e inovações tecnológicas diretamente ligados à consolidação do Sistema Único de Saúde (SUS). As muitas experiências e práticas narradas ao longo do livro reforçam, segundo o pesquisador Michael Machado, professor de saúde coletiva da Universidade Federal de Alagoas, a importância do Nasf para a Atenção Básica à Saúde, “não só por ampliar seu campo de ações e o compartilhamento de conhecimentos, saberes e responsabilidades centradas no território, como também por expandir a capacidade de resolutividade clínica das equipes e de todos os trabalhadores envolvidos”.', '["primary care","Unified Health System (SUS)","health care organization","health professions education","clinical problem solving","health technology","health policy implementation","Recife"]', '10.7476/9786557080672', '9788575416259', 'https://books.scielo.org/id/kqnhg', NULL, NULL, 'https://books.scielo.org/id/kqnhg/cover/cover_thumbnail.jpeg', 157, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-kr4yq', 'kr4yq', 'Mais Médicos: as vozes dos atores e os impactos do programa na atenção básica à saúde', NULL, '["Telles, Helcimara"]', 'Editora UFMG', 'Brasil', 'SciELO Books', 'books', 2019, '2019-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'O mérito da pesquisa de avaliação dirigida por Helcimara Telles está em mostrar a realidade que o Mais Médicos revelou: milhões de brasileiros, entre eles pobres, indígenas e quilombolas que sequer viam médicos, passaram a se beneficiar de um dos programas mais corajosos do governo Dilma. O público em geral conhece melhor o lado emergencial do programa – o atendimento aos recantos mais pobres do país –, mas o Mais Médicos também ampliou as faculdades de Medicina no interior, reforçou a preocupação com o atendimento básico e determinou que houvesse critérios rigorosos de qualidade na formação, incentivando a avaliação dos alunos no segundo e quarto anos de curso. O que as vozes nos dizem, graças a esta importante pesquisa, é como, em pouco tempo, o Mais Médicos mudou o panorama da saúde no Brasil. O livro mostra que políticas públicas bem concebidas podem funcionar, sobretudo quando somam esforços – como os dos Ministérios da Saúde e da Educação – e atendem a necessidades reais da população. Foi um grande esforço, obteve resultados bastante positivos e em tempos mais democráticos será retomado.', '["Mais Médicos program","primary care","health policy evaluation","medical education","medical curriculum","healthcare workers","health care access","Indigenous health","quilombola communities","public health policy","Brazil"]', '10.7476/9786558580140', '9788542302776', 'https://books.scielo.org/id/kr4yq', NULL, NULL, 'https://books.scielo.org/id/kr4yq/cover/cover_thumbnail.jpeg', 263, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-krj5p', 'krj5p', 'Aprendizagem e desenvolvimento humano: avaliações e intervenções', NULL, '["Tânia Gracy Martins do Valle"]', 'Editora UNESP', 'Brasil', 'SciELO Books', 'books', 2009, '2009-01-01', 'pt', 'book', 'medical-health', 'Ciencias Médicas y de la Salud', 'Psychology', 'Apresentação 7 1 Comportamento verbalmente controlado: algumas questões de investigação do controle por estímulos textuais e pela palavra ditada 9 2 Processos de ensino e de aprendizagem profissionais da docência nas séries iniciais: análise do comportamento e formação de professores 33 3 Avaliação e treinamento de habilidades sociais de crianças em idade pré-escolar 49 4 Variáveis sociodemográficas, contaminação por chumbo e o desenvolvimento infantil 77 5 Habilidades sociais e experiências táteis: contato físico nas interações de crianças pré-escolares 97 6 Conceito de família: adolescentes de zonas rural e urbana 121 7 Estereótipos sexuais e a educação sexista no discurso de mães 137 8 A relação entre ex-cônjuges e entre pais e filhos após a separação conjugal 155 9 Relações familiares permeadas por violência sexual do pai contra a filha 177 10 Concepções dos professores do Ensino Fundamental sobre TDAH 201 APRESENTAÇÃO Este livro é resultado de estudos realizados por discentes e docentes do curso de Pós-graduação em Psicologia do Desenvolvimento e Aprendizagem.A diversidade de enfoques apresentados mostra a amplitude das pesquisas desenvolvidas e a contribuição deste grupo de acadêmicos para o desenvolvimento da área que é desafiadora e básica para a Psicologia.Os capítulos iniciais focalizam a responsabilidade que o Programa tem com a área da Aprendizagem.São estudos que apresentam contribuições metodológicas e aplicadas na avaliação de processos de aprendizagem e de planejamento de condições de ensino para crianças e a análise do comportamento para a Educação no campo da formação de professores e contribuições de recursos metodológicos de avaliação fundamental no contexto educacional.Na sequência, os estudos trazem contribuições diretas com a área de Desenvolvimento Humano, abordando temas voltados para pré-escolares até a idade adulta, como pais e professores.Nos capítulos que fornecem dados a respeito de pré-escolares, os temas versam sobre: treino de habilidades sociais e mudanças de desempenho, repertório socialmente habilidoso entre meninos e meninas e a importância do comportamento verbal e não verbal, como favoráveis ao desenvolvimento humano, assim como a análise de desenvolvimento infantil de crianças contaminadas e não contaminadas por chumbo.Os adolescentes têm seu espaço nesta obra, com o estudo de seus conceitos de família, sua função e o grau de satisfação deles em relação a elas, sendo a origem destes: a zona rural e a zona urbana. TÂNIA GRACY MARTINS DO VALLE (ORG.)Nos capítulos que estão voltados para a população de adultos, os estudos investigam os estereótipos sexuais no discurso de mães e o que elas relatam sobre a educação de seus filhos -meninos e meninas -, quando se trata de questões de gênero; o relacionamento conjugal e entre pais e filhos em família de pré-escolares após a separação dos cônjuges; a importância do diálogo entre mãe e filho, mantendo o espaço do pai nas relações afetivas com a criança, para minimizar o sentimento de abandono do filho; a avaliação das percepções de crianças e mães sobre as relações familiares permeadas por violência sexual do pai contra a filha após a revelação da violência; orientação de professores sobre o que é TDAH, suas causas, diagnósticos e prevalência.Espero que o leitor perceba a importância destes estudos e os aproveite como eles bem merecem.', '["verbal behavior","stimulus control","teacher professional development","early childhood teacher education","social skills training","preschool children","lead exposure","child development","physical contact","tactile experience","concept of family","sexual stereotypes"]', '10.7476/9788598605999', '9788598605999', 'https://books.scielo.org/id/krj5p', 'https://books.scielo.org/id/krj5p/pdf/valle-9788598605999.pdf', NULL, 'https://books.scielo.org/id/krj5p/cover/cover_thumbnail.jpeg', NULL, 7, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-krwf3', 'krwf3', 'As minas e a agulheta: romance e história em As minas de prata, de José de Alencar', NULL, '["Marcos Roberto Flamínio Peres"]', 'Editora UFMG', 'Brasil', 'SciELO Books', 'books', 2015, '2015-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'Poucas vezes um estudo acadêmico sobre as artimanhas da imaginação romântica terá sido tratado com tanta abrangência como neste ensaio de Marcos Flamínio Peres. E isso não apenas pelo arranjo escrito do argumento, cuja habilidade como que se amolda ao imprevisto das variações temáticas como que a tendência folhetinesca acabou desarticulando a linearidade do romance histórico, ao ajustar o dado bruto dos grotões da Colônia às figurações da quimera e do maravilhoso. Mais do que isso, o alcance do ensaio vale sobretudo pelo modo preciso com que elucida as particularidades do contesto histórico-literário em que se expande essa transformação do gênero.', '["José de Alencar","historical fiction","Romantic imagination","novella","the marvelous","colonial Brazil","narrative structure","genre transformation","Brazilian Romanticism"]', '10.7476/9788542302875', '9788570419897', 'https://books.scielo.org/id/krwf3', NULL, NULL, 'https://books.scielo.org/id/krwf3/cover/cover_thumbnail.jpeg', 124, 1, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-ksp49', 'ksp49', 'Chauvinismo e extrema direita: crítica aos herdeiros do sigma', NULL, '["Jefferson Rodrigues Barbosa"]', 'Editora UNESP', 'Brasil', 'SciELO Books', 'books', 2015, '2015-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'no ha perdido, pues, su actualidad, ni mucho menos, por más que hayan cambiado las circunstancias de hoy.', '["chauvinism","far right","gender ideology"]', '10.7476/9788568334683', '9788568334683', 'https://books.scielo.org/id/ksp49', 'https://books.scielo.org/id/ksp49/pdf/barbosa-9788568334683.pdf', NULL, 'https://books.scielo.org/id/ksp49/cover/cover_thumbnail.jpeg', NULL, 5, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-ktjyw', 'ktjyw', 'Gestão social e agricultura familiar: a construção e a materialidade de novas formas de administrar', NULL, '["Elisabete Stradiotto Siqueira","Iriane Teresa de Araújo"]', 'EdUFERSA', 'Brasil', 'SciELO Books', 'books', 2018, '2018-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'O livro propõe dialogar com formas de gestão pautadas em valores como solidariedade, cooperação, democracia, igualdade de oportunidades, sustentabilidade ambiental e respeito às relações entre sociedade e organização. Trata-se de nadar contra a corrente da lógica dominante, que sustenta que a desigualdade social é resultado de competências e incompetências individuais. Para lidar com esse questionamento, este livro abordao binômiogestão social e agricultura familiar como um campo para analisar essas relações. O livro está dividido em três eixos: O primeiro trata da dimensão conceitual da gestão social. Para tratar essa questão, é realizada uma reflexão teórico-conceitual sobre gestão social e os nexos entre a lógica da gestão social e da agricultura familiar. No eixo seguinte apresentam-se as experiências de organizações enraizadas na agricultura familiar. Os capítulos trazem vivencias de cooperativas e assentamentos rurais e também é abordado o papel das políticas públicas. A terceira e última parte do livro traz o debate sobre as tecnologias sociais. Trata a questão da economia solidária como uma possibilidade de relacionamento entre organizações que primam por uma lógica administrativa substantiva. Espera-se que a leitura dessa obra permita uma reflexão sobre caminhos que vislumbrem a possibilidade de evidenciar as potencialidades e dificuldades que os atores sociais encontram em desenvolver uma lógica de gestão que favoreça à solidariedade e a cooperação.', '["social management","family farming","cooperatives","rural settlement","social economy","solidarity economy","social technology","public policy","social inequality","cooperativism"]', '10.7476/9786587108636', '9786587108636', 'https://books.scielo.org/id/ktjyw', 'https://books.scielo.org/id/ktjyw/pdf/siqueira-9786587108636.pdf', NULL, 'https://books.scielo.org/id/ktjyw/cover/cover_thumbnail.jpeg', NULL, 1, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
