d.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-kvjqb', 'kvjqb', 'O fenômeno da bruxaria nos dois lados do Atlântico: sintoma de tempos em transição', 'sintoma de tempos em transição', '["Mainka, Peter Johann"]', 'EDUEM', 'Brasil', 'SciELO Books', 'books', 2025, '2025-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'A partir de práticas mágicas e feitiços existentes na Europa criou-se no final do século XV o delito específico da bruxaria: um delito, definido, racional e cientificamente, por teólogos e juristas daquele período. Com a expansão europeia, o conceito da bruxaria chegou a outras regiões do globo e também às Américas Espanhola e Portuguesa, onde existiam outros imaginários sobre o mundo espiritual e transcendente, outras idéias e práticas mágicas. No ultramar sob condições totalmente diferentes, o fenômeno da bruxaria passou por modificações devido ao embate com os novos mundos mágicos, tornando-se um outro fenômeno, sem perder as origens europeias. Surge, de certa forma, um mundo imaginário híbrido, conectando e entrelaçando os universos mágicos do Velho e do Novo Mundo. Focalizando os dois cenários diferentes aquém e além do Oceano Atlântico, os capítulos desta publicação pretendem contribuir para verificar possíveis semelhanças e diferenças do fenômeno da bruxaria e feitiçaria na primeira modernidade.', '["witchcraft","witch trials","magic","incantations","early modern period","transatlantic comparison","European expansion","Spanish America","colonial Brazil","Old and New World"]', '10.7476/9786587626185', '9786586383218', 'https://books.scielo.org/id/kvjqb', NULL, NULL, 'https://books.scielo.org/id/kvjqb/cover/cover_thumbnail.jpeg', 464, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-kvmvh', 'kvmvh', 'Diálogo entre gobierno, movimiento indígena y organizaciones sociales. Memoria documental (Quito, junio-octubre 2022)', NULL, '["Cárdenas, Juan","Fernando, Ponce","Sempértegui, Fernando","Aguirre, Milagros","Enrique, José"]', 'Editorial Abya-Yala', 'Ecuador', 'SciELO Books', 'books', 2023, '2023-01-01', 'es', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Luego de 18 días de paro nacional y atendiendo al llamado de los representantes de las organizaciones sociales, la iglesia, a través de la Conferencia Episcopal Ecuatoriana, aceptó intervenir para encontrar un camino de paz y reconciliación para el país. Estas páginas hacen pública, de manera sistemática y ordenada, los documentos que han sido parte de este proceso. Los Documentos preliminares que llevaron a las partes a instalar mesas de diálogo; el Acta de la paz con la transcripción de las intervenciones de cada uno de los líderes de las organizaciones sociales e indígenas, así como de la CEE y el ministerio de Gobierno durante la firma del Acta de la paz (30 de junio de 2022); la Hoja de ruta con los compromisos básicos para garantizar las condiciones de un diálogo con resultados; el Desarrollo de las demandas que fueron presentadas por organizaciones sociales e indígenas a las instancias gubernamentales al inicio de las sesiones; los Documentos del proceso de seguimiento, con la metodología de seguimientos de los compromisos del gobierno. También recoge los actores, instituciones, facilitadores, cofacilitadores, relatores y corelatores de cada mesa. Esta publicación tiene un valor histórico enorme, tanto para el presente cuanto para el futuro. Su consideración y análisis consolidará prácticas que favorezcan la paz a través de la mediación en escenarios de conflictos sociopolíticos.', '["peace process","national strike","indigenous movements","social organization","peace agreements","reconciliation","peace mediation","socio-political conflict","Ecuador"]', '10.7476/9789978108864', '9789978107751', 'https://books.scielo.org/id/kvmvh', 'https://books.scielo.org/id/kvmvh/pdf/cardenas-9789978108864.pdf', NULL, 'https://books.scielo.org/id/kvmvh/cover/cover_thumbnail.jpeg', NULL, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-kw9nn', 'kw9nn', 'Eugenia: ontem e hoje', NULL, '["Robert Wegner"]', 'Editora FIOCRUZ', 'Brasil', 'SciELO Books', 'books', 2025, '2025-05-20', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'Eugenia: ontem e hoje analisa a história da eugenia e suas permanências na sociedade atual. Ao explorar como ideias e práticas eugenistas se mantêm por meio de formas contemporâneas de exclusão — como o racismo, a misoginia e a homofobia —, o livro propõe uma reflexão crítica sobre as desigualdades que ainda estruturam o mundo em que vivemos.', '["eugenics","history of eugenics","racism","misogyny","homophobia","social exclusion","social inequality"]', '10.7476/9786557082348', '9786557082034', 'https://books.scielo.org/id/kw9nn', NULL, NULL, 'https://books.scielo.org/id/kw9nn/cover/cover_thumbnail.jpeg', 212, 3, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-kwd4s', 'kwd4s', 'Marca: do marketing ao balanço financeiro: a questão da atribuição de valor financeiro ao mais relevante dos ativos intangíveis', NULL, '["Mariza Branco Rodrigo de Freitas","Manoel Marcondes Machado Neto"]', 'LA Referencia (Red Federada de Repositorios Institucionales de Publicaciones Científicas)', 'Brasil', 'SciELO Books', 'books', 2015, '2015-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Business, Management and Accounting', 'Com enfoque multidisciplinar, discorre sobre o valor econômico e contábil das marcas em um momento de grande transformação das normas contábeis no Brasil, com a adoção de Internacional Financial Reporting Standards (IFRS). Busca identificar e analisar, por meio de dados obtidos, sobretudo, em entrevistas e relatórios financeiros, as causas da discrepância entre os valores contabilizados para uma marca e os seus valores de mercado. Texto enriquecido com depoimentos de especialistas em finanças, contabilidade, economia e marketing.', '["brand valuation","intangible assets","IFRS adoption","accounting standards","brand marketing","financial reporting","market value versus book value","Brazilian accounting standards"]', '10.7476/9788575115145', '9788575113677', 'https://books.scielo.org/id/kwd4s', NULL, NULL, 'https://books.scielo.org/id/kwd4s/cover/cover_thumbnail.jpeg', 380, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-kwv9y', 'kwv9y', 'Paisagem como modo de entender o mundo', NULL, '["Laura Beatriz Lage"]', 'Editora UFMG', 'Brasil', 'SciELO Books', 'books', 2023, '2023-01-01', 'pt', 'book', 'engineering-tech', 'Ingeniería y Tecnología', 'Engineering', 'A discussão da paisagem integra e cruza diversas disciplinas e temas, tais como arquitetura, urbanismo, arte, arqueologia, geografia, ecologia, patrimônio cultural, percepção ambiental, dentre outros, além de abordar assuntos contemporâneos como mudanças climáticas e o antropoceno. Conforme Michel Collot, teórico francês e estudioso da temática, nossa relação sensível com o mundo, tal como se manifesta na experiência da paisagem, é a de um encontro e de uma interação permanente entre o dentro e o fora, o eu e o outro, não a de um sujeito separado do meio. Assim, este livro aborda, através da experiência estética e sensível (cinestésica) do ambiente, as possibilidades de (re)integração do homem e seu meio, a partir da perspectiva da paisagem. Devido à maior aproximação da autora a disciplinas de conservação/preservação do patrimônio e planejamento territorial, elas serão as que direcionam mais a discussão, mas nunca se esquecendo de que existem outras possibilidades e que elas devem ser abordadas em um planejamento da paisagem que busca possibilitar a preservação por meio do desenvolvimento, sem perder a dimensão estética, simbólica e paisagística, tão cara à qualidade ambiental dos lugares e de vida dos seus usuários.', '["landscape","landscape experience","aesthetic experience","kinesthetic perception","human-environment relationship","cultural heritage preservation","spatial planning","landscape planning","sustainable development","environmental perception","Anthropocene","climate change"]', '10.7476/9786558581611', '9786558581215', 'https://books.scielo.org/id/kwv9y', NULL, NULL, 'https://books.scielo.org/id/kwv9y/cover/cover_thumbnail.jpeg', 344, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-kwxbt', 'kwxbt', 'Comunicação e saúde', NULL, '["Inesita Soares de Araújo","Janine Miranda Cardoso"]', 'Editora FIOCRUZ', 'Brasil', 'SciELO Books', 'books', 2007, '2007-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Nesta obra, as autoras debatem questões como as relações de poder, a prática comunicativa e os princípios do SUS. “Queremos que você leia o livro e desenvolva suas reflexões tendo em pauta dois grandes parâmetros para pensar o tema ‘comunicação e saúde’”, avisam as autoras na Apresentação do livro. “Um, que não se pode desvincular a comunicação de um projeto ético da sociedade, que contemple, sobretudo, mais equanimidade na distribuição dos capitais e dos poderes materiais e simbólicos. Outro, que o nosso compromisso é com o aperfeiçoamento do SUS, porque ele é o grande projeto que pode permitir uma mudança nas condições de saúde da população”.', '["health communication","power relations","communicative practices","Unified Health System (SUS)","health equity","communication ethics"]', '10.7476/9788575413098', '9788575411254', 'https://books.scielo.org/id/kwxbt', NULL, NULL, 'https://books.scielo.org/id/kwxbt/cover/cover_thumbnail.jpeg', 152, 51, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-kx9pf', 'kx9pf', 'Educação e letramento', NULL, '["Maria do Rosário Longo Mortatti"]', 'Editora UNESP', 'Brasil', 'SciELO Books', 'books', 2004, '2004-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'PARADIDÁTICOS - SÉRIE: EDUCAÇÃO Atualmente, há cerca de vinte milhões de analfabetos no Brasil, resultantes de um processo histórico longo, com lutas políticas e ideológicas mal resolvidas. Ao cidadão talvez pareça natural a idéia de que o Estado tem o dever de propiciar a todos os indivíduos, por meio da educação, o acesso à leitura e à escrita, como uma das principais formas de inclusão social, cultural e política e de construção da democracia. Nesta obra, a autora aborda conceitos como alfabetização e analfabeto, até sua gradativa substituição por expressões e noções como letramento e iletrado. Analisa a trajetória percorrida e o esgotamento de determinadas possibilidades teóricas e práticas no campo educacional evocando meios para sua superação, bem como para o resgate da dívida histórica com os excluídos da participação social, cultural e política no Brasil.', '["literacy","illiteracy","literacy education","social exclusion","state responsibility for education","social inclusion","political participation","Brazil"]', '10.7476/9788539302987', '9788571395596', 'https://books.scielo.org/id/kx9pf', NULL, NULL, 'https://books.scielo.org/id/kx9pf/cover/cover_thumbnail.jpeg', 134, 43, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-kymhj', 'kymhj', 'Covid-19: desafios para a organização e repercussões nos sistemas e serviços de saúde', NULL, '["Margareth Crisóstomo Portela","Lenice Gnocchi da Costa Reis","Sheyla Maria Lemos Lima"]', 'Série Informação para ação na Covid-19 | Fiocruz', 'Brasil', 'SciELO Books', 'books', 2022, '2022-01-26', 'pt', 'book', 'medical-health', 'Ciencias Médicas y de la Salud', 'Medicine', 'Em seus boletins e notas técnicas, divulgados desde o início da pandemia, o Observatório Covid-19 Fiocruz tem apresentado dados, informações e balanços que indicam uma série de tendências para os sistemas e organizações de saúde de todo o país. Em meio a esse contexto, o Observatório e a Editora Fiocruz lançam mais um e-book gratuito, reunindo um compilado de análises, experiências e reflexões para tempos tão desafiadores. Dividido em quatro partes, que englobam um total de 30 capítulos, o volume é um esforço conjunto de 159 pesquisadoras e pesquisadores. A primeira parte faz um panorama sobre o enfrentamento da Covid-19 em âmbitos nacional e internacional. Em seguida, a obra é centrada na organização do cuidado e dos serviços na pandemia. A parte três é dedicada aos profissionais da saúde que atuam na linha de frente da pandemia no Brasil. Já a última parte relata experiências que focam especialmente em ações de organização de serviços na atenção primária. Este é o quarto livro da série "Informação para Ação na Covid-19", que tem como objetivo reunir o conjunto de respostas, pesquisas e ações técnicas produzidas pela Fiocruz durante a pandemia. Com apoio da rede SciELO Livros, a iniciativa disponibiliza as obras exclusivamente em formato digital e acesso aberto.', '["COVID-19 pandemic","health system organization","health services","primary care","healthcare workers","pandemic response","health system challenges","Brazil"]', '10.7476/9786557081587', '9786557081587', 'https://books.scielo.org/id/kymhj', 'https://books.scielo.org/id/kymhj/pdf/portela-9786557081587.pdf', NULL, 'https://books.scielo.org/id/kymhj/cover/cover_thumbnail.jpeg', NULL, 26, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-kynm8', 'kynm8', 'Volta miúda: quilombo, memória e emancipação', NULL, '["Raíssa Félix"]', 'EDITUS', 'Brasil', 'SciELO Books', 'books', 2020, '2020-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Mostrando o quilombo de Volta Miúda (Caravelas/Ba), os remanescentes e suas histórias, a autora apresenta perfis biográficos dos anciões que ali habitam, inspirados no jornalismo literário; o estado de colonialidade da nação brasileira e o papel no direito e do conhecimento no processo assimilacionista e negacionista das identidades; além de analisar a retomada da oralidade, seu caráter ancestral e de resistência.', '["quilombos","quilombola communities","memory","emancipation","coloniality","negationism","identity","oral tradition","resistance"]', '10.7476/9786586213317', '9786586213317', 'https://books.scielo.org/id/kynm8', 'https://books.scielo.org/id/kynm8/pdf/felix-9786586213317.pdf', NULL, 'https://books.scielo.org/id/kynm8/cover/cover_thumbnail.jpeg', NULL, 2, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-kyvkh', 'kyvkh', 'José de Alencar: sou americano para o que der e vier', NULL, '["Weslei Roberto Cândido"]', 'LA Referencia (Red Federada de Repositorios Institucionales de Publicaciones Científicas)', 'Brasil', 'SciELO Books', 'books', 2016, '2016-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'Esta tese tem como objetivo apresentar o romancista José de Alencar como o fundador do romance americano no Brasil, lendo seus romances, prefácios e notas que deixou às suas narrativas, pelo viés de um olhar americano. Desta maneira, o conceito de americanidade possibilitará uma leitura da obra alencariana no âmbito das negociações identitárias. Para tanto, conceitos que estão sob a capa da americanidade como entre-lugar, casa-grande e senzala, tropicalismo, transculturação, indigenismo, serão analisados nos romances de Alencar, pois estes conceitos se cruzam na construção de um discurso que tenta reinventar e explicar a América continuamente. Ao debater estes temas, postular-se-á a figura do romancista como aquele que primeiro defendeu, no Brasil, a construção de um romance das Américas, que propôs narrar a lenta gestação do povo americano no seu projeto de literatura. Alencar também foi o primeiro a se auto-definir como americano publicamente no jornal O Globo. O sentimento de americanidade em Alencar poderá ser verificado nos diálogos estabelecidos, por seus romances, com outros romancistas e escritores do continente. Todos pensando na construção da identidade americana em seus textos. Assim, Domingo Faustino Sarmiento, José Hernández, Juan León Mera, Clorinda Matto de Turner, Jorge Icaza e Ciro Alegría, serão vistos em contraponto com a produção romanesca de Alencar. Todos estes autores privilegiando o espaço americano como seu lugar de enunciação na defesa de uma produção cultural própria do continente americano, da qual seus romances, ensaios e poemas são portadores. Portanto, a tese propõe um trabalho de comparatismo literário interamericano, que tem como centro de discussões a própria América nos seus mais diversos cruzamentos...', '["José de Alencar","American novel","Brazilian literature","identity construction","transculturation","indigenism","tropicalism","betweenness centrality","O Globo","Domingo Faustino Sarmiento","José Hernández","Juan León Mera"]', '10.7476/9788576286943', '9788576286455', 'https://books.scielo.org/id/kyvkh', NULL, NULL, 'https://books.scielo.org/id/kyvkh/cover/cover_thumbnail.jpeg', 224, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-kz2n8', 'kz2n8', 'Radio comunitaria en pandemia: aprendizajes y experiencias', NULL, '["Nogueira, Maria Lúcia Porto Silva"]', 'Universidad Politécnica Salesiana Repositorio Digital (Universidad Politécnica Salesiana)', 'Ecuador', 'SciELO Books', 'books', 2021, '2021-01-01', 'es', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', '¿Qué papel tuvieron las radios comunitarias durante la pandemia? Los autores de esta publicación analizan el contexto y los desafíos de la comunicación popular en Ecuador. La infodemia, la proliferación de noticias falsas, las dificultades de los medios de comunicación tradicionales en llegar con información clave en la prevención de la enfermedad reactivó la importancia de las radios comunitarias. A través de ellas, en los lugares más apartados, sobre todo en la ruralidad, la población se enteró de las medidas de prevención, de las convocatorias para las pruebas de detección del virus e incluso de los decesos ocurridos a causa del Covid-19 en sus territorios. Así mismo, la radio ha tenido una importancia fundamental en la modalidad virtual de educación durante el confinamiento.', '["community radio","COVID-19 pandemic","infodemic","misinformation","public communication","rural communities","health information dissemination","COVID-19 testing","Ecuador"]', '10.7476/9789978106808', '9789978105979', 'https://books.scielo.org/id/kz2n8', 'https://books.scielo.org/id/kz2n8/pdf/grijalva-9789978106808.pdf', 'https://books.scielo.org/id/kz2n8/epub/grijalva-9789978106808.epub', 'https://books.scielo.org/id/kz2n8/cover/cover_thumbnail.jpeg', 126, 2, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-kz4kj', 'kz4kj', 'Prazer e desejo em Aristóteles', NULL, '["Juliana Ortegosa Aggio"]', 'EDUFBA', 'Brasil', 'SciELO Books', 'books', 2017, '2017-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'Esta tese pretende tratar do problema da constituição do fim da ação, objeto de nosso desejo. Visto que a apreensão correta do fim depende da aquisição da virtude moral, é preciso não apenas verificar a possibilidade da virtude ser adquirida, mas também como tal possibilidade se realiza através da educação moral dos desejos. Em primeiro lugar, devemos compreender o que significa educar o desejo. Com efeito, se educar o desejo significa se habituar a ter prazer com o que se deve, então devemos antes examinar em que sentido a concepção aristotélica de prazer permite que o desejo possa ser educado. Em segundo lugar, investigaremos por que tal educação é necessária para o projeto aristotélico da aquisição da virtude moral, pois, se ela não for necessária, ou bem o desejo teria de ser naturalmente bom, ou ele deveria estar submetido de modo incondicional à razão. Contudo, em oposição às posições intelectualista e naturalista, a ética aristotélica não pressupõe que a razão seja autônoma o suficiente para determinar o fim da ação segundo o conhecimento do bem e do mal, nem que ele seja dado por uma natureza inata boa ou má, porém pressupõe que apenas a razão seja capaz de apreender o que é verdadeiramente bom. Sendo assim, para delimitarmos em que medida, segundo Aristóteles, o desejo e a razão determinam o fim, examinaremos de que modo ele pode ser constituído tanto por uma razão capaz de apreendê-lo corretamente, como por um desejo capaz de tomá-lo como seu objeto, uma vez que o desejo já tenha sido habituado a ter prazer com o que se deve. Ao que tudo indica, a educação moral parece ser condição prévia necessária para que razão e desejo se harmonizem e a razão possa ser efetivamente causa coadjuvante na constituição do fim da ação.', '["Aristotle","pleasure","desire","eudaimonia","moral virtues","habituation","moral education","reason and desire","intellectualism","naturalism","good and evil","Nicomachean Ethics"]', '10.7476/9788523220105', '9788523220105', 'https://books.scielo.org/id/kz4kj', 'https://books.scielo.org/id/kz4kj/pdf/aggio-9788523220105.pdf', NULL, 'https://books.scielo.org/id/kz4kj/cover/cover_thumbnail.jpeg', NULL, 1, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-kz7pr', 'kz7pr', 'Tempo de Festas: homenagens a Santa Bárbara, Nossa Senhora da Conceição e Sant’Ana em Salvador (1860-1940)', NULL, '["Edilece Souza Couto"]', 'EDUFBA', 'Brasil', 'SciELO Books', 'books', 2010, '2010-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'O livro faz um estudo sobre três festas: Santa Bárbara, Conceição da Praia e Sant’Ana. Apesar de possuírem características comuns, as devoções surgiram em épocas diferentes, são realizadas em distantes localidades da cidade e atraem um público também diversificado, de acordo com as posições ocupadas na hierarquia das associações católicas e as atividades profissionais dos seus organizadores. O livro, dividido em cinco capítulos, traz uma nova contextualização das festas. A partir dos relatos documentados pelos que viveram essas experiências, o leitor viajará pelo mundo lúdico desses importantes patrimônios culturais.', '["religious festivals","Santa Barbara","Catholic associations","popular religiosity","cultural heritage","Salvador, Bahia"]', '10.7476/9788523212360', '9788523212360', 'https://books.scielo.org/id/kz7pr', 'https://books.scielo.org/id/kz7pr/pdf/rodrigues-9788523212360.pdf', NULL, 'https://books.scielo.org/id/kz7pr/cover/cover_thumbnail.jpeg', NULL, 4, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-kzjzx', 'kzjzx', 'Evolução: o sentido da biologia', NULL, '["Soumia El Hani","Diogo Meyer"]', 'Editora UNESP', 'Brasil', 'SciELO Books', 'books', 2005, '2005-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'Este livro mostra, numa linguagem clara, como a biologia evolutiva surge ao longo dos séculos XIX e XX e apresenta seus principais conceitos, o contexto cultural e social na qual está inserida e as fronteiras atuais da busca do conhecimento sobre a evolução e a diversidade da vida no nosso planeta. Apresenta como a compreensão da biologia evolutiva é importante para desvendar a origem da AIDS, evitar mortes por infecção hospitalar e até entender a razão dos enjôos na gravidez, entre outros.', '["evolutionary biology","history of evolutionary theory","biodiversity","nosocomial infections","nausea in pregnancy","evolution of life on Earth"]', '10.7476/9788539302758', '9788571396029', 'https://books.scielo.org/id/kzjzx', NULL, NULL, 'https://books.scielo.org/id/kzjzx/cover/cover_thumbnail.jpeg', 136, 36, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-kznpy', 'kznpy', 'O direito e a educação do campo: experiências, aprendizagens, reflexões', NULL, '["Maria José Andrade de Souza","Paulo Rosa Torres","Flávia Almeida Pita"]', 'UEFS Editora', 'Brasil', 'SciELO Books', 'books', 2018, '2018-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Uma das vertentes desta coletânea de estudos é a luta pela democratização do direito à terra. A equipe responsável pela elaboração dos textos denomina-se, e com justiça, Turma Elizabeth Teixeira e a Educação Jurídica, ao homenagear a mulher do trabalhador rural João Pedro Teixeira, assassinado em 1962 quando era o presidente da Liga Camponesa de Sapé, na Paraíba. O volume compreende duas partes — A educação do campo e a formação jurídica: o Direito como campo de lutas e Pronera, universidade pública e educação do campo: reflexões em torno da construção do projeto da turma especial de Direito Elizabeth Teixeira. Um fato digno de nota na história da UEFS (Universidade Estadual de Feira de Santana) é o ingresso, há menos de uma década, de quarenta militantes dos movimentos sociais rurais no curso de Direito.', '["rural education","land rights","legal education","rural social movements","PRONERA","Universidade Estadual de Feira de Santana"]', '10.7476/9786589524915', '9786589524915', 'https://books.scielo.org/id/kznpy', 'https://books.scielo.org/id/kznpy/pdf/souza-9786589524915.pdf', NULL, 'https://books.scielo.org/id/kznpy/cover/cover_thumbnail.jpeg', NULL, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-m2ys3', 'm2ys3', 'Lira dissonante : considerações sobre aspectos do grotesco na poesia de Bernardo Guimarães e Cruz e Sousa', NULL, '["Fabiano Rodrigo da Silva Santos"]', 'Editora UNESP', 'Brasil', 'SciELO Books', 'books', 2009, '2009-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'Lira dissonante analisa as características e funções do grotesco na poesia lírica de Bernardo Guimarães e Cruz e Sousa. O grotesco se manifesta na obra de ambos sob forma de imagens estranhas e inesperadas que sugerem um universo lírico extravagante e rebelde, muitas vezes, oposto às convenções estéticas tradicionais, particularmente, românticas. Trata-se de uma contribuição original aos estudos sobre os dois poetas, na medida em que desvenda as rupturas estéticas, típicas da lírica moderna, empreendidas por eles em seu momento histórico-literário', '["grotesque","Bernardo Guimarães","Cruz e Sousa","lyric poetry","modernist poetry","Romanticism","Brazilian poetry"]', '10.7476/9788579830266', '9788579830266', 'https://books.scielo.org/id/m2ys3', 'https://books.scielo.org/id/m2ys3/pdf/santos-9788579830266.pdf', NULL, 'https://books.scielo.org/id/m2ys3/cover/cover_thumbnail.jpeg', NULL, 10, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-m32qk', 'm32qk', 'Atenção diferenciada: a formação técnica de agentes indígenas de saúde do Alto Rio Negro', NULL, '["Luíza Garnelo","Sully de Souza Sampaio","Ana Lúcia de Moura Pontes"]', 'Editora FIOCRUZ', 'Brasil', 'SciELO Books', 'books', 2019, '2019-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Mais um lançamento da coleção Fazer Saúde, o livro apresenta as contribuições do Curso Técnico de Agentes Comunitários Indígenas de Saúde (CTACIS) na região do Alto Rio Negro do Brasil. Com a proposta de melhorar os serviços de saúde nas comunidades indígenas, o curso foi desenhado como uma estratégia multidisciplinar por diversos atores e implementado de acordo com as realidades locais. Em seus sete capítulos, a obra analisa etapas como o trabalho e a formação dos agentes comunitários e indígenas de saúde, as concepções político-pedagógicas e a organização curricular do CTACIS, os cuidados da saúde de crianças e mulheres indígenas, vigilância alimentar e nutricional em terra indígena, além de temas transversais, como território, cultura e política. O título é resultado de um trabalho conjunto feito pelos autores Luiza Garnelo, médica-sanitarista e antropológa, Sully Sampaio, cientista social, e Ana Lúcia Pontes, médica-sanitarista e pesquisadora da Escola Nacional de Saúde Pública Sergio Arouca (Ensp/Fiocruz). Garnelo e Sampaio são, respectivamente, pesquisadora e bolsista do Instituto Leônidas & Maria Deane (ILMD/Fiocruz Amazônia), unidade técnico-científica da Fundação Oswaldo Cruz no Amazonas. Segundo a médica Myrna Cunningham Kain, pertencente ao povo miskitu, da Nicarágua, e defensora dos povos indígenas, o livro é “”uma contribuição significativa para a implementação efetiva de sistemas de saúde com enfoque intercultural e que permitam a plena realização dos direitos dos povos indígenas e de todos que habitam este continente””.A coleção Fazer Saúde pretende, com seus títulos, contribuir para a qualificação de profissionais, pesquisadores e gestores do SUS, estimulando o diálogo entre conhecimentos científicos, educação, inovações tecnológicas, saberes e práticas em saúde.', '["indigenous health agents","community health agents","technical training","indigenous peoples","Alto Rio Negro","intercultural health","curriculum organization","food and nutrition surveillance","indigenous territories","indigenous rights"]', '10.7476/9786557080115', '9786557080115', 'https://books.scielo.org/id/m32qk', 'https://books.scielo.org/id/m32qk/pdf/garnelo-9786557080115.pdf', NULL, 'https://books.scielo.org/id/m32qk/cover/cover_thumbnail.jpeg', NULL, 10, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-m38sb', 'm38sb', 'Guia ilustrado da morfologia do tecido uretral de ratas', NULL, '["Gelson Rodrigues","Talísia Moreto","Sérgio Alexandre Alcântara do Santos","Flávia Karina Delella","Jaqueline de Carvalho Rinaldi","Sérgio Luís Felisbino","Fernanda Pículo","Gabriela Marini","Débora Cristina Damasceno","Yuri Karen Sinzato","Angélica Mercia Pascon Barbosa","Selma Maria Michelin Matheus","Mariza Vieira Cunha Rudge"]', 'Editora UNESP', 'Brasil', 'SciELO Books', 'books', 2014, '2014-01-01', 'pt', 'book', 'medical-health', 'Ciencias Médicas y de la Salud', 'Medicine', 'incontinência urinária no sexo feminino e também em modelos animais.', '["urinary incontinence","female urinary incontinence"]', '10.7476/9788568334515', '9788568334515', 'https://books.scielo.org/id/m38sb', 'https://books.scielo.org/id/m38sb/pdf/piculo-9788568334515.pdf', NULL, 'https://books.scielo.org/id/m38sb/cover/cover_thumbnail.jpeg', NULL, 1, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-m3gqd', 'm3gqd', 'As formigas poneromorfas do Brasil', NULL, '["Jacques Hubert Charles Delabie","Rodrigo M. Feitosa","José Éduardo Serrão","Cléa dos Santos Ferreira Mariano","Jonathan David Majer"]', 'EDITUS', 'Brasil', 'SciELO Books', 'books', 2015, '2015-01-01', 'pt', 'book', 'agricultural-sciences', 'Ciencias Agrícolas y Veterinaria', 'Agricultural and Biological Sciences', 'Resultado do projeto "Rede Multidisciplinar de Estudos sobre Formigas Poneromorfas do Brasil", o livro apresenta um conjunto de estudos originais ou revisões bibliográficas que focalizam o comportamento, desenvolvimento e contribuições das formigas poneromorfas para o ecossistema.', '["ants","ant behavior","ant development","ant taxonomy","ant ecology","Brazil"]', '10.7476/9788574554419', '9788574554419', 'https://books.scielo.org/id/m3gqd', 'https://books.scielo.org/id/m3gqd/pdf/delabie-9788574554419.pdf', NULL, 'https://books.scielo.org/id/m3gqd/cover/cover_thumbnail.jpeg', NULL, 40, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-m49hk', 'm49hk', 'Uma história das leishmanioses no novo mundo: fins do século XIX aos anos 1960', NULL, '["Jaime Larry Benchimol","Denis Guedes Jogas"]', 'Editora Fiocruz; Traço Fino', 'Brasil', 'SciELO Books', 'books', 2020, '2020-01-01', 'pt', 'book', 'medical-health', 'Ciencias Médicas y de la Salud', 'Medicine', 'O título detalha a extensa trajetória dos estudos sobre as leishmanioses (doença infecciosa causada por parasitas protozoários) no Brasil, englobando a descoberta de seus agentes etiológicos, as diversas espécies de leishmanias associadas às diferentes formas clínicas da doença, seus hospedeiros reservatórios e os flebotomíneos vetores. A obra aborda também aspectos da epidemiologia e ações de controle implantadas em contextos sociopolíticos e momentos diversos. Doenças desafiadoras à compreensão biológica e epidemiológica, as leishmanioses sempre despertaram paixões entre os diversos pesquisadores que a elas se dedicaram, além de levantarem dilemas sobre o controle eficaz e as formas de tratamento. Classificadas em três tipos principais (cutânea, mucocutânea e visceral), as leishmanioses continuam a representar um importante problema de saúde pública, no Brasil, nas Américas e em diversas áreas do Velho Mundo. “A leishmaniose visceral foi controlada no Brasil, mas momentaneamente. Hoje apresenta elevada incidência e vasta distribuição, adquirindo formas graves e letais quando associada à má nutrição e a infecções concomitantes como a Aids. Grandes empreendimentos no interior do país após o golpe civil-militar de 1964 contribuíram para a transformação das leishmanioses cutânea e mucocutânea num problema mais grave também, especialmente na região amazônica”, revela Jaime Benchimol, na apresentação do livro.', '["leishmaniasis","history of medicine","etiology","Leishmania species","reservoir hosts","Phlebotomus vectors","epidemiology","disease control","visceral leishmaniasis","cutaneous leishmaniasis","mucocutaneous leishmaniasis","Amazon basin"]', '10.7476/9786557080207', '9786557080016', 'https://books.scielo.org/id/m49hk', NULL, NULL, 'https://books.scielo.org/id/m49hk/cover/cover_thumbnail.jpeg', 790, 18, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-m4bkn', 'm4bkn', 'Breve dicionário das literaturas africanas', NULL, '["Gallo, Fernanda"]', 'Editora da Unicamp', 'Brasil', 'SciELO Books', 'books', 2022, '2022-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'O crescente número de obras literárias de autoria africana publicadas no Brasil vem sendo acompanhado pela ampliação de pesquisas sobre o tema. Com isso, e ressaltando a importância da interdisciplinaridade que acompanha os estudos sobre o continente africano, os 19 verbetes presentes neste livro são escritos por especialistas das áreas de história, antropologia e literatura e oferecem um conjunto de ferramentas que permitem reflexões mais bem situadas, evitando certas essencializações e expectativas – relativamente comuns – sobre a escrita literária de autoria africana.', '["African literature","literary terminology","interdisciplinarity"]', '10.7476/9788526816527', '9788526815728', 'https://books.scielo.org/id/m4bkn', NULL, NULL, 'https://books.scielo.org/id/m4bkn/cover/cover_thumbnail.jpeg', 287, 1, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-m4kn3', 'm4kn3', 'Rede de frio: fundamentos para a compreensão do trabalho', NULL, '["Marileide do Nascimento Silva","Regina Fernandes Flauzino","Grácia Maria de Miranda Gondim"]', 'Editora FIOCRUZ', 'Brasil', 'SciELO Books', 'books', 2017, '2017-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Um eficiente (e complexo) processo de conservação, armazenamento e distribuição – denominado rede de frio – garante a qualidade das vacinas que chegam às diversas salas de imunização do país. E este é um assunto de extrema importância, especialmente num contexto de ampliação das atividades do Programa Nacional de Imunizações (PNI), o que “requer dos profissionais constantes atualizações técnicas não somente sobre o imunobiológico, mas, também, a respeito de sua guarda e seu manuseio, da organização do sistema de vigilância e, especialmente, da organização e estruturação dos serviços, das fontes de recursos utilizadas etc.”. Este volume “tem como objetivo proporcionar reflexões sobre conceitos e/ou práticas cotidianas inerentes aos serviços de saúde, no campo da rede de frio de imunobiológicos, instrumentalizando os profissionais com novos saberes e visão crítica no exercício de suas atividades”.', '["cold chain","vaccine storage and distribution","immunobiologicals","vaccine quality","immunization programs","health care organization","health professions education","vaccine handling"]', '10.7476/9786557080917', '9786557080917', 'https://books.scielo.org/id/m4kn3', 'https://books.scielo.org/id/m4kn3/pdf/silva-9786586084245.pdf', NULL, 'https://books.scielo.org/id/m4kn3/cover/cover_thumbnail.jpeg', NULL, 10, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-m4s6f', 'm4s6f', 'O estado como empregador de última instância : uma abordagem a partir das finanças funcionais', NULL, '["Guilherme da Rocha Bezerra Costa"]', 'Editora UNESP', 'Brasil', 'SciELO Books', 'books', 2010, '2010-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Economics, Econometrics and Finance', 'No presente trabalho, o emprego será estudado sobretudo através da contribuição de Abba P. Lerner (1903-1982), um economista que seguiu os conceitos de Keynes, no que se refere ao nível de intervenção governamental na economia necessário para um bom funcionamento desta. Lerner aprofunda muito dos debates trazidos à tona por Keynes (1936). O mundo que recentemente entrou em crise, por muito tempo teve como diretriz econômica o uso intenso das ferramentas ortodoxas de condução macroeconômica: baixo intervencionismo governamental, orçamento equilibrado e política monetária direcionada para as metas inflacionárias, como bem salientado por Petiffor (2008) e muitos outros. Esse cenário implica dizer que, no geral, temos baixo gasto governamental e taxas de juros mais elevadas do que em um cenário com políticas (pós-)keynesianas. Em sentido totalmente oposto a esta visão ortodoxa, Lerner apresenta um ferramental teórico para alcançar o nível de Pleno Emprego, almejado, ao menos em tese, por todas as escolas de pensamento econômico. Seu diferencial está na forma de alcançar tal patamar de atividade econômica, ou seja, através dos Gastos Públicos e de políticas monetárias corretas. Portanto, não só o Gasto Público deve ser aumentado na visão de Lerner. A utilidade da taxa de juros também muda. Não servirá apenas para manter estável o preço da moeda. Lerner postula a relevância das Finanças Funcionais não somente para combater crises, como muitos a aceitam, mas sim para ser uma política perene.', '["functional finance","public sector employees","full employment","Keynesian economics","government spending","interest rates","monetary policy","economic crisis"]', '10.7476/9788579830846', '9788579830846', 'https://books.scielo.org/id/m4s6f', 'https://books.scielo.org/id/m4s6f/pdf/costa-9788579830846.pdf', NULL, 'https://books.scielo.org/id/m4s6f/cover/cover_thumbnail.jpeg', NULL, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-m5ny5', 'm5ny5', 'Cartografia de leitura: a biblioteca escolar como espaço de múltiplas aprendizagens', 'a biblioteca escolar como espaço de múltiplas aprendizagens', '["Rita de Cássia Brêda Mascarenhas Lima"]', 'UEFS Editora', 'Brasil', 'SciELO Books', 'books', 2023, '2023-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'O desejo por investigar o objeto aqui em foco nasce de andanças formativas plurais de uma trajetória isso informação que foi sendo constituída pelos muitos caminhos trilhados. Para o processo de investigação, percursos precisam ser selecionados, algumas pedras alicerçam os caminhos e outras precisam ser desviadas; como objetivo era desvelar até que ponto a concepção de biblioteca escolar que perpassa o cotidiano das escolas contribui para o processo de forma leitores, fomos, ao longo do processo, como um mosaico, revelando e descrevendo contornos e condições materiais e funcionamento desse espaço; conhecendo, por meio de observações e diálogos, as percepções dos professores e alunos sobre o papel da biblioteca na formação leitura dos alunos; e, ainda, registrando em apenas experiências de leitura desenvolvidas nas bibliotecas escolares ou articuladas com elas e o impacto dessas experiências para a formação dos leitores.', '["school libraries","reading promotion","reader formation","library as learning space","teacher perceptions","student perceptions","reading experience"]', '10.7476/9788555921698', '9786589524571', 'https://books.scielo.org/id/m5ny5', 'https://books.scielo.org/id/m5ny5/pdf/lima-9788555921698.pdf', NULL, 'https://books.scielo.org/id/m5ny5/cover/cover_thumbnail.jpeg', NULL, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-m5yr9', 'm5yr9', 'Preservação documental: uma mensagem para o futuro', NULL, '["Rubens Ribeiro Gonçalves da Silva"]', 'EDUFBA', 'Brasil', 'SciELO Books', 'books', 2012, '2012-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'Este livro, que apresenta muito mais que aspectos técnicos, é resultado do trabalho de profissionais e pesquisadores do campo da preservação documental e patrimonial da humanidade, que, no período de março a abril de 2010, reuniram-se intensamente em uma rede sociotécnica on-line. O primeiro capítulo discute o papel dos documentos na construção da memória social; o segundo apresenta um estudo sobre aspectos interdisciplinares da preservação; o terceiro, por sua vez, trata da temática da repetição e da diferença; o quarto capítulo considera o movimento da ciência em outras direções; o quinto aborda questões sobre a conscientização de manutenção dos acervos; os capítulos seguintes discorrem sobre grandezas físicas presentes em formas de degradação de acervos e reúnem elementos para provar que, sob certos cuidados, o papel pode ser consultado durante várias gerações.', '["document preservation","social memory","documents","repetition and difference","future of science","collection maintenance"]', '10.7476/9788523212216', '9788523212216', 'https://books.scielo.org/id/m5yr9', 'https://books.scielo.org/id/m5yr9/pdf/silva-9788523212216.pdf', NULL, 'https://books.scielo.org/id/m5yr9/cover/cover_thumbnail.jpeg', NULL, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-m6fcj', 'm6fcj', 'Educação de surdos: formação, estratégias e prática docente', NULL, '["Wolney Gomes Almeida"]', 'EDITUS', 'Brasil', 'SciELO Books', 'books', 2015, '2015-01-01', 'pt', 'book', 'medical-health', 'Ciencias Médicas y de la Salud', 'Psychology', 'O livro permite a construção de novos olhares sobre a educação e a atuação docente. Confronta o educador com a grande necessidade de formação profissional, problematizando o contexto educacional e a realidade da surdez como diferença.', '["deaf education","deaf students","teacher professional development","teaching methods","teaching practice","deafness as difference"]', '10.7476/9788574554457', '9788574554457', 'https://books.scielo.org/id/m6fcj', 'https://books.scielo.org/id/m6fcj/pdf/almeida-9788574554457.pdf', NULL, 'https://books.scielo.org/id/m6fcj/cover/cover_thumbnail.jpeg', NULL, 2, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-m6qzr', 'm6qzr', 'A Biopolítica da Beleza: Cidadania Cosmética e Capital Afetivo no Brasil', NULL, '["Álvaro Jarrín"]', 'Editora FIOCRUZ', 'Brasil', 'SciELO Books', 'books', 2023, '2023-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'A Biopolítica da Beleza examina como a beleza se tornou um objetivo da saúde nacional no Brasil. Por meio de um trabalho de campo etnográfico realizado em hospitais brasileiros, o autor mostra como cirurgiões plásticos e pacientes atuam no sistema público de saúde a fim de transformar a beleza em um direito básico de saúde.', '["biopolitics","beauty","cosmetic surgery","affective capital","right to health","public health system","plastic surgeons","patients","Brazil"]', '10.7476/9786557082102', '9786557081457', 'https://books.scielo.org/id/m6qzr', NULL, NULL, 'https://books.scielo.org/id/m6qzr/cover/cover_thumbnail.jpeg', 381, 1, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-m6zjx', 'm6zjx', 'O meu corpo sou eu? Narrativas de cadeirantes sobre a construção da imagem corporal', NULL, '["Carla Borges de Andrade"]', 'UEFS Editora', 'Brasil', 'SciELO Books', 'books', 2022, '2022-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'O livro revela que cada cadeirante experiencia elementos e etapas muito particulares relacionadas ao modo como foi construindo e percebendo sua imagem corporal antes e após a aquisição da deficiência, que partem das relações intra e interpessoais vivenciadas por cada pessoa, cuja interpretação se dá a partir de suas subjetividades. Também evidencia uma íntima relação entre a pessoa e a cadeira de rodas, pois a imagem corporal se apropria desse aparelho, tornando-o uma extensão do próprio corpo que lhe abre possibilidades, ainda que para os outros seja visto como símbolo de limitação. Assim, a cadeira de rodas se liga ao corpo dessas pessoas, esse corpo que é delas, esse corpo que é elas.', '["wheelchair users","body image","disability","lived experience","subjectivity","wheelchairs","embodiment","social attitudes toward disability","personal narrative"]', '10.7476/9788555921193', '9786589524281', 'https://books.scielo.org/id/m6zjx', NULL, NULL, 'https://books.scielo.org/id/m6zjx/cover/cover_thumbnail.jpeg', 335, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-m6zy7', 'm6zy7', 'Derecho internacional y terrorismo', NULL, '["Juan Ramón Martínez Vargas"]', 'Editorial Universidad del Rosario', 'Colombia', 'SciELO Books', 'books', 2014, '2014-01-01', 'es', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'El ataque terrorista del 11-S determinó el nacimiento de una nueva etapa del derecho internacional. No sólo implicó la materialización de un acto de hiperterrorismo, sino que determinó un cambio en la sociedad internacional, priorizando la agenda global en torno al discurso de la lucha contra el terrorismo y determinando una reconfiguración del derecho internacional, que se aparta de los principios generales que fundamentan la regulación jurídica universal. Uno de estos presupuestos vertebrales es el deber de todo Estado de abstenerse, en sus relaciones internacionales de recurrir a la amenaza o al uso de la fuerza, principio que se ha vulnerado en la llamada y discutida “lucha contra el terrorismo” con acciones armadas que han sido emprendidas en los últimos años en diferentes puntos del planeta, en aparente respuesta a ataques o amenazas de grupos que utilizan el miedo como forma de lucha. En este contexto, surge la necesidad de establecer si ¿los actos terroristas pueden ser entendidos como actos de agresión?, y en esa medida analizar si ¿se ha modificado el ejercicio de la legítima defensa frente a actos terroristas? En este libro se abordan dichas cuestiones desde el prisma del derecho a través de un completo conjunto de fuentes, que hacen de esta obra una herramienta de consulta y un instrumento para entender el derecho internacional contemporáneo.', '["international law","terrorism","September 11 attacks","counterterrorism","use of force","prohibition of the use of force","state responsibility","self-defense","acts of aggression"]', '10.7476/9789587384710', '9789587384703', 'https://books.scielo.org/id/m6zy7', NULL, NULL, 'https://books.scielo.org/id/m6zy7/cover/cover_thumbnail.jpeg', 546, 6, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-m7tn7', 'm7tn7', 'Genes: fatos e fantasias', NULL, '["Eloi Souza Garcia"]', 'Editora FIOCRUZ', 'Brasil', 'SciELO Books', 'books', 2006, '2006-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'O livro traz uma análise sobre a fronteira entre ciência e tecnologia, focalizando as novas idéias da era pós-genômica. Com uma linguagem clara e compreensível, o autor analisa os avanços científicos e suas conseqüências para a humanidade, com foco no desenvolvimento da biologia molecular e da genética.', '["post-genomic era","science and technology","molecular biology","genetics"]', '10.7476/9786557081020', '9786557081020', 'https://books.scielo.org/id/m7tn7', 'https://books.scielo.org/id/m7tn7/pdf/garcia-9786557081020.pdf', NULL, 'https://books.scielo.org/id/m7tn7/cover/cover_thumbnail.jpeg', NULL, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-m844g', 'm844g', 'O rural em regiões metropolitanas: a Fazenda Engenho Novo, São Gonçalo', NULL, '["Marcelo Guerra Santos"]', 'EDUERJ', 'Brasil', 'SciELO Books', 'books', 2020, '2020-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Apresenta um olhar amplo sobre a história e a situação atual da Fazenda Engenho Novo (FEN), área localizada no distrito de Monjolos, no município de São Gonçalo. A FEN é um dos exemplos, entre tantos outros na Região Metropolitana do Rio de Janeiro, de áreas rurais que persistem em meio à metrópole, graças à resistência de trabalhadores aos avassaladores processos de urbanização. De caráter interdisciplinar, a obra aborda aspectos diversos do cenário local, tais como as características da comunidade, as alternativas para revitalização do solo e da agricultura familiar, o uso de plantas medicinais e os saberes locais entre os camponeses, o turismo e a preservação da memória, e o patrimônio e educação ambientais. O livro é fruto de reflexão sobre questões socioambientais propostas pelo grupo de pesquisa Estudos Ambientais no Leste Metropolitano do Rio de Janeiro, da Faculdade de Formação de Professores de São Gonçalo, da UERJ.', '["São Gonçalo","metropolitan periphery","family farming","land revitalization","medicinal plants","local knowledge","rural tourism","memory preservation","cultural heritage","environmental education","socio-environmental problems"]', '10.7476/9786500030303', '9786500030303', 'https://books.scielo.org/id/m844g', 'https://books.scielo.org/id/m844g/pdf/santos-9786500030303.pdf', NULL, 'https://books.scielo.org/id/m844g/cover/cover_thumbnail.jpeg', NULL, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-m8d8m', 'm8d8m', 'Diseño hidráulico de plantas de tratamiento de agua potable', NULL, '["Miguel Araque Arellano"]', 'Editorial Abya-Yala', 'Ecuador', 'SciELO Books', 'books', 2022, '2022-01-01', 'es', 'book', 'natural-sciences', 'Ciencias Naturales y Exactas', 'Environmental Science', 'Teniendo en cuenta la importancia de la calidad del agua potable para el consumo humano, los autores de esta obra han realizado esta recopilación basada en bibliografía seleccionada, así como en experiencias en el ámbito de la docencia y la vinculación con la colectividad en la Universidad Politécnica Salesiana. En esta publicación se abordan cinco temas: El agua en la naturaleza, Química acuática, Planta de tratamiento de agua potable, Epidemiología hídrica y prevención de enfermedades de transmisión hídrica y La importancia de la agricultura en el aprovechamiento del recurso agua. Además, una descripción detallada de la metodología de diseño de las unidades de tratamiento de una planta de agua potable considerando su utilidad en la enseñanza universitaria.', '["hydraulic design","drinking water treatment plant","water quality","water chemistry","waterborne disease prevention","university teaching"]', '10.7476/9789978108208', '9789978108208', 'https://books.scielo.org/id/m8d8m', 'https://books.scielo.org/id/m8d8m/pdf/araque-9789978108208.pdf', NULL, 'https://books.scielo.org/id/m8d8m/cover/cover_thumbnail.jpeg', NULL, 6, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-m9', 'm9', 'Ficar na escola: um furo no afeto', NULL, '["Maria de Lourdes S. Ornellas"]', 'EDUFBA', 'Brasil', 'SciELO Books', 'books', 2008, '2008-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Este livro, desde a escolha provocativa do título Ficar na escola: um furo no afeto, busca decifrar o fenômeno ficar no espaço de três escolas estaduais do estado da Bahia, possibilitando um novo olhar sobre as relações afetivas do adolescer na escola, que inquietam pais, professores e estudiosos. A obra é fruto de uma pesquisa com trabalho de campo, decorrente de entrevistas semiestruturadas, audição de discursos de adolescentes, observação de seus comportamentos, e análise de seus desenhos, construindo um trabalho rigoroso de interpretação e análise do material coletado. O ficar, nesse livro, pode ser visto como um sintoma da contemporaneidade, um jeito novo de adolescer e aprender a fazer escolhas. A autora revela, ainda, que a temática ficar pode ser um conteúdo pedagógico disciplinar a ser trabalhado, no sentido de que os componentes curriculares contemplem os valores do compromisso, profundidade, estabilidade, tolerância, prazer, responsabilidade, laços, gosto pelos estudos, na busca da construção de um sujeito afetivo que valorize o homem e a mulher na sua subjetividade e singularidade.', '["school dropout","affective bonds","adolescents","commitment","tolerance","responsibility"]', '10.7476/9788523209377', '9788523209377', 'https://books.scielo.org/id/m9', 'https://books.scielo.org/id/m9/pdf/ornellas-9788523209377.pdf', NULL, 'https://books.scielo.org/id/m9/cover/cover_thumbnail.jpeg', NULL, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-m96dh', 'm96dh', 'Dar a vida e cuidar da vida: feminismo e ciências sociais', NULL, '["Lucila Scavone"]', 'Editora UNESP', 'Brasil', 'SciELO Books', 'books', 2004, '2004-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Com textos que mostram, explícita e implicitamente, a ligação do feminismo com as Ciências Sociais, pelo viés da Sociologia das Relações Sociais, no campo da saúde, este livro é a compilação de diversos artigos produzidos na última década, com base em pesquisas teóricas e empíricas realizadas pela autora sobre a problemática sociológica das mulheres, especificamente no referido campo. Uma lenta construção amadurecida ao longo de seu ofício de socióloga, no ensino e na pesquisa, que teve influência vital da experiência feminista que vivenciou nos anos 70 e 80, na França e no Brasil.', '["feminism","social sciences","women''s health","sociology of women","feminist sociology","Brazil"]', '10.7476/9788539302949', '9788571395480', 'https://books.scielo.org/id/m96dh', NULL, NULL, 'https://books.scielo.org/id/m96dh/cover/cover_thumbnail.jpeg', 205, 46, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-m9xn5', 'm9xn5', 'Promoção da saúde: conceitos, reflexões, tendências', NULL, '["Dina Czeresnia","Carlos Machado de Freitas"]', 'Editora FIOCRUZ', 'Brasil', 'SciELO Books', 'books', 2009, '2009-01-01', 'pt', 'book', 'medical-health', 'Ciencias Médicas y de la Salud', 'Medicine', 'A idéia de promoção procura relacionar saúde e condições de vida, ressaltando a necessidade de uma vida saudável e a importância da participação coletiva e das habilidades individuais neste processo. Promoção da Saúde: conceitos, reflexões, tendências aponta a multiplicidade e a vitalidade da saúde coletiva brasileira nesta área, afirmando-se como uma reflexão crítica e nada reducionista acerca dos discursos e dos conceitos originários a partir deste tema. O livro se constitui de oito artigos que abordam, de diferentes maneiras, o tema da promoção da saúde, que aqui não é encarada unicamente como um movimento político sanitário, mas também como temática de investigação. A discussão teórica de conceitos, tais como saúde, risco, vulnerabilidade, intersetorialidade e vigilância, torna evidente os desafios surgidos e ainda existentes nas tentativas de mudança das práticas de saúde na atualidade.', '["health promotion","collective health","living conditions","healthy life","collective participation","individual skills","health risks","vulnerability","intersectorality","health surveillance"]', '10.7476/9788575413531', '9788575411834', 'https://books.scielo.org/id/m9xn5', NULL, NULL, 'https://books.scielo.org/id/m9xn5/cover/cover_thumbnail.jpeg', 176, 130, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-mbfb7', 'mbfb7', 'A grande Ibéria convergências e divergências de uma tendência', NULL, '["Vamireh Chacon"]', 'Editora UNESP', 'Brasil', 'SciELO Books', 'books', 2005, '2005-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'As culturas conflitam-se e dialogam, entrecruzam-se, não há cultura nem raça puras. A grande Ibéria está aqui na perspectiva brasileira da Nova Ibéria continental americana à Antiga Ibéria peninsular européia, ida e volta: encontros, desencontros e reencontros também pelos oceanos das Áfricas e Ásias lusófonas e hispanófonas até a Oceania das Filipinas e Timor Leste; do passado ao presente e futuro num mundo de culturas em blocos lingüísticos, fonopolítica ora liderada pelos anglófonos diante da resistência de outros povos. (Co-edição: Paralelo 15)', '["Iberian Peninsula","cultural convergence","cultural hybridity","English language dominance","Lusophone culture"]', '10.7476/9788539303090', '9788571396005', 'https://books.scielo.org/id/mbfb7', NULL, NULL, 'https://books.scielo.org/id/mbfb7/cover/cover_thumbnail.jpeg', 272, 3, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-mbpt6', 'mbpt6', 'Sustentabilidade, circuitos curtos de abastecimento e compras públicas', NULL, '["Parrado-Barbosa, Alvaro","Ruiz, Eliziane Nicolodi","Triches, Rozane Marcia"]', 'Editora UFFS', 'Brasil', 'SciELO Books', 'books', 2022, '2022-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Esta obra, a partir de aportes teóricos e pesquisas empíricas, vincula temas, como sustentabilidade, abastecimento e papel do Estado em direcionar o sistema alimentar à garantia de soberania e segurança alimentar e nutricional. Pela complexidade das temáticas, lançou-se mão da interdisciplinaridade; dessa forma, o livro foi organizado e escrito a várias mãos, com pesquisadores de diferentes áreas do conhecimento. Também se buscou tratar estas temáticas calcadas na diversidade de experiências de países latino-americanos e europeus para ilustrá-las de forma mais ampla e abrangente. “Sustentabilidade, circuitos curtos de abastecimento e compras públicas de alimentos” constitui-se de dezesseis capítulos, divididos em três partes. A primeira delas refere-se a discussões mais abrangentes e conceituais sobre sustentabilidade alimentar a partir de diferentes perspectivas e abordagens. Trata-se de abordagens que perpassam o sistema alimentar, sua relação com a soberania e a segurança alimentar, com as formas de abastecimento, com as dietas e com o papel do Estado e suas políticas. A segunda debruça-se sobre experiências com circuitos curtos de abastecimento e compras públicas de alimentos, não somente brasileiras, mas de diferentes países, oferecendo ao leitor uma ideia ampliada e variada de ações, políticas e programas que têm viabilizado novas relações entre produção e consumo em diferentes contextos. A terceira trata exclusivamente das compras públicas de alimentos para os RU das Universidades Federais do Sul do Brasil. Em grande parte, é fruto de pesquisas realizadas a partir do Projeto intitulado “Compras públicas e circuitos curtos da agricultura familiar: a promoção da segurança alimentar e nutricional por meio do abastecimento alternativo no sul do Brasil e Colômbia”.', '["food sustainability","short food supply chains","public food procurement","food sovereignty","food and nutrition security","food system policy","family farming","production-consumption relations","diet"]', '10.7476/9786586545753', '9786586545753', 'https://books.scielo.org/id/mbpt6', 'https://books.scielo.org/id/mbpt6/pdf/parrado-9786586545753.pdf', NULL, 'https://books.scielo.org/id/mbpt6/cover/cover_thumbnail.jpeg', NULL, 2, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-mc9xp', 'mc9xp', 'Historias de familia: etnografía delirante sobre el amor, la violencia y las drogas', NULL, '["César Augusto Tapias Hernández"]', 'Editorial Universidad del Rosario', 'Colombia', 'SciELO Books', 'books', 2014, '2014-01-01', 'es', 'book', 'medical-health', 'Ciencias Médicas y de la Salud', 'Medicine', 'El ejercicio de reunir estas historias, estos conocimientos disponibles, se propuso para encontrar las palabras y los signos que, como prenociones sobre la vida cotidiana de un grupo individuos, ilustraran (no solo) un mar de problemas (sociológicos): anomías, malestares —por ejemplo, los delirios de violencia, el abuso de alcohol y drogas, las rencillas familiares, etc.—, sino también solidaridades y, sobre todo, amores: múltiples y coloridas representaciones que los individuos-partes del grupo (mis familiares y yo mismo) hacemos de nuestro estado, de nuestras condiciones, del lugar que ocupamos con respecto a los demás. Bourdianamente, me corresponde como científico social “demandar al razonamiento, la revelación de las causas estructurales que las palabras y los signos aparentes no develan más que velándolas” (Bourdieu 2000, 558). Intento con este texto, especialmente tras su lectura, hacer conscientes los mecanismos que hacen que funcione el mundo social que construimos en nuestras familias, es decir, la estructura de la interacción que configuramos: la familia en su forma de ser. No para neutralizar los detonantes/causas de las formas anómalas de interacción, ni para resolver los problemas que generan. Basta con comprender las verdaderas causas del malestar que solo se expresan a la luz de la cotidianidad. Si sobrevive la pregunta respecto a ¿cuál es el grado de efectividad de este mensaje sociológico?, respondería que solo quiero hacer/conocer nuestra forma social de interactuar/ser/vivir. Y este hacer/conocer remite a un asunto científico/metodológico con implicaciones políticas: cada repertorio de conocimientos fue obtenido conversando, no interrogando ni siguiendo cuestionario alguno. Se trató de una entrevista etnográfica que incluyó, además de su escritura o transcripción, la lectura posterior entre quienes la hicieron posible. Solo este ejercicio de reflexividad nos permitirá maniobrar con mayor libertad a la hora de seguir siendo parte de este mundo.', '["family","love","violence","drug abuse","alcohol abuse","family conflict","everyday life","social interaction","family structure","Pierre Bourdieu","reflexivity","ethnographic interviews"]', '10.7476/9789587385434', '9789587385434', 'https://books.scielo.org/id/mc9xp', 'https://books.scielo.org/id/mc9xp/pdf/tapias-9789587385434.pdf', NULL, 'https://books.scielo.org/id/mc9xp/cover/cover_thumbnail.jpeg', NULL, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-mcnk2', 'mcnk2', 'Letras UFFS Cerro Largo 10 anos de ensino, pesquisa e extensão', NULL, '["Demétrio Alves Paz","Jeize de Fátima Batista"]', 'Editora UFFS', 'Brasil', 'SciELO Books', 'books', 2021, '2021-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Esta obra apresenta a trajetória dos dez anos do Curso de Letras da UFFS – Campus Cerro Largo, que possui uma importante tarefa: prover a formação de professores numa região até então desprovida de Instituições Federais de Ensino Superior (IFES). Trata-se de alguns estudos, experiências e ações práticas desenvolvidas por colegas e discentes do Curso de Letras – Português e Espanhol – Licenciatura, bem como parceiros profissionais de outras instituições que buscam, da mesma forma, pensar na educação como um meio de construção e transformação social. Ao longo de 15 capítulos, apresentam-se importantes reflexões acerca dos processos de ensino e aprendizagem de línguas, literatura e formação de professores. Há textos de docentes efetivos, substitutos e convidados que contribuíram de alguma forma com a divulgação do conhecimento na UFFS. Letras UFFS Cerro Largo: 10 anos de Ensino, Pesquisa e Extensão oferece múltiplas análises/estudos/pesquisas a partir de experiências nas diferentes áreas do conhecimento, evidenciando um pouco do trabalho desenvolvido no âmbito universitário, no que se refere ao ensino de línguas, literatura e formação de professores.', '["Letters course","teacher professional development","Portuguese language teaching","Spanish language teaching","literature teaching","language teaching and learning","university extension","social transformation through education","federal universities"]', '10.7476/9786586545616', NULL, 'https://books.scielo.org/id/mcnk2', 'https://books.scielo.org/id/mcnk2/pdf/paz-9786586545616.pdf', NULL, 'https://books.scielo.org/id/mcnk2/cover/cover_thumbnail.jpeg', NULL, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-mcwmc', 'mcwmc', 'Mulheres em foco: construções cinematográficas brasileiras da participação política feminina', NULL, '["Danielle Tega"]', 'Editora UNESP', 'Brasil', 'SciELO Books', 'books', 2010, '2010-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'O cinema como objeto de estudo para verificar o modo pelo qual a resistência política à ditadura militar foi representada no período a ela posterior, dando destaque à participação feminina. A análise fílmica possibilitaria observar quais elementos estariam presentes em cena para retratar tal questão, e os estudos de gênero permitiria debater de que forma as relações sociais entre os sexos eram abordadas nos filmes selecionados. Trata-se, portanto, de compreender não apenas como a resistência à ditadura é representada, mas, sobretudo, como esse passado é reconstruído nas diversas formas em que pode ser materializado pela perspectiva feminista, considerando que esta trabalha com elementos fundamentais na luta em torno da memória e pelo reconhecimento de histórias esquecidas. Nesse sentido, procuro privilegiar os pontos onde se cruzam os estudos da memória e o pensamento feminista, visto que este atinge profundamente as necessidades de um resgate histórico ao denunciar o esquecimento de reivindicações, lutas e ações das mulheres.', '["women in film","women''s political participation","Brazilian cinema","military dictatorship","political resistance","gender relations","feminist film criticism","memory studies","feminist theory","women''s history","representation of women in film"]', '10.7476/9788579831232', '9788579831232', 'https://books.scielo.org/id/mcwmc', 'https://books.scielo.org/id/mcwmc/pdf/tega-9788579831232.pdf', NULL, 'https://books.scielo.org/id/mcwmc/cover/cover_thumbnail.jpeg', NULL, 7, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-md7xt', 'md7xt', 'Histórias do vestir masculino: narrativas de moda, beleza, elegância', NULL, '["Ivana Guilherme Símili","Maria Claudia Bonadio"]', 'LA Referencia (Red Federada de Repositorios Institucionales de Publicaciones Científicas)', 'Brasil', 'SciELO Books', 'books', 2017, '2017-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'A concepção de que os homens são fabricados pelas roupas e pela moda norteia o livro. Nas abordagens, as relações históricas, sociais, politicas e culturais estabelecidas pelos homens com as indumentárias intimam e publicam são escrutinadas para revelar modos de vestir, de viver, de sentir, de pensar, de consumir, de amar, de desejar, de praticar a sexualidade, de vivenciar as sensibilidades, as subjetividades, de atuar nos espaços do trabalho, do lazer e das sociabilidades.', '["men''s clothing","masculinity","fashion history","dress and identity","beauty","elegance","clothing consumption","sexuality","subjectivity","sensibility","sociability","gender and dress"]', '10.7476/9788576287445', '9788576287230', 'https://books.scielo.org/id/md7xt', NULL, NULL, 'https://books.scielo.org/id/md7xt/cover/cover_thumbnail.jpeg', 235, 7, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-mfqfm', 'mfqfm', 'Mulheres baianas em tessituras de memórias e ficções: subjetividade femininas', NULL, '["Maria Lúcia Pôrto Silva Nogueira"]', 'EDUNEB', 'Brasil', 'SciELO Books', 'books', 2020, '2020-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', '¿Qué papel tuvieron las radios comunitarias durante la pandemia? Los autores de esta publicación analizan el contexto y los desafíos de la comunicación popular en Ecuador. La infodemia, la proliferación de noticias falsas, las dificultades de los medios de comunicación tradicionales en llegar con información clave en la prevención de la enfermedad reactivó la importancia de las radios comunitarias. A través de ellas, en los lugares más apartados, sobre todo en la ruralidad, la población se enteró de las medidas de prevención, de las convocatorias para las pruebas de detección del virus e incluso de los decesos ocurridos a causa del Covid-19 en sus territorios. Así mismo, la radio ha tenido una importancia fundamental en la modalidad virtual de educación durante el confinamiento.', '["women writers","feminist movements","female subjectivity","patriarchy","memory","fiction","women''s writing","1920s-1960s"]', '10.7476/9786588211304', '9786588211069', 'https://books.scielo.org/id/mfqfm', 'https://books.scielo.org/id/mfqfm/pdf/nogueira-9786588211304.pdf', 'https://books.scielo.org/id/mfqfm/epub/nogueira-9786588211304.epub', 'https://books.scielo.org/id/mfqfm/cover/cover_thumbnail.jpeg', 290, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-mfstr', 'mfstr', 'O horizonte democrático: o hiperpluralismo e a renovação do liberalismo político', NULL, '["Alessandro Ferrara"]', 'Editora da Unicamp', 'Brasil', 'SciELO Books', 'books', 2022, '2022-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'O horizonte democrático nasceu de uma preocupação com a democracia, a herança do liberalismo político e as fontes estéticas da normatividade. Em todo o mundo, a democracia enfrenta desafios sem precedentes, alguns dos quais ironicamente decorrentes de seu próprio sucesso em se estabelecer como horizonte, como a única forma de governo plenamente legítima. Neste livro, investigo a contribuição para a superação daqueles obstáculos que podem ser extraídos do arcabouço normativo desenvolvido por Rawls em O liberalismo político, uma vez que todo o seu potencial é liberado na tripla direção de repensar e pluralizar o ethos democrático, lidar com o hiperpluralismo que permeia nossos espaços políticos e encontrar os caminhos adequados, por meio de argumentos conjecturais, para que a justificação política alcance e inclua o parcialmente razoável. (Do Prefácio).', '["political liberalism","John Rawls","A Theory of Justice","democratic ethos","political justification","legitimacy of democracy"]', '10.7476/9788526816596', '9788526815773', 'https://books.scielo.org/id/mfstr', NULL, NULL, 'https://books.scielo.org/id/mfstr/cover/cover_thumbnail.jpeg', 303, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-mg3c9', 'mg3c9', 'Enlaçando sexualidades: uma tessitura interdisciplinar no reino das sexualidades e das relações de gênero', NULL, '["Messeder, Suely","Castro, Mary Garcia","Laura Moutinho"]', 'EDUFBA', 'Brasil', 'SciELO Books', 'books', 2016, '2016-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'O livro reúne textos que compõem a interdisciplinaridade dos estudos sobre sexualidade e gênero por meio da visão de pesquisadores de diversas áreas do conhecimento, que tratam de assuntos recorrentes da vida cotidiana analisados na perspectiva da educação e da sexualidade, da moralidade e outros temas que permeiam a temática da sexualidade e das relações de gênero.', '["sexuality","gender relations","interdisciplinarity","sex education","morality","everyday life"]', '10.7476/9788523218669', '9788523218669', 'https://books.scielo.org/id/mg3c9', 'https://books.scielo.org/id/mg3c9/pdf/messeder-9788523218669.pdf', NULL, 'https://books.scielo.org/id/mg3c9/cover/cover_thumbnail.jpeg', NULL, 4, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-mh38f', 'mh38f', 'O drama ético na obra de Graciliano Ramos: leituras a partir de Jacques Derrida', NULL, '["Gustavo Silveira Ribeiro"]', 'Editora UFMG', 'Brasil', 'SciELO Books', 'books', 2016, '2016-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'Aproximação crítica de dois escritores (aparentemente) muito distintos, este livro procura revelar como os trabalhos do narrador brasileiro Graciliano Ramos e do filósofo francês Jacques Derrida podem ser lidos de modo conjunto e articulado, tendo como foco principal a reflexão de natureza ética que atravessa, de maneira distinta mas comparável, os textos de ambos. O ponto de contato principal entre eles está no fato de que se dedicaram a pensar, de modo incisivo e bastante original, a questão da alteridade e sua relação com a linguagem, a política e a produção mesma do conhecimento. Ao longo destas páginas conceitos como os de herança, acolhimento, perdão e responsabilidade serão problematizados a partir de uma releitura aguda, informada pelo pensamento contemporâneo sobre cultura e vida literária, de obras-chave de Graciliano Ramos como Vidas secas, Infância e Memórias do cárcere.', '["Graciliano Ramos","Jacques Derrida","ethics","otherness","language","politics","knowledge production","inheritance","hospitality","forgiveness","responsibility","literary culture"]', '10.7476/9788542302929', '9788542301946', 'https://books.scielo.org/id/mh38f', NULL, NULL, 'https://books.scielo.org/id/mh38f/cover/cover_thumbnail.jpeg', 252, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-mh5h8', 'mh5h8', 'A virada testemunhal e decolonial do saber histórico', NULL, '["Márcio Seligmann-Silva"]', 'Editora da Unicamp', 'Brasil', 'SciELO Books', 'books', 2022, '2022-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', '“Este livro pretende ajudar a gerar argumentos para desconstruirmos essa lógica colonial que nos engessa e tende a reproduzir a violência colonial em nossos dias, com práticas racistas, de opressão e violência de classe, misóginas e sempre a favor de uma elite cada vez mais indiferente ao sofrimento dos espezinhados. É importante destacar que, quando falo de ‘virada testemunhal do saber histórico’, me refiro a novas sensibilidades desenvolvidas nesse contexto pós-colonial em que o corpo e sua localização passam a ser reconhecidos como parte da construção de outras narrativas e epistemologias.” (Da Introdução)', '["decoloniality","historical knowledge","colonial violence","postcolonialism","epistemology","body and space","racism","class oppression","misogyny"]', '10.7476/9788526816473', '9788526815315', 'https://books.scielo.org/id/mh5h8', NULL, NULL, 'https://books.scielo.org/id/mh5h8/cover/cover_thumbnail.jpeg', 365, 26, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-mhmbt', 'mhmbt', 'Os sentidos da alfabetização', NULL, '["Maria do Rosário Longo Mortatti"]', 'Editora UNESP', 'Brasil', 'SciELO Books', 'books', 2000, '2000-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'Em um percurso no qual se entrelaçam debates teóricos e metodológicos sobre alfabetização, Mortatti destaca o problema do método como objeto de estudo privilegiado da reflexão pedagógica no Brasil. Essa escolha serve de eixo a uma reconstrução da história da alfabetização, que vai do aparecimento da Cartilha maternal (1876) às pesquisas sobre psicogênese e ontogênese da língua efetuadas nos anos 1980.', '["literacy","history of literacy","literacy teaching methods","pedagogical reflection"]', '10.7476/9788539302697', '9788571392649', 'https://books.scielo.org/id/mhmbt', NULL, NULL, 'https://books.scielo.org/id/mhmbt/cover/cover_thumbnail.jpeg', 370, 60, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-mhx9t', 'mhx9t', 'O cantor-ator: um estudo sobre a atuação cênica do cantor na ópera', NULL, '["Cristine Bello Guse"]', 'Editora UNESP', 'Brasil', 'SciELO Books', 'books', 2011, '2011-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'É um livro único. Emerge do diálogo entre duas lingua­gens artísticas, o teatro e a ópera. Cristine Bello Guse apresenta poeticamente os desafios que o cantor-ator enfrenta na composição de seu papel dramático ao encenar uma ópera. Atualmente os espetáculos de ópera incorpo­ram novas tecnologias fazendo com que este dinamismo abra possibilidades para uma atuação na qual os cantores, além de brindar o público com suas excelentes vozes e sensibilidade musical, também se movimentem livremente pelo espaço cênico interpretando personagens na repre­sentação da situação dramática. Fruto de sua pesquisa de mestrado, este livro se traduz pelo encantamento de uma obra de arte.', '["opera singers","stage acting","opera staging","theatre and opera","stage movement","vocal performance","stage space"]', '10.7476/9786557145333', '9786557145333', 'https://books.scielo.org/id/mhx9t', 'https://books.scielo.org/id/mhx9t/pdf/guse-9786557145333.pdf', NULL, 'https://books.scielo.org/id/mhx9t/cover/cover_thumbnail.jpeg', NULL, 2, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-mj3kk', 'mj3kk', 'O mito do Cristianismo ininterrupto no arquipélogo de Malta', NULL, '["Thomas Bonnici"]', 'LA Referencia (Red Federada de Repositorios Institucionales de Publicaciones Científicas)', 'Brasil', 'SciELO Books', 'books', 2016, '2016-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'O arquipélago de Malta e Gozo, no mar mediterrâneo, se caracterizam por mais de 5000 anos de historia e colonização por diversos povos que deixaram suas marcas idiossincráticas. Um dos eventos mais importantes foi o naufrago e a estada de Paulo de Tarso em 60 EC que gerou a tradição segundo a qual o Cristianismo perdurou desde aquela época ate a contemporaneidade, sem interrupções. O mito do Cristianismo ininterrupto no arquipélago de Malta questiona essa versão e tenta provar a hipótese de que arqueologicamente o Cristianismo começou no século 4 EC. Abundam hipogeus e catacumbas que revelam a presença do Cristianismo entre os séculos 5 e 9 EC, embora o culto ao imperador fosse predominante durante a ocupação romana, enquanto o período bizantino carecesse de evidencia arqueológica farta e decisiva. Comente na década de 1960 que as ruinas de uma basílica bizantina foram encontradas. Ademais houve uma interrupção radical étnica e religiosa no período de dominação muçulmana entre 870 e 1048. Durante quase 180 anos as ilhas de Malta e Gozo ficaram despovoadas e somente em meados do século 11 colonos muçulmanos siculo-arabes iniciaram uma nova colonização. O arquipélago começou a tornar-se lentamente cristão a partir da segunda invasão normando por Rogério II em 1127; contudo, após cem anos desse evento, a população muçulmana ainda era predominante. O Cristianismo foi reintroduzido da sicilia efetivamente no século 12 EC, mas se consolidou somente nos séculos 13 e 14. Devido a um senso de culpa referente a um passado muçulmano que desejava suprimir, a população maltesa adquiriu uma profunda consciência crista e europeia e fabricou lendas e tradições sobre o “passado cristão” que compensariam e quase anulariam a interrupção religiosa. Esse livro narra a historia dessas tradições e recoloca a história do arquipélago sobre uma epistemologia histórica solida, dirimindo as fabricações construídas durante séculos.', '["Malta","Gozo","Paul the Apostle","catacombs","hypogeum","Byzantine period","Roman period","Islamic rule","Norman Conquest","Roger II","Christianization","religious memory"]', '10.7476/9788576287452', '9788576286851', 'https://books.scielo.org/id/mj3kk', NULL, NULL, 'https://books.scielo.org/id/mj3kk/cover/cover_thumbnail.jpeg', 204, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-mjk9h', 'mjk9h', 'Por inflexões decoloniais de corpos e identidades de gênero inconformes: uma análise autoetnográfica da cisgeneridade como normatividade', 'uma análise autoetnográfica da cisgeneridade como normatividade', '["Viviane Vergueiro Simakawa"]', 'EDUFBA', 'Brasil', 'SciELO Books', 'books', 2023, '2023-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'A autora busca fazer uma contribuição para a transformação dos termos e condições a partir dos quais pensamos a inferiorização e marginalização das populações de identidades de gênero trans, travestis, não binárias e não ocidentais por suas expressões e identidades de gênero não normativas. Com reflexões e análises autoetnográficas multidisciplinares e indisciplinadas, Vergueiro analisa as condições materiais, epistêmicas e existenciais dessas populações a partir dos movimentos entre a ciscolonialidade e as inflexões decoloniais em cistemas acadêmicos, legais, de saúde e em dimensões existenciais. Propõe-se a relevância de se estudar a produção institucional e discursiva da cisgeneridade, cisnormatividade e ciscolonialidade, conceitos que podem ser úteis à transformação de tais termos e condições.', '["cisnormativity","decoloniality","gender identity","transgender identity","travestis","non-binary people","marginalization","academic institutions","health care system","legal system","discursive production"]', '10.7476/9786556308890', '9786556305417', 'https://books.scielo.org/id/mjk9h', NULL, NULL, 'https://books.scielo.org/id/mjk9h/cover/cover_thumbnail.jpeg', 337, 2, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-mk2pw', 'mk2pw', 'A pesquisa no campo da alimentação e nutrição no Brasil: pluralidade epistêmica e produtividade científica', NULL, '["Shirley Donizete Prado","Myriam de Lima Ramagem Martins","Maria Cláudia da Veiga Soares Carvalho"]', 'EDUERJ', 'Brasil', 'SciELO Books', 'books', 2021, '2021-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Este trabalho corresponde a um dos resultados de cerca de dez anos de presença na pós-graduação stricto sensu no campo da Alimentação e Nutrição no Brasil. Este novo livro da Série Sabor Metrópole foi construído no interior do Núcleo de Estudos sobre Cultura e Alimentação (NECTAR) do Instituto de Nutrição da Universidade do Estado do Rio de Janeiro (UERJ). Dirige-se aos objetos e metodologias, regras vigentes, agentes e seus habitus no campo da Alimentação e Nutrição no Brasil. Busca compreender relações sociais presentes nesse campo científico a partir do recorte empírico correspondente aos programas de pós-graduação que conformam a Área de Avaliação “Nutrição” na CAPES.', '["food and nutrition research","epistemological pluralism","research productivity","graduate programs","CAPES evaluation criteria","academic habitus"]', '10.7476/9786588808139', '9786587949437', 'https://books.scielo.org/id/mk2pw', NULL, NULL, 'https://books.scielo.org/id/mk2pw/cover/cover_thumbnail.jpeg', 234, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-mk553', 'mk553', 'Louis Couty e o império do Brasil: o problema da mão de obra e a constituição do povo no final do século XIX (1871-1891)', NULL, '["Moisés Stahl"]', 'Editora UFABC', 'Brasil', 'SciELO Books', 'books', 2016, '2016-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', '"As últimas três décadas do século XIX marcaram momentos decisivos na história do Brasil. A diversificação dos interesses das elites, fenômeno que esteve ligado à transição do trabalho escravo para o trabalho livre, resulta numa dinâmica complexa de críticas ao regime monárquico. Nesse contexto, vários grupos sociais alijados pela política imperial adquiriram condições para expressar publicamente seus dissensos e projetos. Na composição desta conjuntura encontramos vários nomes, entre eles o de Louis Couty, que até o momento figurava à sombra de eminentes figuras do Império. Este livro examina de modo profícuo e original a atuação e o pensamento do cientista francês Louis Couty entre as décadas de 1870 e 1890, cuja contribuição ocorreu num momento de transformação/modernização das instituições científicas e criação de novos lugares de ciência visando à constituição de uma ciência moderna no Brasil. Couty agiu em vários contextos do final dos Oitocentos no país. Ele foi responsável pela introdução do campo de estudo da fisiologia experimental em terras brasileiras, escreveu livros sobre a escravidão, artigos sobre o café, relatórios sobre a erva mate, sempre com o olhar de um homem da ciência, que via problemas e procurava soluções, de acordo com o pensamento da época. Louis Couty e o Império do Brasil (1871 – 1891) é um livro que nos auxilia mais especificamente na compreensão do imbricado problema da mão de obra porque revela as conexões que este problema estabelecia com os anseios das elites imperiais quanto à constituição de um povo idealizado, e as conexões com a ciência, que traria as soluções para os problemas. Por tudo isso, Moisés Stahl entende Couty como um mediador das ideias novas que chegaram ao país a partir da década de 1870, ideias que Couty operou em solo brasileiro a partir da definição que realizou de uma de suas disciplinas, a Biologia Industrial, onde mesclou os conceitos evolucionistas da época à realidade produtiva e social do Brasil, lançando teses sobre o país e seu povo. Desse modo, a associação enigmática entre raça e nação, vivida de forma tão angustiada pelas elites brasileiras do final do século XIX ganha, através desse estudo, uma inteligibilidade nova."', '["Brazilian Empire","labor question","experimental physiology","slavery","abolition of slavery","free labor","national identity","scientific modernization","mate tea","evolutionism","19th-century science","history of science in Brazil"]', '10.7476/9788568576854', '9788568576854', 'https://books.scielo.org/id/mk553', 'https://books.scielo.org/id/mk553/pdf/stahl-9788568576854.pdf', NULL, 'https://books.scielo.org/id/mk553/cover/cover_thumbnail.jpeg', NULL, 5, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-mkt7s', 'mkt7s', 'Jorge Amado: et les chemins de l’exil', NULL, '["Rui Afonso"]', 'Editora UNESP', 'Brasil', 'SciELO Books', 'books', 2019, '2019-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'Se, como se diz, a história pertence aos vencedores, o mesmo ocorre com a história intelectual. Desde a queda do comunismo, houve uma proliferação de artigos e livros equiparando o comunismo ao nazismo, difamando todos aqueles que seguiram, mesmo que apenas durante algum tempo, as cores vermelhas. Diante dessa condenação global, um apelo por maior rigor e objetividade pareceria apropriado. O caso do escritor brasileiro Jorge Amado, ativista comunista exilado na França e depois na Tchecoslováquia nos anos do pós-guerra, pode servir de modelo para ilustrar a complexidade do engajamento de um membro do Partido. Como Jorge Amado viveu as esperanças, decepções e grandes contradições desse período? O que sua jornada individual tem em comum com a de outros escritores e intelectuais do século XX? O que aprendemos com o destino desse grande escritor brasileiro? Escrito em francês, este livro se debruça sobre essas questões e procura fornecer ao leitor chaves para decifrá-las.', '["Jorge Amado","communism","exile","intellectual history","Brazilian writers","political engagement of writers","anti-communism","memory of communism","Czechoslovakia","20th century"]', '10.7476/9788595463431', '9788595463431', 'https://books.scielo.org/id/mkt7s', 'https://books.scielo.org/id/mkt7s/pdf/afonso-9788595463431.pdf', NULL, 'https://books.scielo.org/id/mkt7s/cover/cover_thumbnail.jpeg', NULL, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-mktc3', 'mktc3', 'Caipira sim, trouxa não: representações da cultura popular no cinema de Mazzaropi', NULL, '["Soleni Biscouto Fressato"]', 'EDUFBA', 'Brasil', 'SciELO Books', 'books', 2011, '2011-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'Este livro aborda os estereótipos agregados à imagem do caipira a partir do ponto de vista apresentado nos filmes de Mazzaropi, levando em consideração que um registro fílmico é uma problematização da realidade, não um recorte fiel da história. O caipira construído por Mazzaropi é bem diferente daquele construído por Monteiro Lobato, que atribuía a personagens caipiras a imagem de ignorantes, preguiçosos e bobos. Mazzaropi, nadando contra a corrente, capturou as contradições existentes nas relações entre a cidade e o campo, mostrando o cotidiano daqueles que iam contra os valores dominantes.', '["popular culture","film representation","Monteiro Lobato","urban-rural relations","Brazilian cinema"]', '10.7476/9788523211653', '9788523207991', 'https://books.scielo.org/id/mktc3', NULL, NULL, 'https://books.scielo.org/id/mktc3/cover/cover_thumbnail.jpeg', 364, 1, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-mktvz', 'mktvz', 'O cromo: estudos de temperamentos', NULL, '["Horácio de Carvalho"]', 'Editora UNESP', 'Brasil', 'SciELO Books', 'books', 2021, '2021-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'Nova edição do romance "O cromo", de Horácio de Carvalho, publicado originalmente em 1888 e considerado uma das narrativas mais características do movimento naturalista na literatura brasileira. A obra conta a história de Ester, jovem culta e bela que sofre de sintomas de uma doença psicológica, e da relação que se desenvolve entre ela e o médico responsável por seu tratamento, dr. Lins Teixeira.', '["naturalism","Brazilian literature","mental illness","hysteria","physician-patient relationship","esters","19th-century novel"]', '10.7476/9786557140710', '9786557140710', 'https://books.scielo.org/id/mktvz', 'https://books.scielo.org/id/mktvz/pdf/carvalho-9786557140710.pdf', NULL, 'https://books.scielo.org/id/mktvz/cover/cover_thumbnail.jpeg', NULL, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-mmfd8', 'mmfd8', 'Mundos possíveis: culturas em pensamento', NULL, '["Ribeiro, Mônica Medeiros","Mencarelli, Fernando"]', 'Editora UFMG', 'Brasil', 'SciELO Books', 'books', 2022, '2022-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Mundos possíveis: culturas em pensamento surge como mais um dos belos produtos do 52° Festival de Inverno da UFMG, realizado em 2020, em formato digital, por causa da pandemia que nos acometeu, interrompendo as atividades presenciais. No entanto, isso não impossibilitou a realização do evento, que conta com uma longeva trajetória de êxito, refletindo sobre os amplos aspectos artísticos, culturais e educacionais que circundam a Universidade e se refletem na cidade, no estado e no país.O livro é constituído como uma rede polifônica de saberes que, a partir de textos produzidos por intelectuais renomados e agrupados de forma instigante, nos apresenta facetas múltiplas de “mundos possíveis” nos quais aspectos culturais se convertem em reflexões potentes e atualizadas sobre temas diversos,trazendo à baila questões artísticas, econômicas, identitárias,literárias, políticas etc.Assim, com base na diversidade de olhares que o termo cultura congrega, esta publicação oferece ao leitor 21 capítulos escritos por convidados que participaram do Festival, oferecendo-nos pensamentos argutos para tratar de assuntos contemporâneos envolvendo o campo das artes e suas reverberações. Esta obra traz aportes reflexivos importantes produzidos por destacados pensadores. Definitivamente, temos aqui um livro fundamental que aponta novas proposições e caminhos.', '["culture","art","cultural identity","artistic thinking","cultural diversity","cultural policy","literature","cultural economics"]', '10.7476/9786588592328', '9786588592113', 'https://books.scielo.org/id/mmfd8', NULL, NULL, 'https://books.scielo.org/id/mmfd8/cover/cover_thumbnail.jpeg', 258, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-mmjw8', 'mmjw8', 'Avanços conceituais em nutrição humana: ciência e tecnologia de alimentos', NULL, '["Valdemiro Carlos Sgarbieri"]', 'Editora da Unicamp', 'Brasil', 'SciELO Books', 'books', 2020, '2020-01-01', 'pt', 'book', 'natural-sciences', 'Ciencias Naturales y Exactas', 'Biochemistry, Genetics and Molecular Biology', 'Este livro tem por objetivo descrever os avanços ocorridos nas áreas de tecnologia de alimentos e de nutrição humana durante o século XX até os dias de hoje. Novos paradigmas e conceitos foram estabelecidos a partir da segunda metade do século passado, particularmente em nutrição humana, com descobertas nos alimentos de compostos bioativos, até então considerados “não nutrientes”. O primeiro capítulo é uma descrição histórica dos principais avanços ocorridos e da importância das descobertas no período supracitado. Nos capítulos seguintes, é descrito e conceituado o que se convencionou chamar de compostos bioativos e nutrição funcional. Os últimos capítulos tratam de inovações em pesquisas, nas quais os conceitos de dieta funcional, nutrigenômica e nutrição personalizada são introduzidos. Esses conceitos poderão conduzir o leitor à seguinte indagação: Dieta ideal é um desafio atingível ou uma utopia? Para os pesquisadores parece ser mais um desafio inatingível, por se tratar de alcançar uma fronteira que se move constantemente pela pressão evolutiva.', '["human nutrition","food technology","bioactive compounds","functional nutrition","functional diet","nutrigenomics","personalized nutrition","history of nutrition science"]', '10.7476/9788526815933', '9786586253214', 'https://books.scielo.org/id/mmjw8', NULL, NULL, 'https://books.scielo.org/id/mmjw8/cover/cover_thumbnail.jpeg', 639, 2, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-mmp9y', 'mmp9y', 'Vida e Obra de Oswaldo Cruz', NULL, '["Clementino Fraga"]', 'Editora FIOCRUZ', 'Brasil', 'SciELO Books', 'books', 2005, '2005-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'Lançado após três décadas de sua primeira e única edição pela Livraria José Olympio Editora, este livro retrata um extraordinário momento da saúde pública brasileira. Trata-se de uma reedição da biografia de Oswaldo Cruz escrita por Clementino Fraga e lançado no ano de 1972. Representa uma bela e delicada homenagem do discípulo a seu mestre, ambos imortalizados na história da saúde pública no Brasil.', '["Oswaldo Cruz","history of public health","Brazilian public health","Fiocruz"]', '10.7476/9786557080993', '9786557080993', 'https://books.scielo.org/id/mmp9y', 'https://books.scielo.org/id/mmp9y/pdf/fraga-9786557080993.pdf', NULL, 'https://books.scielo.org/id/mmp9y/cover/cover_thumbnail.jpeg', NULL, 12, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-mmtct', 'mmtct', 'Os africanos no Brasil', NULL, '["Raymundo Nina Rodrigues"]', 'Centro Edelstein', 'Brasil', 'SciELO Books', 'books', 2010, '2010-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'É a um ensaio de sistematização destes estudos que consagro o presente livro, destinando-o ao conhecimento de uma das preliminares do problema, a história dos Negros colonizadores. [trecho retirado da introdução do livro]', '["African colonization","African diaspora","colonial Brazil","race relations"]', '10.7476/9788579820106', '9788579820106', 'https://books.scielo.org/id/mmtct', 'https://books.scielo.org/id/mmtct/pdf/rodrigues-9788579820106.pdf', NULL, 'https://books.scielo.org/id/mmtct/cover/cover_thumbnail.jpeg', NULL, 179, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-mn', 'mn', 'Histerosalpingografia: introdução ao estudo da radiologia ginecológica', NULL, '["Hugo Maia"]', 'EDUFBA', 'Brasil', 'SciELO Books', 'books', 2009, '2009-01-01', 'pt', 'book', 'medical-health', 'Ciencias Médicas y de la Salud', 'Medicine', 'O livro destina-se aos ginecologistas, ultrassonografistas e, especialmente, aos médicos que pretendem o título de Especialista em Radiologia. Serve como fonte de consulta sobre a histerosalpingografia (HSG) naquilo em que ela é ainda soberana: o diagnóstico ginecológico.', '["hysterosalpingography","gynecologic radiology","gynecologic diagnosis","gynecology"]', '10.7476/9788523209384', '9788523209384', 'https://books.scielo.org/id/mn', 'https://books.scielo.org/id/mn/pdf/maia-9788523209384.pdf', NULL, 'https://books.scielo.org/id/mn/cover/cover_thumbnail.jpeg', NULL, 1, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-mnhy2', 'mnhy2', 'De anjos a mulheres: ideologias e valores na formação de enfermeiras', NULL, '["Elizete Silva Passos"]', 'EDUFBA', 'Brasil', 'SciELO Books', 'books', 2012, '2012-01-01', 'pt', 'book', 'medical-health', 'Ciencias Médicas y de la Salud', 'Nursing', 'A autora identifica os valores que têm definido a enfermagem como uma prática abnegada, de submissão e doação. Para entender este ponto central, ela retoma algumas questões clássicas que perpassam a enfermagem em geral, focando em experiências vividas na Escola de Enfermagem da UFBA (EEUFBA) ao longo de seus 50 anos de existência. Interessada em entender as relações de poder instituídas no campo da enfermagem, Elizete Passos tomou a perspectiva de Gênero para analisar o modo como esta área é vista como um trabalho essencialmente feminino.', '["nursing education","nursing ideology","gender","women in nursing","power relations","nursing values"]', '10.7476/9788523211752', '9788523211752', 'https://books.scielo.org/id/mnhy2', 'https://books.scielo.org/id/mnhy2/pdf/passos-9788523211752.pdf', NULL, 'https://books.scielo.org/id/mnhy2/cover/cover_thumbnail.jpeg', NULL, 13, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-mnx6g', 'mnx6g', 'Amazônia: expansão do capitalismo', NULL, '["Fernando Henrique Cardoso","Geraldo Müller"]', 'Centro Edelstein', 'Brasil', 'SciELO Books', 'books', 2008, '2008-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', '[Neste trabalho] Tenta-se mostrar as formas particulares que o desenvolvimento capitalista assume no devassamento da Amazônia. Analisa-se como o Estado intervém para assegurar as condições para a ocupação e expansão econômica por meio das empresas e como se dá a exploração do trabalho na área [...] [trecho retirado da introdução do livro]', '["Amazon","capitalist development","state intervention","economic expansion","labor exploitation","deforestation","Amazon deforestation"]', '10.7476/9788599662731', '9788599662731', 'https://books.scielo.org/id/mnx6g', 'https://books.scielo.org/id/mnx6g/pdf/cardoso-9788599662731.pdf', NULL, 'https://books.scielo.org/id/mnx6g/cover/cover_thumbnail.jpeg', NULL, 50, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-mny2p', 'mny2p', 'Ciência, universidade e ideologia: a política do conhecimento', NULL, '["Simón Schwartzman"]', 'Centro Edelstein', 'Brasil', 'SciELO Books', 'books', 2008, '2008-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Diversas partes deste livro apareceram anteriormente em artigos de revistas acadêmicas ou jornais em versões distintas. Elas foram escritas visando públicos e momentos distintos, e isso se reflete em certa diferença de estilos. No entanto, havia uma preocupação e uma temática comum a todas elas, que só agora, quando postas lado a lado, podem ser melhor compreendidas.', '["science and ideology","universities","politics of knowledge","knowledge production","higher education"]', '10.7476/9788599662502', '9788599662502', 'https://books.scielo.org/id/mny2p', 'https://books.scielo.org/id/mny2p/pdf/schwartzman-9788599662502.pdf', NULL, 'https://books.scielo.org/id/mny2p/cover/cover_thumbnail.jpeg', NULL, 13, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-mp925', 'mp925', 'Internet na f avela quantos quem onde para quê', NULL, '["Bernardo Sorj","Luís Eduardo Guedes"]', 'Centro Edelstein', 'Brasil', 'SciELO Books', 'books', 2008, '2008-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Economics, Econometrics and Finance', 'Este trabalho procura avançar na elaboração de políticas públicas, a partir de uma análise empírica da dinâmica de inclusão/exclusão digital nos setores mais pobres da população, tendo como base uma ampla pesquisa quantitativa e qualitativa nas comunidades de baixa renda, no município do Rio de Janeiro. [trecho retirado do prefácio do livro]', '["internet access","digital inclusion","digital exclusion","public policy","low-income communities","poverty","Rio de Janeiro","social inequality"]', '10.7476/9788599662465', '9788599662465', 'https://books.scielo.org/id/mp925', 'https://static.scielo.org/scielobooks/mp925/pdf/sorj-9788599662465.pdf', NULL, 'https://books.scielo.org/id/mp925/cover/cover_thumbnail.jpeg', NULL, 3, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-mpgzk', 'mpgzk', 'Produção social das políticas de saúde bucal no Brasil', NULL, '["Thaís Régis Aranha Rossi"]', 'EDUFBA', 'Brasil', 'SciELO Books', 'books', 2018, '2018-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Esta obra tem como objetivo averiguar como questões de saúde bucal se tornaram problemas sociais no Brasil, de1989 a 2004. Além disso, o livro reflete sobre a emergência das soluções aos problemas bucais da população e analisa os processos relacionados com continuidades e/ou rupturas na história das políticas brasileiras de saúde bucal. O presente estudo busca contribuir para a compreensão do complexo processo de formulação dessas políticas no país, com vistas a interpretar melhor cenários futuros', '["oral health policy","health policy history","oral health","health policy formulation","Brazil","public health policy"]', '10.7476/9788523220228', '9788523220228', 'https://books.scielo.org/id/mpgzk', 'https://books.scielo.org/id/mpgzk/pdf/rossi-9788523220228.pdf', NULL, 'https://books.scielo.org/id/mpgzk/cover/cover_thumbnail.jpeg', NULL, 4, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-mqby6', 'mqby6', 'Saúde na Escola: intersetorialidade e promoção da saúde', NULL, '["Carlos dos Santos Silva"]', 'Editora FIOCRUZ', 'Brasil', 'SciELO Books', 'books', 2019, '2019-01-01', 'pt', 'book', 'medical-health', 'Ciencias Médicas y de la Salud', 'Medicine', 'O livro reflete sobre conceitos, modelos, processos e estratégias para enfrentar os desafios da organização dos programas de saúde na escola. Em um momento desafiador e crucial da história da educação no Brasil, a obra do médico pediatra Carlos dos Santos Silva, pesquisador da Fiocruz, analisa propostas inovadoras de reaproximação entre os setores da educação e da saúde. De forma sintética, mas aprofundada e rica em referências, a obra e convida seus leitores a acompanharem o desenvolvimento histórico da saúde escolar no Brasil, os modelos de programa e a trajetória do Programa Saúde na Escola (PSE) no Rio de Janeiro, de 2000 a 2009, período em que o pesquisador esteve à frente do Programa no município. Como parte da coleção Fazer Saúde, o título pretende contribuir para a qualificação de profissionais, pesquisadores e gestores de saúde e de educação, estimulando os conhecimentos científicos e a avaliação crítica das práticas de desenvolvimento de um programa de saúde na escola. Para Paulo Buss, ex-presidente da Fiocruz e professor titular da Escola Nacional de Saúde Pública Sergio Arouca (ENSP), o autor “destaca a importância da ação de saúde abrangente e intersetorial, que mira não apenas o escolar, mas a família e a comunidade em que vive, em toda sua complexidade, e da construção compartilhada pelos profissionais da saúde e da educação dos programas a serem desenvolvidos simultaneamente na escola e na unidade de saúde".', '["school health","intersectoral collaboration","health promotion","Programa Saúde na Escola","school health programs","Rio de Janeiro","family and community health","health and education integration"]', '10.7476/9786557080511', '9788575416266', 'https://books.scielo.org/id/mqby6', NULL, NULL, 'https://books.scielo.org/id/mqby6/cover/cover_thumbnail.jpeg', 170, 5, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-mqfvk', 'mqfvk', 'ArteCiênciaArte', NULL, '["Rosangella Leote"]', 'Editora UNESP', 'Brasil', 'SciELO Books', 'books', 2015, '2015-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'ArteCiênciaArte propõe uma inspiradora reflexão sobre o encontro da arte com a tecnologia e os mais variados campos científícos. A obra possui dois eixos centrais. O primeiro é o uso das neurociências e dos sistemas complexos para o entendimento da percepção que é localizável em espaços artísticos interativos e multimodais; e o segundo refere-se ao lugar do corpo no contexto do desenvolvimento e da fruição de obras com tecnologias emergentes. Os textos apresentam alguns resultados da pesquisa desenvolvida neste campo por Rosangella Leote, isoladamente e em seu grupo de arte contemporânea, o SCIArts, do qual foi uma das fundadoras e participa até hoje. “Leote se distinguiu não apenas como uma artista original e de propostas pouco ortodoxas, mas também como uma analista e teórica muito refinada desse movimento em processo”.', '["art and technology","complex systems","perception","interactive art","multimodal art","body in art","emerging technologies","contemporary art"]', '10.7476/9788568334652', '9788568334652', 'https://books.scielo.org/id/mqfvk', 'https://books.scielo.org/id/mqfvk/pdf/leote-9788568334652.pdf', NULL, 'https://books.scielo.org/id/mqfvk/cover/cover_thumbnail.jpeg', NULL, 6, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-mqk8h', 'mqk8h', 'Mulheres recipientes: recortes poéticos do universo feminino nas artes visuais', NULL, '["Flávia Leme de Almeida"]', 'Editora UNESP', 'Brasil', 'SciELO Books', 'books', 2010, '2010-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Esta dissertação de mestrado é o resultado de uma investigação sobre o universo feminino nas Artes Visuais. As prováveis tecituras resultantes dos entrelaçamentos de tramas e urdiduras artísticas apontaram para as questões estéticas, as elaborações formais e simbólicas do feminino em suas diversas representações. A pesquisa foi dividida em quatro partes que interligaram-se por um fio condutor: o papel e a força da mulher na história da arte. Na primeira parte, o feminino foi mostrado na sua forma mais ancestral de representação através das estatuetas votivas, denominadas Vênus - a figura da mulher apresentou-se nesse período como força fertilizadora. Na segunda parte, abordou-se a manifestação artística das mulheres após a onda revolucionaria sexista - o feminino é então mostrado como força revitalizadora. A terceira parte foi destinada às artistas (es)colhidas do século XX e XXI que trataram do feminino em suas poéticas artísticas - o feminino é tecido como força convergente. Mulheres Recipientes é finalmente alinhavada na quarta e última parte, que contém o arremate dos fios artísticos tradicionais antigos e contemporâneos com as possíveis leituras das obras em cerâmica da autora - o feminino completa-se como força reconciliadora.', '["representation of women in art","feminine figure","women artists","Venus","feminist art","women in art history","ceramic art","artistic poetics"]', '10.7476/9788579831188', '9788579831188', 'https://books.scielo.org/id/mqk8h', 'https://books.scielo.org/id/mqk8h/pdf/almeida-9788579831188.pdf', NULL, 'https://books.scielo.org/id/mqk8h/cover/cover_thumbnail.jpeg', NULL, 1, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-mrb4z', 'mrb4z', 'Oficinas clínicas do cuidado: efeitos da narratividade sobre o trabalho em saúde', NULL, '["Marilene de Castilho Sá","Lílian Miranda","Denise Scofano Diniz","Elaine Sandra Amorim Savi","Eliane dos Santos Teixeira","Maria Liana Gesteira Fonseca"]', 'Editora FIOCRUZ', 'Brasil', 'SciELO Books', 'books', 2019, '2019-01-01', 'pt', 'book', 'medical-health', 'Ciencias Médicas y de la Salud', 'Health Professions', 'Obra escrita por seis autoras, todas ligadas a atividades de ensino e pesquisa na Escola Nacional de Saúde Pública Sergio Arouca (Ensp/Fiocruz), Oficinas Clínicas do Cuidado: efeitos da narratividade sobre o trabalho em saúde apresenta experiências de um curso-oficina no campo da saúde. O livro é voltado especialmente para gestores e profissionais da saúde, incluindo professores e alunos da área. Um dos objetivos do título é, segundo as autoras, discutir o potencial formador de uma experiência de qualificação profissional. No caso, o curso “Oficinas Clínicas sobre o Cuidado”, iniciativa que vem sendo conduzida na Ensp/Fiocruz e que serve de referência para o livro. As pesquisadoras apontam que o outro principal objetivo do relato é “apresentar em detalhes da metodologia de condução das oficinas e apontar as bases para seu desenvolvimento nos serviços de saúde”. O livro é também dedicado a todos os profissionais do Sistema Único de Saúde (SUS) e a todos aqueles que trabalham para a humanização da saúde. Em seis capítulos, a obra apresenta temáticas como os desafios do cuidado e da formação em saúde, as potencialidades das oficinas nos serviços de saúde, além de exposições sobre a organização e o desenvolvimento do curso e a importância das narrativas nos cuidados em saúde.', '["clinical workshops","health care","narrativity","health work","professional training","health humanization","Unified Health System (SUS)","healthcare workers"]', '10.7476/9786557080764', '9788575416396', 'https://books.scielo.org/id/mrb4z', NULL, NULL, 'https://books.scielo.org/id/mrb4z/cover/cover_thumbnail.jpeg', 156, 1, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-mrbvq', 'mrbvq', 'Bárbara Vasconcelos de Carvalho e o ensino da literatura infantil no Brasil', NULL, '["Fernando Rodrígues de Oliveira"]', 'Editora UNESP', 'Brasil', 'SciELO Books', 'books', 2013, '2013-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'Fernando Rodrigues de Oliveira busca neste livro captar e analisar um momento marcante da história da literatura infantil no país, examinando a história tanto da produção literária nesse campo quanto do desenvolvimento de teoria e crítica específicas. O autor faz o foco no estudo o Compêndio de literatura infantil (1959), de Bárbara Vasconcelos de Carvalho (1915-2008), professora e escritora nascida na cidade baiana de Alagoinhas, que produziu uma expressiva obra literária e didática. Ele explica que voltou a atenção para o manual porque, entre outros motivos, ele reúne um conjunto de saberes relativos à literatura infantil considerados necessários para a formação do professor primário no momento histórico em que foi publicado e utilizado. E ainda porque a obra serviu à época não somente como livro didático, mas também como fonte de teorização sobre literatura infantil que se tornou referência para autores de manuais sobre o mesmo assunto. Reconstituindo a história de uma faceta da educação nos anos 1950, o autor aborda diversas questões relacionadas ao ensino da literatura infantil, como manuais e autores, discorre sobre a vida e a obra de Bárbara Vasconcelos de Carvalho, dimensionando sua importância no contexto da pedagogia, e analisa a formação dos professores primários na época da publicação do Compêndio.', '["children''s literature","primary teacher education","history of children''s literature","children''s literature criticism","1950s education","Brazil"]', '10.7476/9786557144824', '9786557144824', 'https://books.scielo.org/id/mrbvq', 'https://books.scielo.org/id/mrbvq/pdf/oliveira-9786557144824.pdf', NULL, 'https://books.scielo.org/id/mrbvq/cover/cover_thumbnail.jpeg', NULL, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-mrhnc', 'mrhnc', 'O Partido Revolucionário Cubano de José Martí: concepção ético-política original', NULL, '["Baró, Dionisio Lázaro Poey","César, Maria Auxiliadora"]', 'Editora Universidade de Brasília', 'Brasil', 'SciELO Books', 'books', 2023, '2023-07-10', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Esta obra é resultado de uma cuidadosa seleção, organização e tradução de documentos, comunicações, artigos de jornais e cartas de José Martí sobre o Partido Revolucionário Cubano (PRC), publicados em diferentes tomos de suas Obras completas. Está ordenada tematicamente, buscando oferecer ao leitor as linhas mais gerais do pensamento e da atividade martianas no Partido fundado por ele para organizar a guerra de independência e criar as condições para uma real descolonização da república a ser criada. Considerou-se importante mostrar a originalidade dessa instituição política, observável em sua estrutura, seus estatutos, seus princípios ideológicos, sua postura ética, nas formas de financiamento e, sobretudo, na ampla e profunda democracia presente nas práticas cotidianas no interior do Partido. Oito capítulos reúnem os textos em grandes áreas para apresentar uma visão geral dos interesses do PRC e da atividade de Martí. Seus títulos são: “Documentos programáticos do PRC”, “Política e ideologia”, “A política e a ética na política”, “Financiamento e arrecadação de fundos”, “Contra o autonomismo e o anexionismo”, “A unidade de diferentes classes e setores sociais”, “Convivência, fraternidade e honradez” e “O PRC na guerra”.', '["José Martí","Cuban independence wars","political ethics","party ideology","party constitution","party funding","party democracy","class unity","fraternities"]', '10.7476/9786558461661', '9786558461661', 'https://books.scielo.org/id/mrhnc', 'https://books.scielo.org/id/mrhnc/pdf/baro-9786558461661.pdf', NULL, 'https://books.scielo.org/id/mrhnc/cover/cover_thumbnail.jpeg', NULL, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-mrvd4', 'mrvd4', 'Persona, educación y filosofía: reflexiones desde la educación universitaria', NULL, '["Víctor Iza Villacís"]', 'Editorial Abya-Yala', 'Ecuador', 'SciELO Books', 'books', 2018, '2018-01-01', 'es', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'Persona, Educación y Filosofía es un trabajo consciente, arduo y muy válido desde la perspectiva amplia de las ciencias. Humanismo, pedagogía y filosofía, se fusionan en una sola propuesta, donde el centro vuelve a los tiempos, a ser el Hombre. Desde la visión experiencial de los trabajos, hasta la cientificidad de los mismos, podemos darnos cuenta que este texto no es solo un trabajo académico, sino también una propuesta experiencial. La misma busca centrar al ser humano en una dimensión trascendental donde el trinomio razón-ciencia-fe se entrelaza efectiva y eficazmente para abordar la pérdida de sentido y de valores. Las visiones pedagógicas presentadas surcan el horizonte de lo novedoso, buscando aterrizar en tierra fértil, donde explayar su visión de mundo, de hombre y de persona. La visión ética, no puede faltar en este entramado, donde hoy pareciera que lo bueno puede ser malo y viceversa, perdiendo la identidad de vida y, por ende, el proyecto.', '["personhood","humanism","philosophy of education","university education","pedagogy","ethics","human identity"]', '10.7476/9789978104934', '9789978104934', 'https://books.scielo.org/id/mrvd4', 'https://books.scielo.org/id/mrvd4/pdf/iza-9789978104934.pdf', NULL, 'https://books.scielo.org/id/mrvd4/cover/cover_thumbnail.jpeg', NULL, 4, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-mrzjs', 'mrzjs', 'Literatura e representações do eu: impressões autobiográficas', NULL, '["Cláudia Maria Ceneviva Nigro","Susanna Busato","Orlando Nunes de Amorim"]', 'Editora UNESP', 'Brasil', 'SciELO Books', 'books', 2010, '2010-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'O tema "autobiografia" surge neste livro abordado com competência metodológica e bibliográfica, sendo uma coletânea de ensaios que estuda as diferentes possibilidades e sentidos do gênero, ou subgênero autobiografia, discutindo as relações da autobiografia com as questões identitártias, assim como analisando a intersecção da autobiografia com o romance, a escritura e a linguagem. A divisão dos capítulos insere o leitor na complexidade do tema, anunciando diferentes formas de enfocar e estabelecer parâmetros de análise.', '["autobiographical writing","self-representation","identity","language and writing","literary genre"]', '10.7476/9788539304417', '9788539300235', 'https://books.scielo.org/id/mrzjs', NULL, NULL, 'https://books.scielo.org/id/mrzjs/cover/cover_thumbnail.jpeg', 146, 4, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-mshpb', 'mshpb', 'Território, ambiente e saúde', NULL, '["Ary Carvalho de Miranda","Christovam Barcellos","Josino Costa Moreira","Maurício Monken"]', 'Editora FIOCRUZ', 'Brasil', 'SciELO Books', 'books', 2008, '2008-01-01', 'pt', 'book', 'natural-sciences', 'Ciencias Naturales y Exactas', 'Environmental Science', 'O livro traz a contribuição original de geógrafos, epidemiologistas, economistas, historiadores e arquitetos sobre as relações entre condições ambientais e situação de saúde. Aqui é ressaltado o papel do território como mediador entre os processos econômicos e sociais e também suas externalidades, materializadas no espaço geográfico na forma de intensas mudanças nas condições ambientais e suas conseqüências sobre o processo de saúde e doença.', '["territory","health and environment","environmental factors","health disparities","spatial externalities","environmental change","health geography","socioeconomic determinants of health"]', '10.7476/9788575413746', '9788575411599', 'https://books.scielo.org/id/mshpb', NULL, NULL, 'https://books.scielo.org/id/mshpb/cover/cover_thumbnail.jpeg', 274, 12, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-msr7j', 'msr7j', 'Filopoética afrodiaspórica: filosofia africana como imaginação emancipatória', 'filosofia africana como imaginação emancipatória', '["Luís Carlos Ferreira dos Santos"]', 'EDUFBA', 'Brasil', 'SciELO Books', 'books', 2025, '2025-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Ao recuperar a teorização estetizante/estetizada de Glissant, articulada às propostas políticas de Mbembe, desde os horizontes da filosofia da ancestralidade, aqui desdobrada em deriva – para problematizar as relações entre estética, ética e política no contexto da violência racista advinda e geradora do poder de matar e da prática de resistência do recusar-se a morrer –, Filopoética afrodiaspórica, oferece potentes reflexões para o cenário latino-americano de produção de categorias e de crítica afrorreferenciadas, no qual o primor analítico, epistemológico e estético traz ferramentas importantes para a reflexão filosófica contemporânea. A articulação da impressionante miríade de pensadoras e pensadores que toma assento na grande conversa proposta pelo livro nos provoca múltiplas e instigantes questões.', '["Édouard Glissant","Aimé Césaire","racism","resistance","decoloniality","Latin American philosophy","African philosophy"]', '10.7476/9786556309101', '9786556307695', 'https://books.scielo.org/id/msr7j', 'https://books.scielo.org/id/msr7j/pdf/santos-9786556309101.pdf', NULL, 'https://books.scielo.org/id/msr7j/cover/cover_thumbnail.jpeg', NULL, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-mth59', 'mth59', 'Metabolismo social da cidade e outros ensaios', NULL, '["Rubén George Oliven"]', 'Centro Edelstein', 'Brasil', 'SciELO Books', 'books', 2009, '2009-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'A cidade funciona como um pólo de irradiação e de atração em relação ao campo e às cidades menores. À primeira vista a força deste pólo é diretamente proporcional a seu tamanho. Entretanto, o poder de irradiação e atração de uma cidade não é fruto exclusivo do número de seus habitantes, mas também da concentração de equipamentos e de atividades e da vida social nela existente. [trecho retirado do primeiro capítulo do livro]', '["social metabolism","urban metabolism","urban attraction","city size","social life in cities","urban-rural relations","small towns"]', '10.7476/9788579820120', '9788579820120', 'https://books.scielo.org/id/mth59', 'https://books.scielo.org/id/mth59/pdf/oliven-9788579820120.pdf', NULL, 'https://books.scielo.org/id/mth59/cover/cover_thumbnail.jpeg', NULL, 7, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-mv4m8', 'mv4m8', 'Índios e caboclos: a história recontada', NULL, '["Maria do Rosário de Carvalho","Ana Magda Carvalho"]', 'EDUFBA', 'Brasil', 'SciELO Books', 'books', 2012, '2012-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'os quais distinguem os bravos, que, procedentes de Minas Gerais, os visitavam de tempos em tempos.Dois deles -Josefa Ferreira e Manuel Santana -afirmaram, sem pejo, a Carvalho, na década de setenta do século XX, que essa "linguagem de índio é recente, que eles sempre souberam que eram tapuias, em seguida caboclos e, só mais recentemente, Pataxó: e aí ficamos Pataxó toda vida".Isso parece querer dizer que o sentido pejorativo frequentemente associado aos termos tapuia e caboclo decorre da identificação e designação por parte de outrem (hetero-identificação).Os Xacriabá do noroeste mineiro eram referidos por várias denominações (cascavéis, gamelas, caboclos, tapuias, entre outros) que, de maneira geral, tinham significado francamente negativo.Por outro lado, a sua autoclassificação como Xacriabá é suposta ter ocorrido em 1970, por ocasião dos primeiros contatos com a Fundação Nacional do Índio (FUNAI) (SANTOS, 1997, p. 85), quando o etnônimo pode ter-se revelado estrategicamente relevante.Em pesquisa realizada entre os Kiriri, na década de 1960, Maria de Lourdes Bandeira registrou a presença de uma nítida "linha discriminatória" entre "a população mestiça cabocla", portadora de fenótipo predominantemente indígena, e "a população mestiça dita civilizada".Tal discriminação lhe pareceu basear-se, simultaneamente, em uma percepção de "diferenças raciais" e no sentimento de uma "superioridade étnica", que se apresentavam sob a forma de crenças no imaginário regional.Alguns provérbios colhidos pela autora, na ocasião, projetam, eloquentemente, sobre os chamados caboclos, representações relacionadas a conformismo e resignação diante da inevitabilidade de um destino adverso -"caboclo tem três futuros: um é perdido, dois são errados", ou, "caboclo não maldiz a sorte, aconteça o que acontecer, não reclama da vida e nem põe a culpa em Deus"-apoiadas em uma imagem de progressiva decadência ("caboclos bêbados e preguiçosos").(BANDEIRA, 1972, p. 39) Os Kiriri desautorizaram essa visualização etnocêntrica ao reconquistarem, com muita tenacidade, ao longo dos anos 1980, as terras que compunham seu território, liberando-as dos não-índios que aí estavam estabelecidos.Aparentemente, Índio e Caboclo constituem categorias com grande poder polissêmico, variável de acordo com o contexto onde emergem.A substância sangue, em muitas situações, opera como demarcadora, distinguindo os índios dos não-índios, dentro de um gradiente expressivo que rompe com a polaridade, como registramos na região do alto curso do Jutaí/AM, nos anos 1980.Os não-índios aí estabelecidos, regionalmente designados como kariw/a, termo que, de fato, abrange todos aqueles que não se identificam e não são identificados como índios, similarmente ao que tem lugar, no Nordeste, para as categorias português e civilizado, com as quais os índios denominam os que não o são, consideram que os primeiros habitantes, ou colonos, [...] Seres menores ou ''espíritos'', os caboclos são considerados como mais maleáveis que os orixás, e, por isso mesmo, seriam melhores protetores para os homens.Esses novos intercessores, emergindo ao lado dos santos católicos e das potentes divindades africanas, não gozam de estatuto tão prestigioso e se introduzem nas zonas sombrias onde os outros não penetram, não entrando, portanto, em concorrência direta com eles.(BOYER, 1999, p. 34-35) Em contrapartida, em certos contextos, como o do jaré, cuja introdução de caboclos teria ocorrido com as levas de escravos oriundas das Minas Gerais, entre os quais se destacou um filho de alforriados chamado Alfredo Araçás, que teria chegado na Chapada Diamantina baiana por volta dos fins dos fins do século passado, "quando os caboclos chegavam, baixavam em antigos terreiros nagôs.[...] gritavam que estavam bem fortalecidos e diziam que nunca foram escravos de nação nenhuma".(SENNA, 1984, p. 76-77) Quem são os caboclos?Indaga Edison Carneiro, para quem o folclorista Théo Brandão, estudando os cabocolinhos desde 1952, pode estabelecer, bibliograficamente (1952), que no continente africano "os negros usavam enfeites de pena e já se acostumavam êles pintar de ocre ou tinta encarnada, como faziam os nossos índios, ou seus imitadores, considerando possível que nos desfiles de personagens à indígena nêles [os negros] fosse despertar o gosto por indumentos e enfeites já usados em terras de África...".(BRANDÃO, 1952 apud CARNEIRO, 1964, p. 144) De acordo com Carneiro (1964, p. 144), o desfile, e não os desfiles, a que se refere Brandão, era o dos [...] meninos índios que, em 1760, acompanhavam, de arco e flecha, os cucumbis, em Santo Amaro, Bahia, por acasião do casamento de Maria A Louca.Os cucumbis eram reperesentações negras, o que quer dizer que os ''meninos índios'' seriam, certamente, negrinhos vestidos à africana.Ao realizar trabalho de campo nas comunidades Tupinambá de Olivença, entre dezembro de 2001 e junho de 2002, Couto diz haver percebido que o termo caboclo era diretamente associado ao "candomblé de caboclo" e às incorporações próprias do candomblé, e que os Tupinambás estabelecidos em Olivença reagiam, terminantemente, à possibilidade de relacionamento com entidades caboclas, consideradas como não sendo "coisa de índio", ao contrário da Serra do Padeiro, onde reina plena aceitação, desde que sob a égide dos encantados.Dito mais claramente, os Tupinambás aí estabelecidos admitem a presença de orixás em seus cultos, desde que sob a condição de estes serem liderados pelos encantados indígenas.Conforme a interpretação local, cada encantado tem um orixá sob o seu domínio espiritual... "porque guerrear e vencer o que o pessoal chama de Exu, é fácil pro encantado!Mas o problema é como fazer ele [Exu] obedecer o encantado.Na religião negra quem domina o Exu é o candomblezeiro; na nossa não, nós nem sabe quem é ele, quem domina ele é o encantado, quem lida com ele é o encantado porque ele é muito mau, eles são coisas muito más!".(COUTO, 2007, p. 140-146) Exu, na Serra do Padeiro, é o escravo do encantado Tupinambá.Couto observou, e registrou, em fevereiro de 2007, uma sessão do ritual Toré, iniciada depois da meia--noite, no decorrer da qual cerca de sessenta índios, com os paramentos devidos, inclusive maracás, propiciavam a descida dos encantados.Desceram vários, entre os quais Tupinambá, com a mais longa performance da noite, Boiadeiro e Sultão das Matas.Tratava-se de um ritual para fortalecimento dos índios com vistas a uma ação -localmente denominada retomada que seria por eles desencadeada na manhã desse mesmo dia.Ao chegarem os Índios ao local previsto para a ação, os encantados já os esperavam.(COUTO, 2007, p. 146-148) Essas ações são, invariavelmente, aconselhadas e dirigidas pelos encantados, que os Tupinambá da Serra do Padeiro enfatizam tratar-se de encantados indígenas (ou caboclos com mironga ou segredo, conforme Carneiro), guerreiros, tais como Tupinambá, Beri, Erú, Sultão das Matas, Lavriano, Lage Grande e Gentio, entre outros, e comedores de carne crua, a exemplo dos três primeiros citados.Não podemos deixar de assinalar a isenção dos Tupinambás da Serra do Padeiro no tratamento de tema tão delicado, sobrepondo-se ao preconceito dos seus parentes de Olivença e, muito seguramente, ao dos regionais à volta.Tal procedimento é, de certo modo, singular no contexto etnográfico do Nordeste, onde o estigma da mistura atua muito pesadamente.O antropólogo americano Hohenthal Junior, em expedição de campo ao vale de São Francisco, nos anos cinquenta, observou que os povos indígenas aí estabelecidos, não obstante a mistura inter-racial contínua e de longa duração, apresentavam uma surpreendente persistência das tradições graças ao "conservatismo e inércia cultural", o que lhe teria permitido reconstruir, em parte, as culturas locais, registrando a presença de seres tutelares, espíritos guardiões, a grande recorrência do culto da jurema e a persistência do xamanismo, apesar das evasivas dos praticantes que temiam ser designados macumbeiros ou feiticeir', '["caboclo","Tapuia","Pataxó","indigenous identity","ethnonyms","self-identification","racial discrimination","ethnic discrimination","regional imaginary","FUNAI","indigenous dance"]', '10.7476/9788523212087', '9788523212087', 'https://books.scielo.org/id/mv4m8', 'https://books.scielo.org/id/mv4m8/pdf/carvalho-9788523212087.pdf', NULL, 'https://books.scielo.org/id/mv4m8/cover/cover_thumbnail.jpeg', NULL, 9, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-mvcpj', 'mvcpj', 'Ciência, nação e região: as doenças tropicais e o saneamento no estado do Amazonas, 1890-1930', NULL, '["Júlio César Schweickardt"]', 'Editora FIOCRUZ', 'Brasil', 'SciELO Books', 'books', 2011, '2011-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'O objetivo da tese é refletir sobre as atividades de saneamento no Estado do Amazonas no período da Primeira República no Brasil. O momento coincide com o auge e o declínio da economia da borracha, fazendo da Região um importante centro de repercussão da cultura e das idéias científicas. Analisamos como as idéias da medicina tropical foram apropriadas por médicos do Amazonas e como foram colocados em prática os princípios daquela disciplina, com o objetivo de realizar a profilaxia da febre amarela e da malária. Essas duas endemias mobilizaram os diversos atores em torno das teorias, que debatiam sobre os mecanismos de transmissão e sobre as formas de combater e controlar os vetores. Diferentes comissões atuaram no Amazonas nesse período, que envolveram: médicos,cientistas e engenheiros de Manaus, da Capital Federal e de Instituições internacionais. A única comissão que realizou o saneamento do interior do Estado foi o Serviço de Saneamento e Profilaxia Rural, que transformou o posto rural em posto itinerante. O saneamento do Amazonas foi proposto e realizado por estas diferentes comissões, que teve como pano de fundo o ambiente e o regime das águas: na capital os igarapés, e no interior a imensa rede de rios e lagos. O Amazonas, nesse período, constituiu-se, portanto, em uma espécie de laboratório para a pesquisa e a experimentação das idéias científicas correntes. A região, em relação à nação, afirmou a sua autonomia e a sua identidade, através da ação dos médicos e cientistas que refletiram sobre a o saneamento do Estado.', '["tropical diseases","sanitation","yellow fever","malaria","First Brazilian Republic","Amazonas","rubber economy","Manaus","scientific expeditions","disease vectors","water regime","regional identity"]', '10.7476/9788575415498', '9788575412251', 'https://books.scielo.org/id/mvcpj', NULL, NULL, 'https://books.scielo.org/id/mvcpj/cover/cover_thumbnail.jpeg', 344, 6, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-mvsg3', 'mvsg3', 'Sexualidade masculina, gênero e saúde', NULL, '["Romeu Gomes"]', 'Editora FIOCRUZ', 'Brasil', 'SciELO Books', 'books', 2008, '2008-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'O livro traz ampla análise de pesquisas nacionais e internacionais recentes sobre homens, masculinidade e saúde e examina matérias publicadas em uma revista masculina contemporânea, em que a ‘saúde do homem’ vira produto a ser consumido, reforçando a imagem de uma masculinidade globalizada, viril, malhada e heterossexual, em contraste às realidades de um grupo de entrevistados no Rio de Janeiro. Por que homens morrem mais cedo? Por que usam menos os serviços de saúde? Por que aparecem mais como ‘infectantes’ ou ‘transmissores de doença’ do que como sujeitos complexos que também precisam de serviços, atenção e reflexão? Sem cair em estereótipos, o autor evidencia relações de poder e gênero, tradicionalmente espaço para falar de desigualdades que atingem as mulheres e atenta para as masculinidades no plural, contextualizadas em uma rede de poderes e no cenário social e histórico.', '["masculinity","men''s health","gender and health","power relations","health disparities","men''s magazines","health care utilization","male mortality","heteronormativity","gender stereotypes","Rio de Janeiro"]', '10.7476/9786557080542', '9788575411483', 'https://books.scielo.org/id/mvsg3', NULL, NULL, 'https://books.scielo.org/id/mvsg3/cover/cover_thumbnail.jpeg', 184, 40, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-mvxd6', 'mvxd6', 'Arquimedes, Pappus, Descartes e Polya: quatro episódios da história da heurística', NULL, '["Inocêncio Fernandes Balieiro Filho"]', 'Editora UNESP', 'Brasil', 'SciELO Books', 'books', 2017, '2017-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'Este livro discute os indícios heurísticos presentes nas obras O método, do pensador grego Arquimedes de Siracusa (287 a.C-212 a.C.); A coleção matemática, do matemático helenístico Pappus de Alexandria (c.290-c.350 d.C.); e Regras para a direção do espírito, do filósofo francês René Descartes (1596-1650). A partir dessa discussão, o Balieiro Filho estabelece relações com a sistematização da atividade heurística apresentada nas obras A arte de resolver problemas e Matemática e raciocínio plausível, do matemático húngaro George Polya (1887-1985). A atividade heurística – definida como esquema psíquico por meio do qual o homem cria, elabora e descobre a resolução de um problema – é o eixo central dos estudos sobre como pensamos, estabelecidos por Polya e que fundamentam a Resolução de Problemas, linha de pesquisa em Educação Matemática. Este livro também traz a primeira tradução em português, feita pelo autor, a partir do original em grego clássico, da obra O método, de Arquimedes, a mais antiga obra de heurística de que se tem conhecimento.', '["heuristics","problem solving","Archimedes","Pappus of Alexandria","collections","René Descartes","Rules for the Direction of the Mind","George Pólya","ancient Greek mathematics","mathematics education"]', '10.7476/9788595461765', '9788595461765', 'https://books.scielo.org/id/mvxd6', 'https://books.scielo.org/id/mvxd6/pdf/balieiro-9788595461765.pdf', NULL, 'https://books.scielo.org/id/mvxd6/cover/cover_thumbnail.jpeg', NULL, 1, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-mw22b', 'mw22b', 'Design e planejamento: aspectos tecnológicos', NULL, '["Marizilda dos Santos Menezes","Luís Carlos Paschoarelli"]', 'Editora UNESP', 'Brasil', 'SciELO Books', 'books', 2009, '2009-01-01', 'es', 'book', 'engineering-tech', 'Ingeniería y Tecnología', 'Engineering', 'O Planejamento de Produto é uma das linhas de pesquisa do Programa de Pós-Graduação em Design (PPGdesign) da Faculdade de Arquitetura, Artes e Comunicação da Unesp.Compreende as diversas formas de conhecimento que possibilitam o desenvolvimento de produtos e objetos visuais ou tácteis.Os projetos envolvidos nessa área de conhecimento percorrem toda a vida do produto, desde os problemas de concepção, passando pelos de projeto e de confi guração, pela produção e gestão, até a distribuição.Investigam-se desde os conceitos ou ideias iniciais até as questões de uso e descarte.Discutem-se a confi guração e a representação do produto de design.O escopo do Planejamento de Produto do design, embora já bastante abrangente, cresce à medida que outras especialidades de projeto são agregadas ao design.A ideia de design enquanto projetos dirigidos quase exclusivamente para a indústria e a consequente produção em série que tem origem na Revolução Industrial têm evoluído e se alterado.Hoje o design adquire novos olhares e novos enfoques a partir de demandas da contemporaneidade, como as do meio ambiente (com o design ecológico ou ecodesign e design de moda), preocupações com o bem-estar da comunidade (com o design social) e com os sentimentos e afetividade (com design emocional e até mesmo o design de serviços).Essas e outras áreas têm em comum a questão do planejamento e do projeto de produtos. MARIZILDA DOS SANTOS MENEZES • LUIS CARLOS PASCHOARELLIOs textos aqui apresentados representam uma parcela da produção científi ca do PPGdesign que demonstra as muitas possibilidades que o Planejamento de Produto engloba.Partindo dos novos conceitos que o design adquire, encontramos o design cultural, muitas vezes chamado de design étnico ou design vernacular.Ele trata da produção cultural humana, independentemente da forma de produção (industrial ou manual) ou estágio de avanço tecnológico em que se encontra o grupo étnico que o produz.Neste livro temos dois trabalhos que discutem objetos ligados ao conhecimento tradicional de povos de origem asiática, africana e europeia.No primeiro caso -Origami: trajetória histórica, técnica e aplicações no design -, temos o resgate do origami, em uma busca das possibilidades de exploração dessa arte milenar japonesa, para utilização na concepção de formas de produtos contemporâneos.No segundo -Design étnico: a identidade sociocultural dos signos -, discute-se a questão da identidade nos projetos de design, fazendo-se um estudo comparativo dos signos de duas culturas tradicionais, akan (africana) e celta (europeia), e análise por meio da Gestalt.O papel relevante que tem o design na gestão empresarial, em especial nas micro e pequenas empresas (MPEs), é demonstrado em dois exemplos.Em Design para micro e pequena empresa: o desenho como abordagem do projeto, mostra-se o signifi cado do desenho como elemento de gestão, ressaltando-se como o desenvolvimento de projetos contribui efetivamente com o crescimento da produtividade da empresa.Outro estudo em MPEs enfoca de modo mais direto a incorporação do design às estratégias de gestão e a importância da inovação e controle de qualidade que essa integração proporciona.Nesse capítulo -Gestão de design nas MPEs do vestuário de moda: o caso da região de Londrina -, corrobora-se a ideia de design como um dos fatores preponderantes de gerenciamento da empresa, tendo como estudo de caso duas empresas do ramo de moda.Prática profi ssional e metodologias projetuais, tônicas nos anos 1980, retornam como objeto de pesquisa em design no século XXI.', '["product planning","design planning","design technology","product life cycle","product configuration","product representation","eco-design","fashion design","social design","emotional design","service design","cultural design"]', '10.7476/9788579830426', '9788579830426', 'https://books.scielo.org/id/mw22b', 'https://books.scielo.org/id/mw22b/pdf/menezes-9788579830426.pdf', NULL, 'https://books.scielo.org/id/mw22b/cover/cover_thumbnail.jpeg', NULL, 7, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-mw58j', 'mw58j', 'Vetores da doença de Chagas no Brasil', NULL, '["Cléber Galvão"]', 'Sociedade Brasileira de Zoologia', 'Brasil', 'SciELO Books', 'books', 2014, '2014-01-01', 'pt', 'book', 'medical-health', 'Ciencias Médicas y de la Salud', 'Medicine', 'Os triatomíneos são insetos hematófagos de grande importância médica, pois são os responsáveis pela transmissão do Trypanosoma cruzi, o agente etiológico da doença de Chagas. Durante mais de um século, desde a descrição da primeira espécie em 1773, os triatomíneos foram estudados de um ponto de vista puramente entomológico. Porém, a partir de 1909, quando Carlos Chagas descobriu que eram os vetores de uma nova tripanossomíase, que mais tarde levaria o seu nome, adquiriram um interesse médico sanitário muito grande despertando a curiosidade de vários pesquisadores que passaram a estudá-los sob os mais variados aspectos. “Vetores da doença de Chagas no Brasil” é uma obra composta por 13 capítulos, com linguagem acessível a públicos com diferentes níveis de formação, voltada principalmente para equipes que atuam em vigilância entomológica, professores e alunos de graduação e pós-graduação. A obra aborda e atualiza diversos aspectos relacionados aos vetores como: taxonomia, biologia, comportamento, mecanismos de transmissão e relação com os mamíferos reservatórios do Trypanosoma cruzi', '["Chagas disease","Chagas disease vectors","Trypanosoma cruzi","disease vectors","vector biology","vector behavior","transmission mechanism","mammalian reservoirs","insect monitoring"]', '10.7476/9788598203096', '9788598203096', 'https://books.scielo.org/id/mw58j', 'https://books.scielo.org/id/mw58j/pdf/galvao-9788598203096.pdf', NULL, 'https://books.scielo.org/id/mw58j/cover/cover_thumbnail.jpeg', NULL, 128, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-mww95', 'mww95', 'Complexidade e ação sistêmica na saúde coletiva', NULL, '["Luiz Carlos de Sá Carvalho","Marília Sá Carvalho"]', 'Editora FIOCRUZ', 'Brasil', 'SciELO Books', 'books', 2025, '2025-04-29', 'pt', 'book', 'medical-health', 'Ciencias Médicas y de la Salud', 'Medicine', 'A obra propõe uma abordagem inovadora para compreender e enfrentar problemas complexos no campo da saúde coletiva. Com base nos conceitos de sistema e complexidade, os autores desenvolvem a Metodologia Sistêmica para a Ação (MSA), uma ferramenta conceitual e prática criada para integrar diferentes campos do saber e sustentar intervenções éticas, contextualizadas e multidimensionais. Com linguagem acessível e exemplos práticos, o livro é voltado a estudantes, profissionais e gestores comprometidos com soluções transformadoras.', '["complexity","systems thinking","public health","complex problems","multidimensional intervention","ethical intervention","systems approach"]', '10.7476/9786557082317', '9786557081976', 'https://books.scielo.org/id/mww95', NULL, NULL, 'https://books.scielo.org/id/mww95/cover/cover_thumbnail.jpeg', 317, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-mxmk7', 'mxmk7', 'A educação musical em cursos de pedagogia do estado de São Paulo', NULL, '["Wasti Silvério Ciszevski Henriques"]', 'Editora UNESP', 'Brasil', 'SciELO Books', 'books', 2013, '2013-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'Poucos cursos paulistas oferecem a disciplina Música em sua grade curricular, embora os documentos nacionais para o curso de Pedagogia apontem pra a inserção de disciplinas artísticas em seu currículo, pois seu “núcleo de estudos básicos” considera “Artes” como um de seus componentes. Esta obra pretende apresentar aspectos referentes à situação do ensino musical em cursos de Pedagogia paulistas, de modo a contribuir com dados específicos às grandes questões ligadas à implantação da Música na educação básica, temática bastante relevante no momento em que o Brasil se encontra, destacando-se, em especial, a questão do conhecimento em música e o papel da música no currículo da escola regular e nos cursos de formação acadêmico-profissional de professores.', '["music education","pedagogy course","music curriculum","teacher professional development","basic education","musical knowledge","São Paulo state"]', '10.7476/9786557144770', '9786557144770', 'https://books.scielo.org/id/mxmk7', 'https://books.scielo.org/id/mxmk7/pdf/henriques-9786557144770.pdf', NULL, 'https://books.scielo.org/id/mxmk7/cover/cover_thumbnail.jpeg', NULL, 1, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-mxmtw', 'mxmtw', 'História da arte: ensaios contemporâneos', NULL, '["Marcelo Campos","Maria Cristina Louro Berbara","Roberto Conduru","Vera Beatriz Siqueira"]', 'LA Referencia (Red Federada de Repositorios Institucionales de Publicaciones Científicas)', 'Brasil', 'SciELO Books', 'books', 2011, '2011-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'Este livro propõe, seja do ponto de vista de sua rede geral, seja do corpo de cada capítulo, uma história da arte vinculada à produção de reflexões que, não determinadas nem pela cronologia nem pela geografia, permite gerar investigações histórico-artísticas consistentes a partir do cruzamento de expressões visuais e culturais produzidas em diferentes contextos espaciotem', '["art history","contemporary art","visual culture","artistic production","art historiography"]', '10.7476/9786588808115', '9788575111888', 'https://books.scielo.org/id/mxmtw', NULL, NULL, 'https://books.scielo.org/id/mxmtw/cover/cover_thumbnail.jpeg', 2011, 1, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-mxrdc', 'mxrdc', 'A cidade como história: os arquitetos e a historiografia da cidade e do urbanismo', NULL, '["Eloísa Petti Pinheiro","Marco Aurélio A. de Filgueiras Gomes"]', 'EDUFBA', 'Brasil', 'SciELO Books', 'books', 2005, '2005-01-01', 'pt', 'book', 'engineering-tech', 'Ingeniería y Tecnología', 'Engineering', 'Neste livro, encontram-se reunidas colaborações relacionadas à sétima edição do Seminário de História da Cidade e do Urbanismo, ocorrido em 2002, em Salvador, por iniciativa do Programa de Pós-Graduação em Arquitetura e Urbanismo da Universidade Federal da Bahia (UFBA). Busca contribuir para o adensamento da pesquisa neste campo, repensando a cidade a partir da história e da cultura e oferecendo uma ria e da cultura, oferecendo uma reflexesquisa nesse campo, repensando a cidade a partir da histreflexão sobre suas convergências e divergências, impasses e desafios, e possibilidades de interlocução dentro de um panorama aberto à perspectiva comparada internacional.', '["urban history","architects","urbanism","city and culture","comparative urban history"]', '10.7476/9788523211677', '9788523203498', 'https://books.scielo.org/id/mxrdc', NULL, NULL, 'https://books.scielo.org/id/mxrdc/cover/cover_thumbnail.jpeg', 228, 2, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-myv39', 'myv39', 'Visões imaginárias da cidade da Bahia: um diálogo entre a geografia e a literatura', NULL, '["Délio José Ferraz Pinheiro","Maria Auxiliadora da Silva"]', 'EDUFBA', 'Brasil', 'SciELO Books', 'books', 2004, '2004-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Visões imaginárias da cidade da Bahia é um trabalho surpreendente. Ele rompe com a aridez de uma geografia clérica, seguindo a orientação de Milton Santos, para o qual “o maior erro que a geografia cometeu foi o de querer ser ciência, em vez de ciência e arte”. A proposta dos autores é a de retornar ao pensamento sartreano, tão caro a Milton. Pensamento que expressa em Esboço de uma teoria das emoções, no qual “... uma emoção remete ao que ela significa. E, o que ela significa é a totalidade das relações da realidade-humana com o mundo”, através da “...queda brusca da consciência no mágico". (Retirado da apresentação do livro)', '["imaginary city","Bahia","geography and literature","Jean-Paul Sartre","emotion theory","Milton Santos","magical realism","urban representation"]', '10.7476/9788523209223', '9788523209223', 'https://books.scielo.org/id/myv39', 'https://books.scielo.org/id/myv39/pdf/pinheiro-9788523209223.pdf', NULL, 'https://books.scielo.org/id/myv39/cover/cover_thumbnail.jpeg', NULL, 5, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-mzqvc', 'mzqvc', 'Heidegger e o sentido como lugar', 'a transformação topológica de sua filosofia', '["Laurenio Leite Sombra"]', 'UEFS Editora', 'Brasil', 'SciELO Books', 'books', 2024, '2024-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'O lugar pressupõe a articulação de um conjunto de elementos concomitantes de forma complexa, mas não é interdependência, que permita pensá-los numa unidade que se identifica. Para que um lugar seja pensado como tal, há necessidade de uma concepção dinâmica da unidade do todo, assim como das partes, conexão constantemente trabalhada articulada na interação dos elementos, mas também é constantemente indeterminada, frágil. O lugar e seus elementos articulam-se de tal modo que impedem que se estabeleça uma relação hierárquica que afirmaria categoricamente que coisas determinam lugares o que lugares determinam coisas. É fundamental ao contrário, uma rede de remissões que, em sua conexão complexa, aponte para um "sentido", um espaço de coerência que possa ser pensado como um lugar com a região que a barca lugares', '["Martin Heidegger","place","senses","indeterminacy","coherence"]', '10.7476/9788555921636', '9786589524656', 'https://books.scielo.org/id/mzqvc', NULL, NULL, 'https://books.scielo.org/id/mzqvc/cover/cover_thumbnail.jpeg', 197, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-n22qp', 'n22qp', 'Origens da dialética do trabalho: estudo sobre a lógica do jovem Marx', NULL, '["José Arthur Giannotti"]', 'Centro Edelstein', 'Brasil', 'SciELO Books', 'books', 2010, '2010-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'De novo venho salientar o caráter lógico deste texto, meu interesse fundamental em compreender a viabilidade da dialética. Se passo por uma leitura do jovem Marx, é para investigar a validade duma dialética que toma como ponto de partida a categoria do homem como ser genérico na qualidade de universal concreto.', '["dialectics","dialectical method"]', '10.7476/9788579820441', '9788579820441', 'https://books.scielo.org/id/n22qp', 'https://books.scielo.org/id/n22qp/pdf/giannotti-9788579820441.pdf', NULL, 'https://books.scielo.org/id/n22qp/cover/cover_thumbnail.jpeg', NULL, 5, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-n2gtg', 'n2gtg', 'Memória: interfaces no campo da informação', NULL, '["Eliane Braga de Oliveira","Georgete Medleg Rodrigues"]', 'Editora Universidade de Brasília', 'Brasil', 'SciELO Books', 'books', 2017, '2017-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Na contemporaneidade, discute-se cada vez mais o papel e o lugar da memória, considerando-se, sobretudo, o privilégio da rapidez, da eficácia e da eficiência da informação, ao mesmo tempo em que se constata a célere obsolescência dos meios tecnológicos para a sua disseminação. Nesse contexto, surgem também reflexões sobre o papel das instituições ou, mais popularmente, dos “lugares de memória”. Assim, arquivos, museus, centros de documentação, bibliotecas e espaços virtuais atuam na constituição, sedimentação e disseminação dessa memória. Outra vertente dessas reflexões reside na discussão sobre a possibilidade de autonomia dos indivíduos e grupos sociais organizados na construção e elaboração de suas memórias. No entanto, numa sociedade pautada pelo efêmero e pela fluidez – a modernidade “líquida” segundo Zygmunt Bauman –, as experiências passadas tendem a se tornar pouco relevantes, e a função social da memória parece ser útil apenas para o atendimento de necessidades imediatas. Isso pode nos levar a uma situação ambígua, na qual caberia à Ciência da Informação atender às demandas de uma sociedade que valoriza o efêmero e a velocidade, em detrimento da permanência e da construção de uma memória social. Com o objetivo de contribuir para esse debate, esta coletânea reúne textos de pesquisadores de universidades do Brasil, da Espanha e de Portugal que têm refletido sobre o tema da memória, na perspectiva da Ciência da Informação e nos diálogos com outras disciplinas.', '["memory","social memory","places of memory","archives","museums","libraries","virtual space","liquid modernity","Zygmunt Bauman","information science","collective memory"]', '10.7476/9788523013479', '9788523011949', 'https://books.scielo.org/id/n2gtg', NULL, NULL, 'https://books.scielo.org/id/n2gtg/cover/cover_thumbnail.jpeg', 360, 2, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-n2qff', 'n2qff', 'Ganhar a saída', NULL, '["Antonie Compagnon"]', 'Editora UFMG', 'Brasil', 'SciELO Books', 'books', 2023, '2023-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', '“Ganhar a saída” registra a conferência que encerra a trajetória de 45 anos de ensino de Antoine Compagnon na França, e a última do curso intitulado “Fins da literatura”, no Collège de France. “Não sabia, portanto, como intitular esta última aula, oscilando entre as duas vias que me esforcei por seguir ao longo deste último ciclo de cursos e ainda durante a penúltima hora: uma tentação melancólica, a dos artistas que reivindicam uma ‘segunda chance’ para, enfim, realizar sua obra-prima e uma esperança redentora naqueles que aceitam ser nada além do que o avatar de uma linhagem. Polaridade que não concerne somente aos criadores, mas talvez também aos professores”, revela o autor. Na avaliação da tradutora, “Ganhar a saída” preserva o estilo ao mesmo tempo coloquial e erudito do autor, mas traz a particularidade de uma certa nostalgia que perpassa por suas reflexões, em meio a fragmentos de memórias da carreira de professor.', '["Antoine Compagnon","Collège de France","literary theory","literature teaching","melancholy","redemption","artistic heritage","literary lineage","nostalgia"]', '10.7476/9786558581574', '9786558581284', 'https://books.scielo.org/id/n2qff', NULL, NULL, 'https://books.scielo.org/id/n2qff/cover/cover_thumbnail.jpeg', 72, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-n2s6z', 'n2s6z', 'Una obra para la historia: homenaje a Germán Colmenares', NULL, '["Diana Inés Bonnett Vélez"]', 'Editorial Universidad del Rosario', 'Colombia', 'SciELO Books', 'books', 2015, '2015-01-01', 'es', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'Con esta obra se pretende establecer una línea de cercanía con el tipo de historia profesada por Germán Colmenares en los terrenos de lo social y lo económico, la teoría de la historia y también la historia del derecho. El texto que hoy entregamos se abre a algunos de los temas referidos en su obra completa, como sus preocupaciones por lo que llamamos etnohistoria, la historia regional, la relación hacienda-minería, los procesos sociales y la esclavitud, todo ello estudiado en los ámbitos rurales y urbanos en los que Colmenares incursionó. Este no es, pues, en estricto sentido, un texto sobre la obra o la persona de Germán Colmenares, sino una expresión de lo que los historiadores hemos aprendido —o discutido, o confrontado, o decimos saber— de sus propuestas teóricas, ideas, técnicas, metodologías y conocimientos en Historia.', '["historiography","social history","economic history","legal history","ethnohistory","regional history","social processes","slavery","rural history","urban history"]', '10.7476/9789587386776', '9789587386769', 'https://books.scielo.org/id/n2s6z', NULL, NULL, 'https://books.scielo.org/id/n2s6z/cover/cover_thumbnail.jpeg', 182, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-n2t8g', 'n2t8g', 'Estudos de casos para a formação de professores de Química: desafios contemporâneos da sala de aula', 'desafios contemporâneos da sala de aula', '["Bego, Amadeu Moura","Merseth, Katherine"]', 'Editora UNESP', 'Brasil', 'SciELO Books', 'books', 2024, '2024-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Os estudos de casos, escritos ou, modernamente, em vídeo, são utilizados para a formação profissional, como medicina, direito, negócios e outras atividades. Na formação de professores, um caso é usado em sala de aula para aprimorar o estudo do ensino de alguma disciplina e/ou de determinada prática de ensino relacionado a tópicos conhecidos por serem difíceis de lidar por envolverem dilemas. A docência em ciências demanda de professores a capacidade de lidar com a multiplicidade de fatores presentes no contexto escolar. Desde questões comportamentais até a consideração das identidades de gênero de alunos, a singularidade e a complexidade da realidade em sala de aula exigem novas abordagens formativas. Neste livro, encontram-se onze casos relacionados ao ensino de Química, produzidos por pós-graduandos e professores brasileiros, sob orientação e revisão de docentes da Harvard e da Unesp. Esperamos que esses casos – com dilemas, histórias e lições – sirvam como material de apoio para melhorar a formação de professores de Ciências e, mais especificamente, os professores de Química.', '["case studies","chemistry teacher education","science teacher education","teacher dilemmas","classroom problems","student behavior","teaching practice","teacher professional development"]', '10.7476/9786557145494', '9786557145494', 'https://books.scielo.org/id/n2t8g', 'https://books.scielo.org/id/n2t8g/pdf/bego-9786557145494.pdf', NULL, 'https://books.scielo.org/id/n2t8g/cover/cover_thumbnail.jpeg', NULL, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-n3253', 'n3253', 'Tradução em (ent)revista: Simone Schwarz-Bart e as tradutoras brasileiras', NULL, '["Vanessa Massoni da Rocha"]', 'EDUERJ', 'Brasil', 'SciELO Books', 'books', 2021, '2021-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'Propõe uma reflexão ampla sobre o exercício e os mistérios inerentes ao ofício do tradutor. O livro reúne entrevistas com Estela dos Santos Abreu e Eurídice Figueiredo, responsáveis por verter ao português, respectivamente, os livros A ilha da chuva e do vento (em 1986) e Joãozinho no Além (em 1988). Apresenta também uma entrevista com a escritora guadalupense Simone Schwarz-Bart, autora das referidas obras, cuja escrita engajada é fortemente ancorada nos costumes caribenhos. Os capítulos revelam rituais, práticas, prazos, dificuldades e repercussões dos trabalhos das tradutoras entrevistadas, descortinando aspectos vitais para que se alcance qualidade e o papel estratégico que a tradução desempenha no processo de receptividade de uma obra pelo público. Tradução em (ent)revista também é um testemunho dos processos que envolvem a tradução de obras caribenhas no Brasil, estimulando debates e estudos sobre a área.', '["Simone Schwarz-Bart","literary translation","Portuguese translation","Caribbean literature","translation process","translation quality","reader reception","Guadeloupean literature"]', '10.7476/9786599111150', '9786599111150', 'https://books.scielo.org/id/n3253', 'https://books.scielo.org/id/n3253/pdf/rocha-9786599111150.pdf', NULL, 'https://books.scielo.org/id/n3253/cover/cover_thumbnail.jpeg', NULL, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-n3wpq', 'n3wpq', 'Política urbana no contexto federativo brasileiro: aspectos institucionais e financeiros', NULL, '["Angela Moulin S. Penalva Santos"]', 'LA Referencia (Red Federada de Repositorios Institucionales de Publicaciones Científicas)', 'Brasil', 'SciELO Books', 'books', 2017, '2017-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', '"Analisa os desafios impostos para a implementação de políticas urbanas nas cidades brasileiras. Destaca, principalmente, os efeitos da Constituição de 1988, que atribuiu aos municípios a responsabilidade de gerir a política urbana, ainda que os governos estaduais e federal também possuam responsabilidade em relação ao ordenamento territorial. O livro também aborda aspectos como o uso da tributação imobiliária com finalidade de instrumento de política urbana e os efeitos da descentralização das políticas públicas sobre a autonomia financeira dos municípios. Trata-se de obra multidisciplinar, perpassando as áreas de economia, urbanismo, geografia, história e ciências políticas. A discrepância entre a cidade almejada pelos legisladores e o espaço urbano real, com graves problemas de habitação, saneamento e segurança, revela a urgência de uma reflexão sobre o tema."', '["urban policy","Brazilian federalism","local self-government","fiscal decentralization","real estate taxation","land use planning","Brazilian Constitution of 1988","intergovernmental relations","housing","sanitation","urban security","Brazilian cities"]', '10.7476/9788575114513', '9788575114490', 'https://books.scielo.org/id/n3wpq', NULL, NULL, 'https://books.scielo.org/id/n3wpq/cover/cover_thumbnail.jpeg', 288, 5, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-n4kw6', 'n4kw6', 'Cidades saudáveis? Alguns olhares sobre o tema', NULL, '["Carmen Beatriz Silveira","Tania Maria Fernandes","Bárbara Pregrini"]', 'Editora FIOCRUZ', 'Brasil', 'SciELO Books', 'books', 2014, '2014-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'A grande maioria da população vive hoje nas cidades. Mas elas variam bastante entre si e há diferenças marcantes mesmo dentro de uma mesma cidade, o que tem impacto sobre as características da vida urbana e as condições de saúde da população. Compreender essa complexidade é essencial para a tomada de decisões sobre intervenções públicas nas cidades. Estudos e ensaios sobre o assunto estão reunidos neste livro, que não só traz reflexões teóricas, mas as coloca em diálogo com diferentes iniciativas para a melhoria da saúde das cidades. Municípios ou comunidades saudáveis dependem de uma prática contínua de aprimoramento do ambiente físico e social, por meio de estratégias que priorizem a saúde dos cidadãos dentro de uma lógica ampliada de qualidade de vida, com ações intersetoriais e garantia de participação social. Uma cidade saudável, destaca-se, é também uma cidade com justiça social, pois as iniquidades se destacam entre as causas de deterioração da saúde.', '["healthy cities","urban health","social determinants of health","social justice","intersectoral action","social participation","quality of life","public health interventions","urban inequality","healthy communities"]', '10.7476/9788575415290', '9788575414521', 'https://books.scielo.org/id/n4kw6', 'https://books.scielo.org/id/n4kw6/pdf/silveira-9788575415290.pdf', 'https://books.scielo.org/id/n4kw6/epub/silveira-9788575415290.epub', 'https://books.scielo.org/id/n4kw6/cover/cover_thumbnail.jpeg', 332, 9, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-n4pzq', 'n4pzq', 'Barganhas e querelas da escravidão: tráfico, alforria e liberdade (séculos XVIII e XIX)', NULL, '["Gabriela dos Reis Sampaio","Lisa Earl Castillo","Wlamyra Ribeiro de Albuquerque"]', 'EDUFBA', 'Brasil', 'SciELO Books', 'books', 2014, '2014-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'Barganhas e querelas da escravidão é composto por capítulos escritos por membros do Grupo de Pesquisa Escravidão e Invenção da Liberdade e resultam de investigações sobre tráfico de escravos, alforria e liberdade. A obra reúne textos que evidenciam tradições, tendências e caminhos da historiografia contemporânea sobre escravidão e liberdade.', '["slave trade","manumission","slavery","freedom","historiography of slavery","18th century","19th century"]', '10.7476/9788523217259', '9788523211011', 'https://books.scielo.org/id/n4pzq', NULL, NULL, 'https://books.scielo.org/id/n4pzq/cover/cover_thumbnail.jpeg', 358, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-n5g9r', 'n5g9r', 'Carta de achamento do Brasil', NULL, '["Pêro Vaz de Caminha"]', 'Editora da Unicamp', 'Brasil', 'SciELO Books', 'books', 2021, '2021-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'Escrita em maio de 1500 em Porto Seguro, Bahia, a carta do escrivão Pero Vaz de Caminha ao rei D. Manuel assemelha-se a um relato de viagem. Mais do que descrever a terra e a natureza, brevemente vistas durante os nove dias em que a frota de Pedro Álvares Cabral esteve no que viria a ser o Brasil, a narrativa é centrada nos povos indígenas, e as palavras de Caminha, hábil escritor, pintam imagens vívidas do que observou, pretendendo informar e maravilhar o seu interlocutor. A “Carta” nos surpreende com questões que até hoje, mais de 500 anos depois, permanecem agudamente presentes, tais como a ameaça da mineração aos povos indígenas, o direito à propriedade da terra e o apagamento de vozes não europeias. Nesta edição modernizada, uma introdução contextualiza a carta em seu tempo, destaca sua singularidade e aponta as apropriações culturais e políticas que dela se fizeram. As notas explicam o texto passo a passo, abrindo caminhos para uma interpretação atualizada e crítica.', '["Pero Vaz de Caminha","Pedro Álvares Cabral","Portuguese exploration of Brazil","indigenous peoples","indigenous land rights","colonial Brazil","Portuguese monarchy","travel writing","16th century"]', '10.7476/9788526815469', '9786586253825', 'https://books.scielo.org/id/n5g9r', NULL, NULL, 'https://books.scielo.org/id/n5g9r/cover/cover_thumbnail.jpeg', 133, 9, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-n656x', 'n656x', 'Observatório da vida estudantil: primeiros estudos', NULL, '["Sônia Maria Rocha Sampaio"]', 'EDUFBA', 'Brasil', 'SciELO Books', 'books', 2011, '2011-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Esta obra contempla os objetivos, metodologia de trabalho e perspectivas atuais do ''Observatório da Vida Estudantil'', que atua em duas Instituições Federais de Ensino Superior da Bahia - a UFBA e a UFRB. A obra, formada por 12 artigos, trata de temas como o novo universitário que vem se inserindo na UFBA, o aluno de origem popular e a opinião dos estudantes com relação ao Bacharelado Institucional. A relação da juventude com a política, a maternidade durante o período universitário, e a questão da evasão na educação superior são alguns dos assuntos também abordados.', '["student life","university students","Universidade Federal da Bahia","youth and politics","higher education dropout"]', '10.7476/9788523212117', '9788523212117', 'https://books.scielo.org/id/n656x', 'https://books.scielo.org/id/n656x/pdf/sampaio-9788523212117.pdf', NULL, 'https://books.scielo.org/id/n656x/cover/cover_thumbnail.jpeg', NULL, 15, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-n66cm', 'n66cm', 'Fantasia e outros textos', NULL, '["Cândida Fortes Brandão"]', 'Editora UNESP', 'Brasil', 'SciELO Books', 'books', 2024, '2024-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'Misto de professora, escritora e jornalista, Cândida Fortes Brandão nasceu e viveu em Cachoeira do Sul (RS), onde dedicou a vida a seus ideais: a poesia, o jornalismo e o magistério. Apesar de ter sido reconhecida por Júlia Lopes de Almeida como "mãe intelectual dos cachoeirenses", ter sido aclamada por Olavo Bilac e integrar a Academia Literária Feminina do Rio Grande do Sul, seu nome ficou esquecido. Este livro faz o necessário e merecido resgate desta figura central nas letras brasileiras, por meio de alguns de seus textos mais memoráveis.', '["women writers","Brazilian literature","women journalists","women poets","literary criticism","Cachoeira do Sul","literary legacy"]', '10.7476/9786557145487', '9786557145487', 'https://books.scielo.org/id/n66cm', 'https://books.scielo.org/id/n66cm/pdf/brandao-9786557145487.pdf', NULL, 'https://books.scielo.org/id/n66cm/cover/cover_thumbnail.jpeg', NULL, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-n7ckq', 'n7ckq', 'Marxismo(s) &amp; educação', NULL, '["Anita Helena Schlesener","Gisele Masson","Maria José Dozza Subtil"]', 'Editora UEPG', 'Brasil', 'SciELO Books', 'books', 2016, '2016-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Este livro reúne reflexões de diferentes autores do campo educacional que se valem das contribuições de Karl Marx e da tradição marxista para problematizar a educação e o seu importante papel de mediação na formação de homens e mulheres capazes de compreender os antagonismos sociais imanentes à sociedade capitalista e de forjar possibilidades de sua superação.', '["Marxism","Marxist theory of education","Karl Marx","capitalist society","social antagonism","critique of capitalism"]', '10.7476/9788577982110', '9788577982110', 'https://books.scielo.org/id/n7ckq', 'https://books.scielo.org/id/n7ckq/pdf/schlesener-9788577982110.pdf', NULL, 'https://books.scielo.org/id/n7ckq/cover/cover_thumbnail.jpeg', NULL, 2, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-n7g56', 'n7g56', 'Questões sociocientíficas: fundamentos, propostas de ensino e perspectivas para ações sociopolíticas', NULL, '["Dália Melissa Conrado","Nei Nunes-Neto"]', 'EDUFBA', 'Brasil', 'SciELO Books', 'books', 2018, '2018-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'SOBRE OS AUTORES11 PREFÁCIO O campo da educação em ciências e tecnologias é um dos mais importantes para a construção de uma sociedade mais justa, equânime e democrática.A articulação deste campo e o dos estudos sociais da ciência e da tecnologia (Estudos CTS) tem produzido algo novo, muito significativo em termos educacionais, na medida em que os conhecimentos a ensinar passam a incorporar aspectos das realidades sociais e culturais locais, regionais e globais.Como resultado, conhecimentos locais, ancestrais e consuetudinários passam a ser reconhecidos como válidos, o que reduz a verticalidade nas relações de saber/poder, a percepção de neutralidade da ciência e de autonomia da tecnologia.As possibilidades oferecidas pelas controvérsias presentes nas Questões Sociocientíficas e Sociotecnológicas, frutos de pesquisas desses campos e suas articulações, anteriormente silenciadas ou tratadas como não pertinentes ao ensino tradicional de ciências e tecnologias, provocam mudanças muito significativas na forma e no conteúdo educacionais.Uma educação científica e tecnológica com essa perspectiva é emancipadora e muito mais próxima de uma formação para o pleno exercício da cidadania em um universo que se deseja democrático.Trata-se de superar definitivamente um ensino de ciências e tecnologias descontextualizado e aquilo que Paulo Freire identificou como educação bancária.Como bem aponta o livro, todas as socioculturas estão, de alguma maneira, envolvidas com aspectos e produtos da atividade científico-tecnológica.Entretanto, em muitos casos, esses envolvimentos não são percebidos criticamente pelos diferentes grupos sociais.Em muitas situações, os seus efeitos são sentidos, mas não associados aos produtos daquela atividade.Aqui há algo que aponta para a extrema necessidade da presença das Questões Sociocientíficas e Sociotecnológicas na educação científica e tecnológica.A formação tradicional de cientistas e tecnólogos, favorecida pela abordagem fragmentada do conhecimento e pela afirmação da neutralidade que constrói a não existên-12 | Irlan von Linsingen cia da sua natureza social e cultural, produz efeitos de sentido que tendem a amortecer a responsabilidade social e ambiental sobre as consequências nocivas que suas atividades profissionais podem ajudar a produzir.Por outro lado, a percepção hegemônica de que há conhecimentos superiores e inferiores acaba por induzir os fazedores de políticas públicas a tratar de forma verticalizada os problemas e as soluções.Por conta disso, as soluções a problemas identificados como de natureza científica e tecnológica são construídas em uma instância alheia à dos chamados usuários/beneficiários daquelas soluções, sem que estes tenham participado da construção do problema e, assim, podem não reconhecer nem o problema, nem a solução.Em tais contextos, a perspectiva educacional, tanto formal quanto não-formal, apresentada nesse livro, torna-se uma via substantiva também para a formação de cientistas e tecnólogos e para uma crescente participação dos grupos sociais na construção coletiva de problemas e de soluções.A potencialidade transformadora dessa coletânea está relacionada à sua perspectiva educacional crítica, solidamente construída nos diversos textos, através da explicitação de aspectos normalmente silenciados ou deliberadamente ocultados sobre a Natureza da Ciência e da tecnologia e dos produtos a elas associados.Os textos estão organizados em três partes.A primeira é dedicada aos fundamentos teóricos da Educação Ciência-Tecnologia-Sociedade-Ambiente (Educação CTSA), das Questões Sociocientíficas, do pensamento crítico e da formação de pessoas para ações sociopolíticas.A segunda apresenta 14 propostas de ensino baseadas em Questões Sociocientíficas (e Questões Sociotecnológicas), explorando temas diversos e atuais de expressiva repercussão que põem em questão a sustentabilidade em sentido amplo, como aqueles provocados pelo uso de agrotóxicos, poluição hídrica, medicalização da vida, transgênicos, as questões de produção e uso de energia (hidráulica, eólica, nuclear), a exploração de minérios e a manipulação climática.De todos os significativos temas abordados no livro, cito aqui como exemplo a impactante e dramática questão da exploração do mineral Coltan, de onde são extraídos o Tântalo e o Nióbio, essenciais, entre outras, para as áreas de informática, telefonia celular, aeronáutica e bélica.O assunto envolve acontecimentos que conectam essas substâncias aos interesses sociopolíticos e econômicos de grupos e países como os Estados Unidos da América do Norte, a Alemanha, a Bélgica, os Países Baixos e o Cazaquistão, e aos conflitos étnicos e bélicos na República Democrática do Congo e seus vizinhos, Ruanda e Uganda.Assim como as outras abordadas no livro, essa Questão Sociocientífica e Sociotecnológica evidencia o comprometimento e a inseparabilidade entre Ciência-Tecnologia-Sociedade-Ambiente e também aspectos da colonialidade do saber/poder entre países do norte e do sul global.Todos esses ingredientes fazem parte da configuração dos artefatos tecnológicos e a educação CTS deve ter isso em conta.As propostas, com esses vieses na Educação CTS desenvolvidos no livro, podem ser potenciais indutores do desenvolvimento de outras propostas baseadas em temas si-Prefácio | 13 tuados ou problemas locais, como o do acidente radiológico com o Césio-137 em Goiânia (1987), a exploração do Nióbio no Brasil (país que detém uma das maiores reservas mundiais do mineral), e tantos outros que ainda se situam na zona do "não problema" -ou seja, um problema que não é sequer percebido pelos sujeitos de uma determinada comunidade, país ou mesmo de um continente.A terceira e última parte é dedicada à abordagem de perspectivas e experiências para a construção de possibilidades educativas, a partir da articulação de Questões Sociocientíficas e Sociotecnológicas nos diversos níveis da educação em ciências e tecnologias na construção de propostas de ensino, envolvendo resultados de pesquisas realizadas no Brasil, em Portugal, na Colômbia e no Canadá.Há muitos anos, temos nos empenhado em mostrar a inadequação de uma educação que não considera a pluralidade de saberes, que trata de forma assimétrica e verticalizada os conhecimentos, que defende a universalidade da ciência e a autonomia da tecnologia, que as considere como conhecimentos superiores e, portanto, que constrói a não existência de outros saberes, fomentando atitudes não apenas acríticas, mas sobretudo preconceituosas em relação aos diferentes saberes.Questões desse tipo são também postas à disposição do leitor ao abordar as Questões Sociocientíficas a partir de diversos olhares referenciais (da filosofia crítica, da política, da educação, da sociologia, da antropologia e dos estudos CTS).Questões éticas são fundamentais na educação científica e tecnológica e, neste particular momento histórico de acontecimentos dramáticos no cenário brasileiro e mundial, realçar a natureza política da educação científica e tecnológica é não apenas uma necessidade da educação CTS, mas um desafio para o processo de formação em todos os campos de saber.Seja para preparar aqueles que seguirão carreiras científicas e tecnológicas, seja para a educação em geral, todos deverão estar capacitados a assumir suas responsabilidades pela preservação da vida e pela sustentabilidade, como cidadãos em um mundo finito.Este livro oferece aos seus leitores a oportunidade de compartilhar saberes e de construir novos sentidos sobre os conhecimentos em um universo diverso, multicultural, pluriétnico, plurilíngue e, sobretudo, pleno de conhecimentos diferentes aos quais se deve dar igual importância.Bons livros de um campo interdisciplinar tão amplo como o dos Estudos CTS carregam a marca de sua época.Atentos aos eventos sócio-históricos, oferecem percepções consistentes da realidade e normalmente tornam-se referências de trabalhos e ações futuros e, desse modo, possuem potencial capacidade para transformar, partic', '["socioscientific issues","socio-technical challenges","science and technology education","citizenship education","emancipatory education","banking model of education","knowledge-power relations","sociotechnical controversies","sociopolitical action","democratic education","Paulo Freire","critical pedagogy"]', '10.7476/9788523220174', '9788523220174', 'https://books.scielo.org/id/n7g56', 'https://books.scielo.org/id/n7g56/pdf/conrado-9788523220174.pdf', NULL, 'https://books.scielo.org/id/n7g56/cover/cover_thumbnail.jpeg', NULL, 43, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-n7zmk', 'n7zmk', 'Novos rumos do direito ambiental: um olhar para a geodiversidade', NULL, '["Luciana Cordeiro de Souza-Fernandes","Alexandra Aragão","Artur A. Sá"]', 'Editora da Unicamp', 'Brasil', 'SciELO Books', 'books', 2021, '2021-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Esta obra inova por oferecer ao leitor diversos olhares sobre o tema ambiental unindo o direito ambiental às ciências da Terra. Destaca-se por incorporar a multi, a inter e a transdisciplinaridade necessárias para efetivação da legislação ambiental, a qual deve ser elaborada a partir do conhecimento e da assimilação dos conceitos das ciências da Terra. Seu pioneirismo está em articular os temas por meio de um conjunto de 24 capítulos de renomados autores, professores membros de grupos de pesquisa nacionais e internacionais, que demonstram e revelam a interconexão e a interdependência entre temas tão sinérgicos.', '["environmental law","geodiversity","earth sciences","transdisciplinarity","interdisciplinary approach"]', '10.7476/9788526815490', '9786586253870', 'https://books.scielo.org/id/n7zmk', NULL, NULL, 'https://books.scielo.org/id/n7zmk/cover/cover_thumbnail.jpeg', 559, 3, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-n8k9y', 'n8k9y', 'O que vamos fazer depois do trabalho? Reflexões sobre a preparação para aposentadoria', NULL, '["José Luiz Riani Costa","Amarilis Maria Muscari Riani Costa","Gilson Fuzaro"]', 'Editora UNESP', 'Brasil', 'SciELO Books', 'books', 2016, '2016-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Amarilis Maria Muscari Riani Costa O caminho trilhado até o momento 15 O Ciclo de Palestras sobre Preparação para Aposentadoria e seus desdobramentos 18 Referências bibliográficas 20 O título do livro, propositalmente, tem um duplo sentido.Muitas pessoas provavelmente associarão o título a um conjunto de atividades realizadas após o expediente de trabalho, popularmente conhecido como happy hour.Alguns poderão até pensar que se trata de um guia de bares e restaurantes destinados às confraternizações de final de tarde.O subtítulo deixa claro que não se trata disso, mas o que poderíamos chamar, por analogia, de happy years; ou seja, um "guia" para que o tempo da aposentadoria seja um período de anos felizes.Este livro surgiu da necessidade sentida de divulgar a experiência acumulada em uma série de atividades vinculadas à extensão universitária voltadas à preparação para a aposentadoria, bem como em projetos de pesquisa e publicações envolvendo docentes, servidores técnico-administrativos e pós-graduandos ligados à Unesp, no câmpus de Rio Claro. 1 A expectativa é que as reflexões aqui apresentadas contribuam para a implantação de progra mas de preparação para a aposentadoria (PPA) em insti-', '["retirement planning","university extension","happy hour","university employees","technical-administrative staff","graduate students","pension plans","UNESP Rio Claro"]', '10.7476/9788579837630', '9788579837630', 'https://books.scielo.org/id/n8k9y', 'https://books.scielo.org/id/n8k9y/pdf/costa-9788579837630.pdf', NULL, 'https://books.scielo.org/id/n8k9y/cover/cover_thumbnail.jpeg', NULL, 29, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-n93s9', 'n93s9', 'Polidocência na educação a distância: múltiplos enfoques', NULL, '["Daniel Ribeiro Silva Mill","Luis Roberto de Camargo Ribeiro","Marcia Rozenfeld Gomes de Oliveira"]', 'LA Referencia (Red Federada de Repositorios Institucionales de Publicaciones Científicas)', 'Brasil', 'SciELO Books', 'books', 2010, '2010-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', '[RETIRADO/WITHDRAWN] A tese do livro gira em torno do seguinte questionamento: quem é o docente da educação a distância? O trabalho docente na educação a distância (EaD) é extremamente fragmentado e cada parte das atividades que compõem o trabalho docente virtual é atribuída a um trabalhador diferente, ou a um grupo deles. Apesar de haver variações nos tipos de equipes entre uma experiência de EaD e outra (e.g., equipes baseadas numa concepção aditiva, na qual cada integrante executa uma parcela específica do trabalho, ou integrada, na qual as atividades são desempenhadas por todos), sabe-se que o trabalho docente a distância se organiza de forma coletiva e cooperativa. A esse conjunto articulado de trabalhadores, necessário para a realização das atividades de ensino-aprendizagem na EaD, denominamos de polidocência. O conceito de polidocência traz consigo algumas implicações e também pode ser observado de perspectivas distintas. Por isso, cada capítulo do livro pretende explorar um aspecto dessa noção de polidocência, buscando desvelar suas especificidades.', '["distance education","virtual teaching","teacher identity","teacher teams","collective teaching","cooperative teaching"]', '10.7476/9788576003632', '9788576003632', 'https://books.scielo.org/id/n93s9', NULL, NULL, 'https://books.scielo.org/id/n93s9/cover/cover_thumbnail.jpeg', NULL, 29, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-n99p3', 'n99p3', 'Avaliação das políticas de alimentação e nutrição: contribuições teóricas e práticas', NULL, '["Cruz, Marly Marques da","Barros, Denise Cavalcante de","Vitorino, Santuzza Arreguy Silva"]', 'Editora FIOCRUZ', 'Brasil', 'SciELO Books', 'books', 2023, '2023-03-29', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Assegurar à população os direitos constitucionais de alimentação e nutrição é ainda um grande desafio no Brasil, onde coexistem problemas nutricionais relacionados a sobrepeso e obesidade, fome e desnutrição e carências nutricionais específicas – cenário agravado durante a pandemia de Covid-19. A fim de demonstrar o quanto a avaliação favorece o aprimoramento das políticas públicas, os autores evidenciam o potencial do debate nas esferas acadêmica e gestora, considerando a capacidade das intervenções de promover transformação real na qualidade de vida da população. A obra, elaborada em duas partes, traz artigos de pesquisadores e profissionais da área, que conjugam os aspectos teóricos e práticos, e tem como público-alvo todos aqueles que participam do ciclo de políticas públicas em qualquer de suas etapas ― gestores, profissionais da saúde, acadêmicos, pesquisadores, especialistas ― reforçando a importância da formação de redes colaborativas. Com um conteúdo instigante e agradável, dá a conhecer ao leitor diversas formas de avaliar as políticas públicas, oferecendo novos paradigmas de avaliação, voltados para a abordagem colaborativa e participativa, de modo a atender os desafios impostos para o paradoxal cenário de alimentação e nutrição brasileiro.', '["nutrition policy","policy evaluation","policy cycle","collaborative networks","participatory evaluation","hunger and malnutrition","nutritional deficiency","COVID-19 pandemic","Brazil"]', '10.7476/9786557081792', '9786557081440', 'https://books.scielo.org/id/n99p3', NULL, NULL, 'https://books.scielo.org/id/n99p3/cover/cover_thumbnail.jpeg', 369, 3, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-n9brm', 'n9brm', 'Da produção ao consumo: impactos socioambientais no espaço urbano', NULL, '["Sílvia Aparecida Guarnieri Ortigoza","Ana Tereza Cáceres Cortez"]', 'Editora UNESP', 'Brasil', 'SciELO Books', 'books', 2009, '2009-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'A interdependência existente na relação entre produção, circulação e consumo deve contemplar a proteção do meio ambiente, assim a proposta de refl exão deste livro aborda a necessidade de discutir os resultados socioambientais das ações do homem nessas esferas.Nesse contexto, é preciso resgatar todo o movimento da ação humana e os principais impactos socioambientais decorrentes dessas ações.Fala-se sobre as cidades como materialidade dessas mudanças socioambientais no primeiro capítulo, intitulado "Da produção ao consumo: dinâmicas urbanas para um mercado mundial", que procura enfocar a necessidade de tratar, na totalidade, todas as relações sociais de produção, haja vista que a fragmentação no entendimento dessas esferas pode levar a uma compreensão parcial da realidade.A cidade demonstra em seu dinamismo faces que são resultados tanto da produção quanto da distribuição e do consumo.Desse modo, decompor os diversos cenários urbanos é muito importante para entender as complexidades espaciais da atualidade.Uma explosão do consumo surge como modo ativo de relação das pessoas com os objetos, com a coletividade e com o mundo, servindo de base ao nosso sistema cultural.Os objetos não estão mais relacionados exclusivamente à sua utilidade, mas ao prestígio simbolizado por sua posse.da produção e concorrência e caracteriza-se por suas dimensões organizacional, temporal e espacial, dimensões essas que permitem o desenho global, regional e local da rede, a interdependência, a diversifi cação dentro de cada escala espacial, a inclusão seletiva e portanto, excludente.Toda essa racionalidade da era das redes acaba desintegrando as "antigas" lógicas da geografi a econômica.Os estudos desenvolvidos por muitos geógrafos sobre redes geográfi cas têm sido guiados pela seguinte defi nição: rede geográfi ca é "um conjunto de localizações geográfi cas interconectadas ''entre si'' por um certo número de ligações" (Correa, 1997, p.107).Esse mesmo autor colabora diretamente nessa temática e a citação que segue coloca o papel das redes de cidades globais nessa realidade socioespacial:As cidades mundiais ou globais, sedes das grandes corporações multifuncionais e multilocalizadas, constituem, no fi nal do século XX, os epicentros de numerosas, complexas e desiguais redes que tornaram a organização espacial caleidoscopicamente fragmentada e globalizada.Desse modo o estudo das diferentes redes que compõem a organização espacial constitui-se em relevante tarefa para os geógrafos.(idem, p.108) Outro autor que contribui diretamente com os estudos das redes globais é Santos.Ele prefere denominá-las redes técnicas:As redes são mistas, elas incluem materialidade e ação.A rede técnica mundializada atual é instrumento da produção, da circulação e da informação mundializadas.Nesse sentido, as redes são globais e, desse modo, transportam o universal ao local.É assim que, mediante a telecomunicação, criam-se processos globais, unindo pontos distantes numa mesma lógica produtiva.É o funcionamento vertical do espaço geográfi co contemporâneo.(2005, p.168) Essa colocação contribui diretamente com a temática que estamos debatendo neste capítulo, pois coloca em debate as mudanças CASTELLS, M.', '["production and consumption","socio-environmental impacts","urban space","global cities","urban networks","consumption","social production","urban dynamics","international markets","environmental protection","urban materiality","urbanization and environment"]', '10.7476/9788579830075', '9788579830075', 'https://books.scielo.org/id/n9brm', 'https://books.scielo.org/id/n9brm/pdf/ortigoza-9788579830075.pdf', NULL, 'https://books.scielo.org/id/n9brm/cover/cover_thumbnail.jpeg', NULL, 22, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-n9nxv', 'n9nxv', 'La universidad interrogada: opacamiento de la formación y la experiencia', NULL, '["Carlos Sklíar","Alberto Martínez Boom","Sonia Cadena Castillo","Adriana De la Rosa","Jhon Henry Orozco","Alejandro Álvarez","Teresa Pontón","Ana Lucía Sanín Jiménez","María Eugenia Torres","Ana Milena Álvarez","Margot Cajigas Romero","Jaime López Osorno","Jaime Otero Meléndez","Dario Esteban Recalde Morillo"]', 'LA Referencia (Red Federada de Repositorios Institucionales de Publicaciones Científicas)', 'Colombia', 'SciELO Books', 'books', 2018, '2018-01-01', 'es', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Este texto busca organizar y sistematizar algunos de los problemas que tiene la universidad actual respecto a tres temas singulares: la pedagogía, la formación y la experiencia. Poner en común los problemas docente, en relación con estas tres variables, significó hacer y ensayar un esfuerzo compartido que recogemos ahora como libro.', '["university education","pedagogy","teacher professional development","experiential learning","educational challenges","higher education reform"]', '10.7476/9789586190107', '9789588994567', 'https://books.scielo.org/id/n9nxv', NULL, NULL, 'https://books.scielo.org/id/n9nxv/cover/cover_thumbnail.jpeg', 200, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-n9ydj', 'n9ydj', 'A arquitetônica da divulgação científica brasileira oitocentista: uma análise do discurso na perspectiva do Círculo de Bakhtin', 'uma análise do discurso na perspectiva do Círculo de Bakhtin', '["Urbano Cavalcante Filho"]', 'Editus', 'Brasil', 'SciELO Books', 'books', 2026, '2026-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'A obra investiga uma das iniciativas de divulgação científica mais relevantes do Brasil do/no século XIX: as Conferências Populares da Glória. Neste livro, Urbano Cavalcante Filho analisa esses discursos para mostrar como a divulgação da ciência foi utilizada como ferramenta política, ideológica e social na construção do pensamento republicano. Ciência e educação emergem como alicerces fundamentais, moldando debates sobre progresso, cidadania e modernização do país - questões que ainda reverberam na sociedade atual. Uma leitura indispensável para quem deseja compreender o passado e refletir sobre seus impactos no presente!', '["scientific dissemination","Bakhtin Circle","discourse analysis","19th-century Brazil","republican thought","science and politics","citizenship","modernization","progress","science and education"]', '10.7476/9788574556567', '9788574556468', 'https://books.scielo.org/id/n9ydj', NULL, NULL, 'https://books.scielo.org/id/n9ydj/cover/cover_thumbnail.jpeg', 319, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-nb', 'nb', 'Pensar o discurso no webjornalismo: temporalidade, paratexto e comunidades de experiência', NULL, '["Edson Fernando Dalmonte"]', 'EDUFBA', 'Brasil', 'SciELO Books', 'books', 2009, '2009-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Investiga o atual estágio do Webjornalismo, com base na análise do discurso, tomando-se por referência a perspectiva contratual da comunicação. A partir das características próprias do Webjornalismo, são localizados os elementos componentes de um quadro geral de "constrangimentos discursivos", base do posicionamento discursivo, estabelecido segundo a perspectiva do dispositivo, capaz de implementar novas formas de enunciação, resultando numa configuração paratextual. A obra reflete ainda sobre alguns critérios do mercado informacional. Nessa perspectiva trata o Webjornalismo como "bem de experiência" e ressalta a importância das "comunidades de experiência" para a simulação do contato entre as instâncias comunicacionais.', '["web journalism","discourse analysis","temporality","paratext","discursive constraints","discursive positioning","enunciation","information market","experience goods"]', '10.7476/9788523212155', '9788523212155', 'https://books.scielo.org/id/nb', 'https://books.scielo.org/id/nb/pdf/dalmonte-9788523212155.pdf', NULL, 'https://books.scielo.org/id/nb/cover/cover_thumbnail.jpeg', NULL, 7, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-nbpwk', 'nbpwk', 'A persistência dos deuses', NULL, '["Eduardo R. Cruz"]', 'Editora UNESP', 'Brasil', 'SciELO Books', 'books', 2004, '2004-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'PARADIDÁTICOS - SÉRIE: CULTURA Um dos traços culturais brasileiros que mais se destaca é o da pluralidade e vitalidade religiosas e o "jeitinho brasileiro" para lidar com a questão religiosa está presente nesta obra. Com um texto empolgante, o autor apresenta "as regras do jogo" no universo das religiões estabelecidas e põe em xeque o dito popular de que "religião, política e futebol não se discutem", ao abordar: a identidade nacional, a separação Igreja-Estado, a obrigatoriedade do ensino religioso no país e o entendimento moderno da religião como forma de cultura. Eduardo Rodrigues propõe uma reflexão sobre as características universais da religião ao debater a forma como ela produz deuses e seus mundos sobrenaturais.', '["religion in Brazil","religious pluralism","religion and politics","football and religion","national identity","separation of church and state","religious education","religion as culture","God"]', '10.7476/9788539303359', '9788571395572', 'https://books.scielo.org/id/nbpwk', NULL, NULL, 'https://books.scielo.org/id/nbpwk/cover/cover_thumbnail.jpeg', 91, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-nc8tm', 'nc8tm', 'El pensamiento Kuna o la utopía realmente existente', NULL, '["Adolfo Chaparro Amaya"]', 'Editorial Universidad del Rosario', 'Colombia', 'SciELO Books', 'books', 2014, '2014-01-01', 'es', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Los kunas que habitan al noreste de la costa panameña son herederos de los más antiguos guerreros que resistieron tanto la conquista española desde comienzos del siglo XVI como el posterior asedio misionero y comercial del Estado modernizador. Sin pretender una etnografía detallada de los kuna, este texto plantea un estudio sistemático de aspectos nodales de su pensamiento jurídico, económico, estético y religioso. Explorando los recursos del lenguaje ritual, las formas de escritura y el pensamiento mítico, el texto muestra cómo los kunas responden y se vuelven receptivos al otro sin dejar de ser lo que son. El resultado es un sincretismo polifacético que demuestra la eficacia de la estrategia de intercambio sin integración para la continuidad de la máquina territorial kuna. Siendo la globalización de la forma Estado una suerte de utopía práctica en proceso de consolidación, la afirmación de una nación indígena que mantiene formas democráticas inspiradas en una tradición mítica singular se convierte en un desafío y una alternativa (a)histórica, vigente en su anacronismo, que resuena en comunidades étnicamente diferenciadas de todo el mundo. Sin ignorar la fragilidad del modo de existencia kuna, esa persistencia en la singularidad de su pensamiento, y en su fijeza étnica y territorial, se puede leer como un paradigma de política minoritaria, contrahegemónica, autoinmunitaria. En ese contexto, el texto cumple con la promesa metódica inicial: demostrar que siguiendo los avatares de una comunidad particular es posible deconstruir la oposición mito/utopía en su enunciación abstracta o ilusoria al poner en evidencia la fuerza utópica del mito como ethos comunitario de la experiencia histórica.', '["Kuna people","ritual language","writing practices","religious syncretism","territorial continuity","Indigenous nationhood","counter-hegemonic politics","minority politics","state formation","globalization","community ethos"]', '10.7476/9789587385014', '9789587385014', 'https://books.scielo.org/id/nc8tm', 'https://books.scielo.org/id/nc8tm/pdf/chaparro-9789587385014.pdf', NULL, 'https://books.scielo.org/id/nc8tm/cover/cover_thumbnail.jpeg', NULL, 2, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-ncmhn', 'ncmhn', 'Imprensa escrita e telejornal', NULL, '["Juvenal Zanchetta"]', 'Editora UNESP', 'Brasil', 'SciELO Books', 'books', 2004, '2004-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'PARADIDÁTICOS - SÉRIE: LINGUAGENS E REPRESENTAÇÕES Obra que analisa a notícia impressa, o fotojornalismo e a notícia de telejornal. Para tratar desses "gêneros textuais" associados ao jornal impresso e abordar o telejornal, particularmente o Jornal Nacional da Rede Globo de Televisão, o autor se concentra sobre um conjunto de mediadores externos e internos que atuam no atual modo de fazer jornalismo. Sua visão crítica e distanciada desmascara as aparentes objetividade e isenção idealmente características da atividade jornalística. Coloca o papel central ocupado pela imprensa na sociedade contemporânea, num enfoque de "quarto poder" arbitrário, opressor e manipulador da opinião pública e de instrumento redentor da democratização da informação.', '["newspaper journalism","television news","Jornal Nacional","Rede Globo","news genres","photojournalism","news objectivity","media and public opinion","democratization of information","fourth power"]', '10.7476/9788539303175', '9788571395558', 'https://books.scielo.org/id/ncmhn', NULL, NULL, 'https://books.scielo.org/id/ncmhn/cover/cover_thumbnail.jpeg', 134, 18, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-ncqn8', 'ncqn8', 'A missão portuguesa', NULL, '["Fernando Lemos","Rui Moreira Leite"]', 'Editora UNESP', 'Brasil', 'SciELO Books', 'books', 2003, '2003-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'Desdobramento natural da mostra de 30 painéis organizada para acompanhar o Congresso Internacional "Sinais de Jorge de Sena", em 1998, homenageia os artistas lusos que viveram e trabalharam no País, interagindo de forma marcante com a cultura nacional. (Co-edição: Editora da Universidade do Sagrado Coração)', '["Portuguese artists","Jorge de Sena","art exhibitions","national culture","national identity in art"]', '10.7476/9788539303250', '9788571394612', 'https://books.scielo.org/id/ncqn8', NULL, NULL, 'https://books.scielo.org/id/ncqn8/cover/cover_thumbnail.jpeg', 236, 1, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-ncqxp', 'ncqxp', 'Clientelismo político, ¿desviación de la política o forma de representación?: Estado del arte sobre las aproximaciones al clientelismo en Colombia 1973-2011', NULL, '["Laura Daniela Guerrero García"]', 'Editorial Universidad del Rosario', 'Colombia', 'SciELO Books', 'books', 2014, '2014-01-01', 'es', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'El clientelismo político en Colombia, desde hace unas cuatro décadas, se ha venido configurado como objeto de estudio de antropólogos, sociólogos, historiadores y politólogos, incluso, se ha configurado como materia de discusión de periodistas y abogados. Los escándalos de corrupción en instituciones públicas, asociados erróneamente con el clientelismo, han suscitado el interés de muchos estudios de caso, que corroboran la existencia de racionalidades útiles a quienes detentan el poder, pero ineficientes dentro de las lógicas de un Estado moderno regido por la trasparencia, meritocracia y la participación ciudadana en defensa de lo público.', '["political clientelism","clientelism","political representation","corruption scandals","public institutions","modern state","transparency","meritocracy","citizen participation","Colombia"]', '10.7476/9789587385526', '9789587385526', 'https://books.scielo.org/id/ncqxp', 'https://books.scielo.org/id/ncqxp/pdf/guerrero-9789587385526.pdf', NULL, 'https://books.scielo.org/id/ncqxp/cover/cover_thumbnail.jpeg', NULL, 3, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-ncvg5', 'ncvg5', 'Movimentos da hesitação: deslizamentos do dizer em sujeitos com doença de Parkinson', NULL, '["Roberta Cristina Rodrigues Vieira","Lourenço Chacon"]', 'Editora UNESP', 'Brasil', 'SciELO Books', 'books', 2015, '2015-01-01', 'pt', 'book', 'medical-health', 'Ciencias Médicas y de la Salud', 'Health Professions', 'Considerações finais: possíveis contribuições para a clínica fonoaudiológica 93 Referências bibliográficas 101 Sobre os autores 107 APRESENTAÇÃONeste livro, abordaremos um funcionamento hesitativo bastante frequente no discurso de sujeitos com doença de Parkinson: os deslizamentos do dizer em contexto fonético-fonológico recorrente.Nosso interesse mais particularizado pelo estudo desse funcionamento das hesitações ou, de modo mais amplo, pelo estudo das próprias hesitações, resultou, primeiramente, do fato de nos situarmos em um lugar que consideramos privilegiado para a observação de questões mais gerais de linguagem, e, de modo mais específico, de suas características em sujeitos parkinsonianos: o lugar da interseção entre os campos de conhecimento da Fonoaudiologia e da Linguística.Situados nesse lugar, nosso interesse acabou voltando-se para a observação empírica e teórica dessas questões.Em nosso contato cotidiano com questões de linguagem (clínicas e teóricas), no qual defrontamos com a interseção desses dois campos, o teórico e o empírico, temos constatado que as hesitações são bastante frequentes nos enunciados falados de parkinsonianos.A literatura (biomédica), ao explicar teoricamente seu funcionamento cursivos subjacentes às alterações de linguagem, pretendemos, ao estudar o funcionamento hesitativo, mostrar a importância de uma visão linguístico-discursiva dele para melhor compreensão dos problemas que, no interior desse campo do conhecimento, são caracterizados como distúrbios de linguagem ou que, em outra perspectiva, caracterizariam uma fala sintomática.• Pretendemos, ainda, com o nosso estudo, possibilitar melhor compreensão acerca do funcionamento hesitativo no campo da Linguística, levando para esse campo reflexões feitas a partir da análise de dados extraídos de contextos patológicos da linguagem.Este livro está organizado em quatro capítulos.No Capítulo 1, "A doença de Parkinson", o leitor encontrará um apanhado teórico de como têm sido estudadas as hesitações em sujeitos com essa doença, bem como uma síntese de nossa compreensão teórica sobre elas.Para tanto, nele apresentaremos estudos que consideramos representativos da literatura biomédica sobre essa doença, os quais ilustram, de modo privilegiado, como os aspectos relacionados à linguagem têm sido entendidos nessa literatura.Mais especificamente, será destacado um desses aspectos, as hesitações, e como elas têm sido entendidas em trabalhos sobre a linguagem nos sujeitos parkinsonianos construídos sob diferentes perspectivas teóricas.Apresentaremos nesse capítulo, ainda, de modo breve, os conceitos que fundamentarão a análise dos dados de nosso estudo.No Capítulo 2¸ "Aspectos metodológicos", apresentaremos aspectos do banco de dados do qual selecionamos o material utilizado no estudo, bem como o recorte realizado, dentre o vasto material que compõe o banco, para a escolha do sujeito e da sessão de conversação analisada. ROBERTA VIEIRA • LOURENÇO CHACONAinda nesse capítulo, faremos uma breve caracterização das hesitações e dos critérios utilizados para a seleção dos enunciados analisados.No Capítulo 3, "Resultados e discussão", apresentaremos os dados recolhidos, o funcionamento e as características das hesitações.Por fim, nas "Considerações finais", retomaremos caminhos percorridos ao longo do trabalho, destacando as contribuições que esperamos ter oferecido, sobretudo aquelas que podem fornecer subsídios para a clínica de linguagem com sujeitos afetados pela doença de Parkinson.', '["Parkinson''s disease","hesitation","speech errors","speech disorders","phonological processing","phonetic analysis","discourse analysis","language pathology","speech therapy","stuttering","prosody","neurodegenerative language disorders"]', '10.7476/9788579836640', '9788579836640', 'https://books.scielo.org/id/ncvg5', 'https://books.scielo.org/id/ncvg5/pdf/vieira-9788579836640.pdf', NULL, 'https://books.scielo.org/id/ncvg5/cover/cover_thumbnail.jpeg', NULL, 3, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-nf9bn', 'nf9bn', 'Clínica e terapêutica da doença de Chagas: uma abordagem prática para o clínico geral', 'uma abordagem prática para o clínico geral', '["Dias, João Carlos Pinto","José Rodrigues Coura"]', 'Editora FIOCRUZ', 'Brasil', 'SciELO Books', 'books', 1997, '1997-01-01', 'pt', 'book', 'medical-health', 'Ciencias Médicas y de la Salud', 'Medicine', 'Um verdadeiro tratado clínico e terapêutico sobre Chagas, que reúne os maiores especialistas na enfermidade. Os autores pretendem a difusão dos conhecimentos e práticas que habilitam o manejo adequado desta parasitose contidos neste ''manual'', principalmente entre aqueles que vivem e trabalham nas áreas endêmicas de ocorrência, na busca de minimizar os sofrimentos que a tripanossomíase tem imposto a populações. Com esse objetivo, a obra vem mostrar que não só a doença pode e deve ser prevenida, bem como é possível diagnosticá-la entre os já infectados e dar a estes uma atenção específica capaz de atenuá-la ou mesmo de curá-la em certas circunstâncias.', '["Chagas disease","Trypanosoma cruzi","clinical management","treatment","diagnosis","prevention","endemic areas","parasitic infection"]', '10.7476/9788575412435', '9788585676315', 'https://books.scielo.org/id/nf9bn', 'https://books.scielo.org/id/nf9bn/pdf/dias-9788575412435.pdf', NULL, 'https://books.scielo.org/id/nf9bn/cover/cover_thumbnail.jpeg', NULL, 102, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-nfxby', 'nfxby', 'Educação física e ciências do esporte no tempo presente: desmonte dos processos democráticos, desvalorização da ciência, da educação e ações em defesa da vida', NULL, '["Vicente Molina Neto"]', 'EDUEM', 'Brasil', 'SciELO Books', 'books', 2021, '2021-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'O livro é um enfrentamento e uma reflexão crítica sobre diferentes marcadores sociais estruturantes da nossa vida social (racismo, gênero, classe social, educação e saúde, esporte e lazer, entre outros). A obra se constitui de duas partes: na primeira, quatro personalidades que transcendem suas especificidades disciplinares, com reconhecimento nacional e internacional, discorrem sobre os temas e questões sociais fundamentais e uma segunda em que pesquisadores das ciências do esporte trazem o conhecimento avançado de seus grupos de trabalho na tentativa de estimular o pensamento crítico e o engajamento ao pensamento democrático.', '["physical education","sports science","democratic process","critical thinking","social markers","racism","gender","social class","health","sport and leisure","protection of life"]', '10.7476/9786586383829', '9786586383829', 'https://books.scielo.org/id/nfxby', 'https://books.scielo.org/id/nfxby/pdf/vago-9786586383829.pdf', NULL, 'https://books.scielo.org/id/nfxby/cover/cover_thumbnail.jpeg', NULL, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-ngbrd', 'ngbrd', 'A Cosmopolítica da gestação, do parto e do pós-parto: autoatenção e medicalização entre os índios Munduruku', NULL, '["Raquel Paiva Dias-Scopel"]', 'Editora FIOCRUZ', 'Brasil', 'SciELO Books', 'books', 2018, '2018-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'A pesquisadora Raquel Paiva Dias-Scopel, do Instituto Leônidas e Maria Deane (ILMD/Fiocruz Amazônia), levanta questões sobre a valorização e respeito à diversidade étnica e cultural dos povos indígenas e a difícil interface com o processos de medicalização e do direito ao acesso aos serviços de saúde biomédicos. O livro é parte da Coleção Saúde dos Povos Indígenas, da Editora Fiocruz e partiu da tese de doutorado defendida em 2014 no Programa de Pós-Graduação em Antropologia Social da Universidade Federal de Santa Catarina (UFSC). Foi publicado pela primeira vez em 2015 pela Associação Brasileira de Antropologia com o título A Cosmopolítica da Gestação, Parto e Pós-Parto: práticas de autoatenção e processo de medicalização entre os índios Munduruku. No prefácio da primeira edição, sua orientadora, a doutora em antropologia e professora titular da UFSC, Esther Jean Langdon, ressalta que o conceito fundamental deste livro é da autoatenção, que aponta para o reconhecimento da autonomia e da criatividade da coletividade, principalmente da família, como núcleo que articula os diferentes modelos de atenção ou cuidado da saúde', '["Munduruku","indigenous peoples","medicalization","self-care","pregnancy","childbirth","postpartum care","cosmopolitanism","family autonomy","ethnic and cultural diversity","health care practices"]', '10.7476/9786557080146', '9786557080146', 'https://books.scielo.org/id/ngbrd', 'https://books.scielo.org/id/ngbrd/pdf/dias-9786557080146.pdf', NULL, 'https://books.scielo.org/id/ngbrd/cover/cover_thumbnail.jpeg', NULL, 1, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
