INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-ngnq4', 'ngnq4', 'Formação de professores para uma educação plural e democrática: narrativas, saberes, práticas e políticas educativas na América Latina', NULL, '["Sangenis, Luiz Fernando Conde","Oliveira, Elaine Ferreira Rezende de","Carreiro, Heloísa Josiele Santos"]', 'EDUERJ', 'Brasil', 'SciELO Books', 'books', 2018, '2018-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'formação de Professores Na américa latiNa 5. El accionar de un congreso internacional sobre interculturalidad en la voz reflexiva de profesores indígenas . . . . . . . . . . . .', '["teacher professional development","plural education","democratic education","interculturality","indigenous teachers","educational narratives","educational knowledge","teaching practice","education policy","Latin America"]', '10.7476/9788575114841', '9788575114841', 'https://books.scielo.org/id/ngnq4', 'https://books.scielo.org/id/ngnq4/pdf/sangenis-9788575114841.pdf', NULL, 'https://books.scielo.org/id/ngnq4/cover/cover_thumbnail.jpeg', NULL, 1, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(exclu