INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-ngswq', 'ngswq', 'Ejercicio del control de convencionalidad por jueces administrativos: estudio de caso de Cúcuta. Una percepción desde la judicatura', 'estudio de caso de Cúcuta. Una percepción desde la judicatura', '["Cubides-Cárdenas, Jaime","Castillo Galvis, Sergio Hernando","González Agudelo, Juan David"]', 'Editorial Fundación Universitaria San Mateo', 'Brasil', 'SciELO Books', 'books', 2022, '2022-01-01', 'es', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'El presente libro de investigación tiene por objeto de estudio el ejercicio del control de convencionalidad por los jueces administrativos del distrito judicial de Cúcuta, Colombia, en procesos de responsabilidad contra el Estado, iniciadas a través del medio de control de reparación directa, con ocasión de graves violaciones de derechos humanos. Reconoce que con la transformación de fuentes jurídicas en Colombia los instrumentos de rango internacional que cumplan con los criterios del artículo 93 harán parte del denominado bloque de constitucionalidad, sea en su sentido estricto o amplio. Sin embargo, en cualquiera de los casos resulta vinculante como resultado de la función integradora o interpretativa.', '["constitutional review","administrative courts","state liability","human rights violations","constitutional block","judges'' perceptions","Cúcuta"]', '10.7476/9786287725164', '9786289526240', 'https://books.scielo.org/id/ngswq', 'https://books.scielo.org/id/ngswq/pdf/cubides-9786287725164.pdf', 'https://books.scielo.org/id/ngswq/epub/cubides-9786287725164.epub', 'https://books.scielo.org/id/ngswq/cover/cover_thumbnail.jpeg', 159, 1, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-ngzt3', 'ngzt3', 'A obra literária de João Paulo Borges Coelho. Panorama crítico', NULL, '["Brugioni, Elena","Gallo, Fernanda","Zanfelice, Gabriela Beduschi"]', 'Editora da Unicamp', 'Brasil', 'SciELO Books', 'books', 2022, '2022-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'Esta primeira coletânea de ensaios dedicada ao conjunto das obras literárias de João Paulo Borges Coelho coincide com a estreia do escritor moçambicano no Brasil e com o crescente interesse que sua literatura vem suscitando no meio acadêmico nacional. O livro aborda a totalidade das obras do autor publicadas até o momento: desde o romance de estreia, As duas sombras do rio (2003), até o mais recente, Museu da Revolução (2021). Nos 12 capítulos aqui reunidos, especialistas apontam a sofisticação e a originalidade da criação de JPBC, videnciando discussões teóricas e percursos interpretativos de grande pertinência e atualidade no campo de estudo sobre as literaturas africanas contemporâneas.', '["João Paulo Borges Coelho","Mozambican literature","contemporary African literature","literary criticism","literary interpretation"]', '10.7476/9788526816442', '9788526815261', 'https://books.scielo.org/id/ngzt3', NULL, NULL, 'https://books.scielo.org/id/ngzt3/cover/cover_thumbnail.jpeg', 325, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-nhddk', 'nhddk', 'Pensar a Loucura: trilhas literárias, culturais, históricas', NULL, '["Maia, João Roberto","Reis, José Roberto Franco","Cruz, Leandra Brasil da"]', 'Editora FIOCRUZ', 'Brasil', 'SciELO Books', 'books', 2023, '2023-01-01', 'pt', 'book', 'medical-health', 'Ciencias Médicas y de la Salud', 'Psychology', 'Os textos que compõem este volume nos levam a refletir sobre o papel da arte-cultura como trilhas, ou pistas, na mediação e diálogo entre as várias e diversas formas de ser e as relações sociais. Ou seja, sobre arte-cultura como dispositivo de construção de novos lugares sociais, de novas formas de significação para a loucura. É na possibilidade de trazer mais reflexões, mais questionamentos, que reside a originalidade desta coletânea.', '["madness","madness in literature","history of madness","social construction of meaning","interpersonal relationships"]', '10.7476/9786557082171', '9786557081808', 'https://books.scielo.org/id/nhddk', NULL, NULL, 'https://books.scielo.org/id/nhddk/cover/cover_thumbnail.jpeg', 312, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-njb43', 'njb43', 'Adolescência em foco: contribuições para a psicologia e para a educação', NULL, '["Záira Fátima de Rezende Gonzalez Leal","Marilda Gonçalves Dias Facci","Marilene Proença Rebello de Souza"]', 'LA Referencia (Red Federada de Repositorios Institucionales de Publicaciones Científicas)', 'Brasil', 'SciELO Books', 'books', 2014, '2014-01-01', 'pt', 'book', 'medical-health', 'Ciencias Médicas y de la Salud', 'Psychology', 'Esta coletânea reúne textos de diferentes autores que têm, em comum, o estudo de aspectos da adolescência, tendo como base uma perspectiva crítica de análise em Psicologia Histórico-Cultural. Busca oferecer ao leitor novas possibilidades de compreensão da adolescência, procurando contribuir para a reflexão e intervenção na área da Educação e Psicologia.', '["adolescence","historical-cultural psychology","critical analysis","adolescent psychology","adolescent education","psychological intervention"]', '10.7476/9788576286585', '9788576286004', 'https://books.scielo.org/id/njb43', NULL, NULL, 'https://books.scielo.org/id/njb43/cover/cover_thumbnail.jpeg', 187, 7, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-njj38', 'njj38', 'Entre a oralidade e a escrita: a etnografia nos candomblés da Bahia', NULL, '["Lisa Earl Castillo"]', 'EDUFBA', 'Brasil', 'SciELO Books', 'books', 2010, '2010-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Pesquisa etnográfica de grande importância para o estudo das religiões de matrizes africanas no Brasil. Examina a interface entre a oralidade e a escrita nos candomblés da Bahia, demonstrando a importância da relação entre saber e poder dentro da hierarquia religiosa. Analisa a transmissão do saber dentro da secular tradição oral, passando pelo antigo gênero do caderno de fundamento, até as polêmicas atuais sobre a produção textual de sacerdotes autores.', '["Candomblé","Afro-Brazilian religions","orality and writing","religious hierarchy","transmission of knowledge","religious texts","Bahia"]', '10.7476/9788523211875', '9788523205218', 'https://books.scielo.org/id/njj38', NULL, NULL, 'https://books.scielo.org/id/njj38/cover/cover_thumbnail.jpeg', 231, 23, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-nkdqb', 'nkdqb', 'Filosofia da psicanálise: autores, diálogos, problemas', NULL, '["Richard Theisen Simanke","García Menéndez, Ada Jimena","Fátima Siqueira Caropreso","Izabel Cristina Barbelli","Josiane Cristina Bocchi"]', 'EdUFSCar', 'Brasil', 'SciELO Books', 'books', 2010, '2010-01-01', 'pt', 'book', 'medical-health', 'Ciencias Médicas y de la Salud', 'Psychology', '[RETIRADO/WITHDRAWN] Trata-se de uma coletânea de textos dos mais destacados pesquisadores nacionais e internacionais da atualidade na área de Filosofia da Psicanálise, que procura contribuir para a consolidação e delimitação desse novo campo disciplinar em formação. Os ensaios reunidos abrangem temas que vão das questões epistemológicas que emanam do campo psicanalítico às diversas interlocuções que se podem estabelecer - e que, de fato, vêm se estabelecendo - entre as ideias formuladas pelos grandes teóricos da psicanálise e as diferentes linhagens de pensamento no âmbito da tradição filosófica, passando ainda pela filosofia da prática psicanalítica e pelas implicações éticas e sociopolíticas da psicanálise, entre outras questões.', '["philosophy of psychoanalysis","psychoanalytic epistemology","psychoanalytic practice","psychoanalytic ethics","psychoanalysis and philosophy"]', '10.7476/9788576003663', '9788576003663', 'https://books.scielo.org/id/nkdqb', NULL, NULL, 'https://books.scielo.org/id/nkdqb/cover/cover_thumbnail.jpeg', NULL, 3, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-nkhks', 'nkhks', 'Autotradução: breve histórico, razões, consequências, práticas', NULL, '["Maria Alice Gonçalves Antunes"]', 'LA Referencia (Red Federada de Repositorios Institucionales de Publicaciones Científicas)', 'Brasil', 'SciELO Books', 'books', 2019, '2019-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'Este livro oferece um panorama abrangente, preciso, bem fundamentado e atualizado da autotradução e suas diferentes motivações e realizações. Sem deixar de lado a referenciação e o rigor necessários e recomendáveis, o texto flui de forma tal que poderá atrair também o leitor não acadêmico. Aliando teoria à prática, a autora, no capítulo final, nos permite compartilhar de sua própria experiência como autotradutora de textos acadêmicos, quando revela, em estilo saboroso e coloquial – que de certa forma rompe com o tom mais objetivo e impessoal da pesquisadora observado nos capítulos anteriores –, seu diálogo interno com o autor do texto e consigo mesma, sua visão de tradução, suas estratégias… enfim, o que está por trás de suas escolhas tradutórias. E como bônus, no final do volume há um glossário, apresentando os principais conceitos utilizados, o que potencializa a utilidade da obra em cursos de tradução em geral.', '["self-translation","academic texts","translator''s experience","translation strategies","translator''s perspective"]', '10.7476/9786588808061', '9788575115053', 'https://books.scielo.org/id/nkhks', NULL, NULL, 'https://books.scielo.org/id/nkhks/cover/cover_thumbnail.jpeg', 104, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-nn5mf', 'nn5mf', 'Ensaios de teatro e filosofia: do Renascimento ao século XVIII', NULL, '["Ana Portich"]', 'Editora UNESP', 'Brasil', 'SciELO Books', 'books', 2021, '2021-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'Esses Ensaios de teatro e filosofia têm como fio condutor a filosofia de Diderot e Rousseau, em paralelo com o teatro forjado pela Contrarreforma. A autora faz uma leitura a contrapelo da tendência desconstrucionista, que passa ao leitor contemporâneo a falsa impressão de que Diderot tenha defendido a metafísica da presença, contra a representação. Rousseau trabalha na confluência de teoria da linguagem, moral, política e teatro. No âmbito ibérico, vemos as consequências políticas do entrecruzamento da comédia e da tragédia praticado pelo dramaturgo luso-brasileiro António José da Silva, o Judeu. Retrocedendo ao século XVII, o cartesianismo encontra terreno fértil nas tragédias de Corneille e o teatro do Século de Ouro é atravessado pelo jusnaturalismo defendido por Grotius. Na commedia dell’arte, o desbragamento é compatível com o dogma da Queda como apanágio do humano e com o excesso de dispêndio, próprio da sociedade de corte. Shakespeare assume o hermetismo concebido em Florença no Quatrocentos para caracterizar a personagem Ofélia como regida pelo elemento água; a própria catástrofe de Hamlet está associada a seu temperamento melancólico.', '["theatre and philosophy","Denis Diderot","Jean-Jacques Rousseau","metaphysics of presence","linguistic theory","ethics","political philosophy","Antônio José da Silva","tragedy and comedy","Cartesianism","Pierre Corneille","Hugo Grotius"]', '10.7476/9786557140536', '9786557140536', 'https://books.scielo.org/id/nn5mf', 'https://books.scielo.org/id/nn5mf/pdf/portich-9786557140536.pdf', NULL, 'https://books.scielo.org/id/nn5mf/cover/cover_thumbnail.jpeg', NULL, 1, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-npy7z', 'npy7z', 'Tópicos em Malacologia Médica', NULL, '["Frederico Simões Barbosa"]', 'Editora FIOCRUZ', 'Brasil', 'SciELO Books', 'books', 1995, '1995-01-01', 'pt', 'book', 'medical-health', 'Ciencias Médicas y de la Salud', 'Salud Colectiva', 'Prefacio E muito bem-vindo este livro de malacologia na atual conjuntura das Ciências Biológicas e da Saúde Pública do Brasil.Pensado e materializado no seio da Fiocruz e da Universidade, ele retrata uma vocação da comunidade científica brasileira para com suas doenças endêmicas, uma tradição consolidada desde Oswaldo Cruz e Carlos Chagas, no início deste século.Frederico Simões Barbosa e seus companheiros dão aqui seqüência a esta caminhada, trabalhando com os moluscos que, em nosso país, apresentam a sua maior importância quando veiculam a esquistossomose mansoni.Estimando-se que acometa pelo menos 10 milhões de brasileiros, a esquistossomose tem origens históricas nas fortes correntes da migração afro-brasileira dos tempos da escravidão, alcançando nosso país pelo Nordeste e encontrando possibilidades de transmissão em três espécies de moluscos brasileiros.é ainda pior...* Altos índices de analfabetismo, desnutrição, parcos salários e muito baixa capacidade de organização e reivindicação política são outras características das populações mais expostas à esquistossomose.O modelo político-econômico desprivilegia totalmente essas populações, oferecendo-lhes como estratégia de sobrevivência as migrações internas e a urbanização.Vão junto os esquistossomas e os caramujos, espraiando a doença pelo País e urbanizando sua transmissão.Hoje já se conhecem importantes focos de esquistossomose com transmissão ativa em várias metrópoles brasileiras, coincidentemente acometendo as populações excluídas, mal assalariadas e desprovidas de educação, de água e de esgoto.Neste contexto e nesta história, os moluscos transmissores da esquistossomose no Brasil têm-se revelado bastante competentes, aprendendo a adaptar-se às mais distintas condições ambientais e a sobreviver ou recuperar suas populações em meio ambiente, provocada pelos resíduos industriais, por pesticidas agrícolas e mesmo por potentes moluscicidas.Visto até pouco tempo como o elo mais vulnerável da cadeia epidemiológica da esquistossomose, o caramujo mostrou-se um formidável adversário da Saúde Pública, sendo plenamente justificáveis os esforços para conhecê-lo melhor.Neste sentido, a malacologia brasileira teve o seu maior desenvolvimento a partir dos anos 50, quando bons grupos de investigação se iniciaram em Minas Gerais, em Pernambuco, na Bahia, em São Paulo e no Instituto Oswaldo Cruz.Nomes como Lobato Paraense e Simões Barbosa muito cedo se destacaram entre os grandes pesquisadores mundiais.Nos anos 60, as áreas finalísticas do Ministério da Saúde ligadas à esquistossomose mantinham excelente interface com os centros de investigação e tinham mesmo sua própria massa crítica de pesquisa, desenvolvimento e vigilância sanitária concentrada no Instituto Nacional de Endemias Rurais (INERu).Na década de 70, no bojo do regime militar e de uma série de perseguições aos investigadores, a malfadada Reforma Rocha Lagoa fez desaparecer o INERu e enfraquecer bastante as relações entre os serviços e a investigação.Houve mesmo episódios de confronto, como aquele em que pesquisadores brasileiros foram pejorativamente tachados de "mandarins da esquistossomose" por autoridades ministeriais.Não obstante, iniciativas como o Programa Integrado de Doenças Endêmicas (PIDE), do CNPq, e os emergentes cursos de pós-graduação em algumas universidades reforçam as investigações sobre a esquistossomose.Desta época, o maior produto no âmbito da parasitose foi indubitavelmente a radical modificação de sua abordagem programática, advinda da descoberta de drogas esquistossomicidas como a Oxamniquine e o Praziquantel, capazes de controlar efetivamente as formas graves da doença.Pari passu, uma nova perspectiva de atenção à saúde se formatava em Alma-Ata, em busca das ações *Amaral, R. S. & Porto, MAS, 1994.Evoluçăo e situaçăo atual do controle da esquistossomose no Brasil.Revista da Sociedade Brasileira de Medicina Tropical, 27 (Suplemento III): 7390.Refira-se ainda que a fauna malacológica é muito rica e importante na biocenose de nossas águas, havendo muito por explorar e reconhecer.Como mencionado, Frederico Simões Barbosa há muitos anos vem contribuindo na pesquisa, no ensino e na resolução de nossos grandes problemas de saúde, notadamente da esquistossomose.Sua vocação é estar permanentemente indagando, cercado de gente idealista, a dizer as suas coisas e a palmilhar sertões e povoados.Não estranha, pois, mais este livro, eminentemente prático e essencialmente dirigido à formação de técnicos e de alunos.Desde os primeiros textos da Sistemática e da Biogeografia, percebe-se a inquietação em contextualizar a malacologia brasileira numa projeção ao serviço.A Etologia, a Embriología e a relação molusco-parasita abrem campo e caminho à discussão do controle.Esta se faz numa perspectiva ecológica, como se deveria esperar dos autores deste livro.Ao final, uma importante série de aspectos práticos compõe seis itens sobre técnicas malacológicas, destinadas ao estudante, ao técnico de campo e ao iniciante à pesquisa.Aqui se manifesta uma vez mais a sintonia dos autores com as questões éticas mais fundamentais para aqueles que estudam as coisas da Saúde Pública: o objeto a serviço do homem, na construção de uma sociedade em que as doenças não separem demasiadamente os homens.Num sentido prático,', '["schistosomiasis mansoni","snail control","Mollusca","endemic disease","socioeconomic vulnerability","Oswaldo Cruz","Carlos Chagas","Brazil","molluscicides"]', '10.7476/9788575414019', '9788575414019', 'https://books.scielo.org/id/npy7z', 'https://books.scielo.org/id/npy7z/pdf/barbosa-9788575414019.pdf', NULL, 'https://books.scielo.org/id/npy7z/cover/cover_thumbnail.jpeg', NULL, 19, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-nq', 'nq', 'O poder dos candomblés: perseguição e resistência no Recôncavo da Bahia', NULL, '["Edmar Ferreira Santos"]', 'EDUFBA', 'Brasil', 'SciELO Books', 'books', 2009, '2009-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'Nos tempos atuais de crescente visibilidade pública dos candomblés, dos seus registros nos livros de tombo e da retórica de preservação dos patrimônios culturais afro-brasileiros, não resulta supérfluo lançar um olhar atento para um passado não tão remoto em que tais práticas de matriz africana eram ora silenciadas, ora perseguidas e depreciadas porquanto identificadas com atraso e desvio dos modelos civilizatórios europeus. Se esse olhar retrospectivo resulta salutar ao constatar o quanto se avançou, ele também nos alerta para o quanto ainda se precisa avançar, pois os discursos da intolerância religiosa de ontem se alastram até hoje, embora em novos púlpitos, com os mesmos efeitos perniciosos. Nesse sentido, o livro de Edmar Ferreira Santos atinge uma meta que qualquer pesquisa em história social pode almejar: a de nos permitir compreender em detalhe a complexidade do passado para, através dele, iluminar os paradoxos do presente (trecho retirado do Prefácio do livro).', '["Candomblé","Afro-Brazilian religions","religious persecution","religious resistance","Recôncavo Baiano","Afro-Brazilian heritage","religious intolerance","social history of religion","Bahia"]', '10.7476/9788523212100', '9788523208967', 'https://books.scielo.org/id/nq', 'https://books.scielo.org/id/nq/pdf/santos-9788523212100.pdf', NULL, 'https://books.scielo.org/id/nq/cover/cover_thumbnail.jpeg', NULL, 33, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-nqdxq', 'nqdxq', 'Breve história da vida e morte de Anísio Teixeira: desmontada a farsa da queda no fosso do elevador', NULL, '["João Augusto de Lima Rocha"]', 'EDUFBA', 'Brasil', 'SciELO Books', 'books', 2019, '2019-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'A obra objetiva demonstrar que o educador Anísio Teixeira não morreu em consequência de um acidente. O autor defende, de forma precisa e minuciosa, que a causa da morte não foi uma queda em fosso de elevador, como divulgado oficialmente, e que é muito provável a hipótese de ele ter sido assassinado por razões políticas. Além de justificar o porquê de a ditadura militar desejar eliminar uma pessoa como Anísio Teixeira, o livro ainda analisa a obra do educador baiano, revelando ser, apesar de breve, uma importante biografia.', '["Anísio Teixeira","assassination","death investigation","military dictatorship","political persecution","history of education in Brazil"]', '10.7476/9786556301761', '9786556301761', 'https://books.scielo.org/id/nqdxq', 'https://books.scielo.org/id/nqdxq/pdf/rocha-9786556301761.pdf', NULL, 'https://books.scielo.org/id/nqdxq/cover/cover_thumbnail.jpeg', NULL, 4, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-nqrrs', 'nqrrs', 'Comunicação e trabalho infantil doméstico: política, poder, resistências', NULL, '["Danila Cal"]', 'EDUFBA', 'Brasil', 'SciELO Books', 'books', 2016, '2016-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Este livro difere de estudos voltados para a face mais evidente do conceito de poder – isto é, o poder como dominação. Para compreender de que forma o trabalho infantil doméstico é configurado como problema político, o livro analisa criticamente a definição de poder, tomado também como possibilidade de empoderamento, resistência e construção de solidariedade. Esse percurso argumentativo orienta o exame da conversação pública sobre o trabalho infantil doméstico presente nos media e das discussões e depoimentos de trabalhadores e ex-trabalhadores infantis domésticas, reunidos a partir da realização de grupos focais. Destina-se a pesquisadores e estudantes das áreas de Comunicação, Sociologia e Ciência Política, além de profissionais de instituições públicas e não-governamentais interessados nas relações entre poder, comunicação e política, trabalho doméstico, trabalho infantil e ações de advocacy.', '["power","empowerment","resistance","solidarity","public communication","media discourse","advocacy","domestic workers"]', '10.7476/9788523218706', '9788523218706', 'https://books.scielo.org/id/nqrrs', 'https://books.scielo.org/id/nqrrs/pdf/cal-9788523218706.pdf', NULL, 'https://books.scielo.org/id/nqrrs/cover/cover_thumbnail.jpeg', NULL, 8, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-nr24h', 'nr24h', 'Desenvolvimento e conflitos ambientais', NULL, '["Andréa Zhouri","Klemens Laschefski"]', 'Editora UFMG', 'Brasil', 'SciELO Books', 'books', 2010, '2010-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Esta coletânea aborda temas como eficiência de políticas participativas, biocombustíveis, conflitos territoriais envolvendo povos indígenas, grupos tradicionais e quilombolas, expansão agrícola e projetos industriais na Amazônia, consequências do uso dos agrotóxicos, pesca artesanal, monocultura do camarão, hidrelétricas e conflitos sobre a água e saneamento e conflitos territoriais no espaço urbano. Dessa forma, os autores pretendem destacar a importância da investigação de conflitos ambientais para a consolidação da Ecologia Política na Academia Brasileira.', '["environmental conflicts","participatory policy","biofuels","indigenous peoples","quilombola communities","traditional communities","agricultural expansion","agrotoxins","small-scale fisheries","hydroelectric dams","water conflicts","sanitation"]', '10.7476/9788542303063', '9788570417749', 'https://books.scielo.org/id/nr24h', NULL, NULL, 'https://books.scielo.org/id/nr24h/cover/cover_thumbnail.jpeg', 484, 185, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-nr5wx', 'nr5wx', 'Encontros e desencontros de lá e de cá do Atlântico: mulheres africanas e afro-brasileiras em perspectivas de gênero', NULL, '["Patrícia Godinho Gomes","Cláudio Alves Furtado"]', 'EDUFBA', 'Brasil', 'SciELO Books', 'books', 2017, '2017-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'O título aborda temas de gênero no contexto da África Subsaariana e do nordeste do Brasil, e foi estruturado pela necessidade de repensar e questionar algumas das concepções eurocêntricas no âmbito do estudo sobre mulheres e gênero, e reavaliar a eficácia da sua aplicabilidade nessas realidades. A partir da análise dessas, a obra procura possíveis formas de diálogo entre as experiências das mulheres africanas e afro-brasileiras, e busca proporcionar ao leitor uma visão mais ampla e articulada dos processos históricos nessas realidades “(in)distintas” do continente africano e do Brasil.', '["African women","Afro-Brazilian women","gender","sub-Saharan Africa","Northeast Brazil","Eurocentrism","transatlantic relations","women''s history","comparative gender studies"]', '10.7476/9788523217310', '9788523215866', 'https://books.scielo.org/id/nr5wx', NULL, NULL, 'https://books.scielo.org/id/nr5wx/cover/cover_thumbnail.jpeg', 307, 1, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-nrd7d', 'nrd7d', 'Percursos de um arte-educador: a arte de se constituir educador nas práticas de ensino de teatro com crianças', NULL, '["Francisco Souza da Silva","Theda Cabrera"]', 'Editora UNESP', 'Brasil', 'SciELO Books', 'books', 2022, '2022-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'Neste livro, o autor apresenta um estudo etnográfico sobre práticas de ensino das artes cênicas e as transformações na organização e na orientação dos encontros de ensino, a partir da perspectiva de processo de ensino de Paulo Freire. O autor procura refletir sobre práticas de ensino de teatro para crianças, considerando os contextos e os conflitos que permeiam o caminhar da docência.', '["theatre teaching","children","art teachers","Paulo Freire","teaching process","art education","teaching practice","teacher identity"]', '10.7476/9786559542475', '9786559542475', 'https://books.scielo.org/id/nrd7d', 'https://books.scielo.org/id/nrd7d/pdf/silva-9786559542475.pdf', NULL, 'https://books.scielo.org/id/nrd7d/cover/cover_thumbnail.jpeg', NULL, 1, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-nssyz', 'nssyz', 'Deus salve a rainha e evite engarrafamentos: textos de jornalismo cultural', NULL, '["Ademir Assunção"]', 'Editora Universidade de Brasília', 'Brasil', 'SciELO Books', 'books', 2021, '2021-06-29', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', '“Muito se fala em “jornalismo literário”, como se a segunda condição tornasse a primeira mais nobre, e como se a primeira ajudasse a segunda a se tornar mais “popular”, coloquial. Não parece algo que tire o sono de Ademir Assunção: ele não concebe a escrita a partir de um cânone, de uma idealização, de uma vontade externa, mas de sua própria inquietação. Ele também não teme a verdade — e ele a busca em qualquer lugar, seja no morro com Bezerra da Silva, seja caminhando pelas ruas de Porto Alegre a bordo de Mário Quintana. Ademir também escreve ficção, e os pressupostos — não as ferramentas — são parecidos com os de seu jornalismo. Em janeiro de 2004, com Adorável criatura Frankenstein, esculachava os ritos de legitimação de ídolos, marqueteiros, intelectuais e modelos-atrizes-apresentadoras do circo midiático brasileiro. Ele parece crer que a literatura (e também o jornalismo) age no mundo, muda o mundo e não está aí para fixar ou cristalizar as convicções, mas para sacudi-las, abalá-las, estremecer a árvore dos fetiches. O poeta beatnik Gary Snyder disse, certa vez, que a poesia é como um grande corvo sentado num fio de alta tensão, entre dois postes. “Ninguém presta atenção nela, mas ela vê tudo.” O jornalismo cultural praticado pelo Ademir é como aquele corvo do Snyder. Está lá, em todos os fios, com seu olhar escrutador. Os farsantes vão ficando pelos meios fios. Assunção vai enchendo todos os fios.”', '["cultural journalism","literary journalism","literary canon","truth in journalism","journalism and fiction","Porto Alegre"]', '10.7476/9786558460565', '9786558460114', 'https://books.scielo.org/id/nssyz', NULL, NULL, 'https://books.scielo.org/id/nssyz/cover/cover_thumbnail.jpeg', 354, 2, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-ntbn4', 'ntbn4', 'Pesquisas em gramática funcional: descrição do português', NULL, '["Erotilde Goreti Pezatti"]', 'Editora UNESP', 'Brasil', 'SciELO Books', 'books', 2009, '2009-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'Esta coletânea traz um conjunto de textos baseados em dissertações de alunos do Programa de Pós-Graduação em Estudos Lingüísticos da UNESP, campus de São José do Rio Preto, da área de Descrição e Análise Lingüística, que tratam da aplicação do modelo da Gramática Funcional Padrão ao português oral e escrito. Os autores integram o Grupo de Pesquisa em Gramática Funcional (GPGF), que tem se destacado nacional e internacionalmente como um dos grupos funcionalistas mais atuantes na área. O livro pretende não só divulgar esse modelo teórico como também mostrar sua eficácia na descrição lingüística, além de constituir a primeira obra em português a mostrar a contribuição dessa teoria para a descrição da língua portuguesa.', '["functional grammar","Portuguese language","written Portuguese","language description","Portuguese grammar"]', '10.7476/9788539304448', '9788571399730', 'https://books.scielo.org/id/ntbn4', NULL, NULL, 'https://books.scielo.org/id/ntbn4/cover/cover_thumbnail.jpeg', 383, 1, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-ntjdk', 'ntjdk', 'Parto natural, parto humanizado: perspectivas de mulheres de camadas populares e médias', NULL, '["Olívia Nogueira Hirsch"]', 'Editora FIOCRUZ', 'Brasil', 'SciELO Books', 'books', 2019, '2019-01-01', 'pt', 'book', 'medical-health', 'Ciencias Médicas y de la Salud', 'Medicine', 'Resultado de pesquisa para a realização de tese de doutorado da autora Olivia Hirsch, o livro Parto Natural, Parto Humanizado: perspectivas de mulheres de camadas populares e médias se debruça sobre experiências de parto humanizado em dois diferentes segmentos sociais de uma metrópole do Brasil. Em um paí­s que dissemina amplamente a prática de cesáreas agendadas, por que certas mulheres de camadas médias desejam um parto natural e humanizado, sem anestesias ou outros tipos de intervenção? Por outro lado, por que algumas mulheres de camadas populares abrem mão do atendimento por médicos e preferem ser atendidas exclusivamente por enfermeiras e obstetras? Ao buscar responder a essas e outras questões, a pesquisadora investigou - a partir de um universo composto de 37 gestantes e puérperas - mulheres sob diferentes contextos: das vinculadas a uma casa de parto pública às frequentadoras de um grupo de preparação para o parto. Jornalista de formação, Hirsch é doutora pelo Programa de Pós-Graduação em Ciências Sociais da Pontifí­cia Universidade Católica do Rio de Janeiro (PUC-Rio), instituição na qual é docente do quadro complementar do Departamento de Ciências Sociais. A publicação em livro de sua tese de doutorado contribui, segundo a pesquisadora Sonia Giacomini afirma na apresentação da obra, para "todas que lutam para desnaturalizar as relações de gênero e de classe em que estão envolvidas, as quais muitas vezes tornam desigual o acesso à possibilidade de decidir que tipo de parto cada mulher deseja realizar".', '["natural childbirth","humanized childbirth","childbirth experience","social class","popular classes","middle class","cesarean section","obstetric surgery","midwifery care","pregnant women","postpartum women","gender relations"]', '10.7476/9786557080580', '9788575416372', 'https://books.scielo.org/id/ntjdk', NULL, NULL, 'https://books.scielo.org/id/ntjdk/cover/cover_thumbnail.jpeg', 401, 3, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-ntykr', 'ntykr', 'Viver e morrer em São Paulo: imigração, saúde e infraestrutura urbana (século XIX até o presente)', 'imigração, saúde e infraestrutura urbana (século XIX até o presente)', '["Jeffrey Lesser"]', 'Editora UNESP', 'Brasil', 'SciELO Books', 'books', 2025, '2025-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'Este livro revela como a o passado e o presente da saúde pública estão entrelaçados com questões raciais e estigmas de classe. Trata-se de um estudo meticuloso e urgente, que mostra como a desigualdade não é um acaso, mas um projeto inscrito na própria infraestrutura que nos cerca. Com uma análise que põe em diálogo constantemente o passado e o presente, Jeffrey Lesser examina como as visões de saúde do Estado — expressas em instituições como a antiga Polícia Médica ou em ações de vigilância sanitária — muitas vezes entraram em conflito com as experiências e resistências de imigrantes. O autor revela os “resíduos” materiais, legislativos e sociais que o tempo não apagou, mostrando como legados históricos continuam a moldar os resultados de saúde na metrópole contemporânea.', '["history of public health","immigration","urban infrastructure","São Paulo","racial inequality","medical police","sanitary surveillance","health disparities","historical legacy","urban health"]', '10.7476/9786557146361', '9786557112786', 'https://books.scielo.org/id/ntykr', 'https://books.scielo.org/id/ntykr/pdf/lesser-9786557146361.pdf', NULL, 'https://books.scielo.org/id/ntykr/cover/cover_thumbnail.jpeg', NULL, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-nv4nc', 'nv4nc', 'Os parasitas de ovinos', NULL, '["Alessandro Francisco Talamini do Amarante"]', 'Editora UNESP', 'Brasil', 'SciELO Books', 'books', 2014, '2014-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Immunology and Microbiology', 'Piolhos e ácaros 253 APRESENTAÇÃOEste livro apresenta informações sobre as principais parasitoses que acometem ovinos criados no Brasil e tem por objetivo fornecer subsídios para a elaboração de estratégias de profilaxia das enfermidades parasitárias.Trabalhos relevantes realizados por pesquisadores brasileiros, bem como de outros países, foram imprescindíveis como fonte de consulta para a elaboração dos textos.Aqui também estão apresentados os resultados obtidos no Laboratório de Helmintologia Veterinária, especialmente a partir de 1988, quando o autor deste livro iniciou suas atividades na Unesp, campus de Botucatu.Desde aquela data, várias dissertações e teses foram elaboradas por estudantes de pós-graduação, cujos resultados estão a seguir apresentados.A maioria das fotografias apresentadas no livro foi obtida pelo próprio autor, com a colaboração de alunos e técnicos do Departamento de Parasitologia; porém, merece destaque o inestimável auxílio prestado pelo pós-graduando César Cristiano Bassetto na colheita de material e montagem de lâminas. HELMINTOS INTRODUÇÃOOs helmintos são classificados em dois grandes grupos, denominados filos: Nemathelminthes e Platyhelminthes.O primeiro grupo é constituído por vermes que apresentam o corpo cilíndrico, enquanto que no segundo grupo os vermes apresentam o corpo achatado dorso-ventralmente.Os principais gêneros de helmintos com as suas respectivas classificações estão apresentados na Tabela 1. Três classes de parasitas se destacam: Nematoda, Cestoda e Trematoda, as quais serão abordadas separadamente.', '["sheep parasites","nematodes","cestodes","trematodes","helminths","sheep lice"]', '10.7476/9788568334423', '9788568334423', 'https://books.scielo.org/id/nv4nc', 'https://books.scielo.org/id/nv4nc/pdf/amarante-9788568334423.pdf', NULL, 'https://books.scielo.org/id/nv4nc/cover/cover_thumbnail.jpeg', NULL, 41, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-nvnjd', 'nvnjd', 'Aplicações de química teórica no estudo de materiais: métodos in silico para nanomateriais', NULL, '["Luiz Carlos Gomide Freitas","Guedmiller S. Oliveira"]', 'EdUFSCar', 'Brasil', 'SciELO Books', 'books', 2018, '2018-01-01', 'pt', 'book', 'natural-sciences', 'Ciencias Naturales y Exactas', 'Physics and Astronomy', 'A aplicação da química teórica no estudo de materiais é apresentada neste livro na forma de capítulos que dispõem o conteúdo embasado nas pesquisas científicas realizadas por renomados pesquisadores brasileiros. O intuito desta obra é divulgar a aplicabilidade de metodologias computacionais na interpretação e ou previsão de processos físico-químicos relevantes no estudo de materiais. Desta forma, pesquisadores poderão se inteirar das potencialidades oferecidas pelas metodologias computacionais e como estes métodos podem agregar valor as suas respectivas linhas de atuação. Ademais, esta divulgação poderá impactar de forma positiva nas relações entre pesquisadores teóricos e experimentais para o estabelecimento de pesquisas mais colaborativas e de ponta.', '["theoretical chemistry","materials science","nanomaterials","in silico analysis","computational chemistry"]', '10.7476/9786580216123', '9786580216123', 'https://books.scielo.org/id/nvnjd', 'https://books.scielo.org/id/nvnjd/pdf/freitas-9786580216123.pdf', NULL, 'https://books.scielo.org/id/nvnjd/cover/cover_thumbnail.jpeg', NULL, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-nw2rh', 'nw2rh', 'Agroclimatología del Ecuador', NULL, '["Fredi Leonidas Portilla Farfán"]', 'Editorial Abya-Yala', 'Ecuador', 'SciELO Books', 'books', 2018, '2018-01-01', 'es', 'book', 'natural-sciences', 'Ciencias Naturales y Exactas', 'Environmental Science', 'La climatología indudablemente es una ciencia aplicable a todas las áreas del conocimiento y en este caso de enorme trascendencia para el área de la Ingeniería Agronómica, Ambiental y afines. El presente trabajo constituye una aproximación a la climatología del Ecuador continental e insular en base de datos oficiales que propende servir a futuro para estudios de aplicación en el área de ciencias de la vida. Los estudios relativos al clima del Ecuador regularmente han estado enfocados al sector turístico, área importante de desarrollo; sin embargo es menester estructurar una climatología que tenga aplicación en el área agropecuaria y ambiental, fuente de autoconsumo y de generación de divisas. No se encuentra, sin embargo, una climatología estadística sistemática del Ecuador que permita situarse con una cierta amplitud en el contexto de un estudio climático del conjunto del país. A partir de datos oficiales proporcionados por el INAMHI (Instituto Nacional de Meteorología e Hidrología del Ecuador), el presente trabajo tiene como objetivo formular una climatología estadística básica que nos permita afrontar trabajos más específicos posteriormente.', '["agroclimatology","agrometeorology"]', '10.7476/9789978104927', '9789978104927', 'https://books.scielo.org/id/nw2rh', 'https://books.scielo.org/id/nw2rh/pdf/portilla-9789978104927.pdf', NULL, 'https://books.scielo.org/id/nw2rh/cover/cover_thumbnail.jpeg', NULL, 16, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-nw44n', 'nw44n', 'Entre o roçado e a Coca-Cola: uma sociobiografia', NULL, '["Priscila de Oliveira Coutinho"]', 'Editora UFMG', 'Brasil', 'SciELO Books', 'books', 2022, '2022-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Este livro oferece uma rota possível para se pensar um tema central na sociologia: uma trajetória improvável se constitui de um conjunto de acasos misteriosamente orquestrados ou possui uma lógica cujos traços podem ser reconstituídos pelas ciências sociais? Juscelina, uma migrante paraibana e trânsfuga de classe, então executiva de uma multinacional, vive o instável momento em que se fecha um ciclo de vida; Priscila, a pesquisadora, acompanha as grandes mudanças que transcorrem esta fase. A sociobiografia que o leitor tem em mãos busca nas estruturas sociais, nas relações familiares, laborais e de amizade, assim como nos conflitos intraindividuais, as causas dos movimentos mais determinantes da vida de Juscelina, cuja problemática existencial se forma nas tensões entre os traços estruturais e relacionais de sua origem e aqueles dos contextos frequentados na vida adulta. O exame dessas e de muitas outras questões resulta num original exercício de imaginação sociológica, em que a objetivação de uma relação etnográfica que vai se transformando em amizade articula-se a estratégias metodológicas bem fundamentadas, rico material empírico e competente atividade interpretativa.', '["life trajectories","sociobiography","life course","social mobility","migrant women","family relationships","workplace relationships","friendship","life transitions","sociological imagination"]', '10.7476/9786558580874', '9788542303230', 'https://books.scielo.org/id/nw44n', NULL, NULL, 'https://books.scielo.org/id/nw44n/cover/cover_thumbnail.jpeg', 462, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-nxq2k', 'nxq2k', 'Histórias de Salvador nos nomes das suas ruas', NULL, '["Luiz Eduardo Dórea"]', 'EDUFBA', 'Brasil', 'SciELO Books', 'books', 2006, '2006-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Salvador esconde em seu desordenado contexto urbano, o histórico passado daquela que foi a primeira capital do Brasil. Dentro dos seus limites primitivos, demarcou-se uma praça central e dela partiram as poucas vias à epoca necessárias ao trânsito de pessoas e mercadorias. Cada um desses logradouros recebeu o seu próprio batismo, muitos dos quais ainda hoje se encontram em uso. A pesquisa reunida nesse livro resgata a memória de fatos, acontecimentos e personagens cuja existencia e realidade históricas acham-se registradas nas placas de endereçamento afixadas nas esquinas.', '["Salvador, Bahia","street names","urban history","historical memory","historical plaques","colonial capital","historical figures","historical events"]', '10.7476/9788523208738', '9788523203986', 'https://books.scielo.org/id/nxq2k', NULL, NULL, 'https://books.scielo.org/id/nxq2k/cover/cover_thumbnail.jpeg', 450, 19, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
